window.JASTROW_CHUNKS[57]={"22800":{"h":"פַּלִּיָא","r":"Q01040","html":"<div class=\"sense\"><i>old</i>, v. <a href=\"#\" data-headword=\"פַּלִּיָיא\">פַּלִּיָיא</a>.</div>","alt":["פַּלִּיאָה"]},"22801":{"h":"פְּלִיאָה","r":"Q01041","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>hidden thing, secret; miracle</i>. Y. Ḥag. III, 77ᶜ top (fr. Ben Sira) <span dir=\"rtl\">פ׳ ממך מה תדע</span> why wilt thou attempt to know what is hidden from thee? (v. <a href=\"#\" data-headword=\"מוּפְלָא\">מוּפְלָא</a>). <span class=\"citation\">Midr. Till. to Ps. CXIX, 18</span> (ref. to <span class=\"citation\">Ps. CXXXIX, 6</span>) <span dir=\"rtl\">פ׳ זו התוֹרה</span> ‘the secret’, that means the Law. <span class=\"citation\">Num. R. s. 10</span> (ref. to <a href=\"#\" data-headword=\"פֶּלִאי\">פלאי</a>, <span class=\"citation\">Jud. XIII, 18</span>) <span dir=\"rtl\">לפי פ׳ ופ׳ וכ׳</span> according to each miracle that he (the Lord) performs through us (angels), he names us.</div>","alt":[]},"22802":{"h":"פְּלֵיג","r":"Q01042","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלַג I\"><span dir=\"rtl\">פְּלַג</span> I</a></div>","alt":["פְּלִיג"]},"22803":{"h":"פְּלִיגָא I","r":"Q01043","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּלַג I\">פְּלַג</a>) </div><div class=\"sense\"><b>1)</b> <i>division, discord</i>. <span class=\"citation\">Num. R. s. 18</span> (ref. to <span class=\"citation\">Num. XVI, 1</span>) <span dir=\"rtl\">אין ויקח אלא לשון פ׳</span> ‘and he took away’ has the meaning of division.</div><div class=\"sense\"><b>—2)</b> <i>portion</i>, v. <a href=\"#\" data-headword=\"פְּלַג II\">פַּלְגָּא</a>.</div>","alt":[]},"22804":{"h":"פְּלִיגָא II","r":"Q01044","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Mount P’liga</i> (<i>Division</i>). <span class=\"citation\">Targ. Josh. XI, 17</span> (h. text <span dir=\"rtl\">ההר החלק</span>).</div>","alt":["טוּרָא פ׳"]},"22805":{"h":"פַּלְיוּם","r":"Q01045","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (pallium, πάλλιον) <i>sheet, blanket; mantle</i>. <span class=\"citation\">Nidd. VIII, 1</span>, v. <a href=\"#\" data-headword=\"אַפַּלְיוֹן\">אַפַּלְיוֹן</a>. Y. Sabb. XVI, 15ᵈ top <a href=\"#\" data-headword=\"פִּילוֹן\">פיליון</a> (corr. acc.); Bab. <span class=\"citation\">Sabb. 120ᵃ</span> <a href=\"#\" data-headword=\"אפיליות\">אפיליות</a> (corr. acc., v. <a href=\"#\" data-headword=\"אַפַּלְיוֹן\">אַפַּלְיוֹן</a>). <span class=\"citation\">Y. Ber. II, 4ᶜ</span> bot. <span dir=\"rtl\">מעבר ליה בפיליוס</span> (corr. acc.) put a sheet over it; a. e.—Pl. <span dir=\"rtl\">פַּלְיוֹנוֹת</span>. Sifra M’tsorʿa, Neg., Par. 7, ch. V אפי הוא לבוש … ועטוף עשרה פ׳ Rabad (ed. <a href=\"#\" data-headword=\"פולייוניות\">פולייוניות</a>, corr. acc.) even if he is clothed …, and wrapped in ten pallia.</div>","alt":["פַּלְיוֹן"]},"22806":{"h":"פליון","r":"Q01046","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to VI, 1</span>, v. <a href=\"#\" data-headword=\"פִּילוֹן\">פִּילּוֹן</a></div>","alt":[]},"22807":{"h":"פְּלִיזָא","r":"Q01047","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. Arab. <i>falaz</i>) <i>bronzed</i> or <i>gilt</i>. <span class=\"citation\">B. Kam. 113ᵇ</span> זבין לקנא … במר די פ׳ Ms. M. (Ar. <span dir=\"rtl\">בכלל דפ׳</span>; ed. <span dir=\"rtl\">דפרזלא</span>, corr. acc.; v. Rabb. D. S. a. l. note) bought a flask of solid gold for plated ware.</div>","alt":[]},"22808":{"h":"פָּלֵיט","r":"Q01048","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פָּלֵט\">פָּלֵט</a></div>","alt":[]},"22809":{"h":"פָּלִיט","r":"Q01049","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>one that escaped, survivor</i>. <span class=\"citation\">Snh. 105ᵇ</span> <span dir=\"rtl\">שריד ופ׳</span> remnant or survivor. <span class=\"citation\">Gen. R. s. 42</span> הוא עוג הוא פ׳ Og and ‘he that had escaped’ (<span class=\"citation\">Gen. XIV, 13</span>) are the same person; a. e.—Pl. <a href=\"#\" data-headword=\"פְּלֵיטִית\">פְּלֵיטִים</a>, <a href=\"#\" data-headword=\"פלטים\">פְּלֵטִים</a>, v. <a href=\"#\" data-headword=\"פָּלֵט\">פָּלֵט</a>.</div>","alt":[]},"22810":{"h":"פליטה","r":"Q01050","html":"<div class=\"sense\">, <span class=\"citation\">Y. Taan. IV, 68ᵇ</span> top, v. <a href=\"#\" data-headword=\"פְּלִיפָּא\">פְּלִיפָּא</a></div>","alt":[]},"22811":{"h":"פְּלֵיטָה","r":"Q01051","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>escape, safety; remnant</i>. <span class=\"citation\">Gen. R. s. 76</span> [read:] <span dir=\"rtl\">אע&quot;פ שנשארו לפ׳ הֱיוּ מתענין עליהן וכ׳</span> (v. <span class=\"citation\">Yalk. ib. 131</span>) although they (in the diaspora) have been allowed to escape (from the persecutions in Palestine), yet fast (and pray) for them &amp;c. <span class=\"citation\">Gen. R. s. 38</span> <span dir=\"rtl\">נשתיירה מהן פ׳</span> a remnant of them was left; a. e.</div>","alt":["פְּלֵטָה"]},"22812":{"h":"פֹּלְיָטוֹן","r":"Q01052","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פּוֹלְיָיטוֹן\">פּוֹלְיָיטוֹן</a></div>","alt":[]},"22813":{"h":"פליטורין","r":"Q01053","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְטֵר\">פַּלְטֵרָא</a></div>","alt":[]},"22814":{"h":"פְּלֵיטִיאַת","r":"Q01054","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלַטְיָא\">פְּלַטְיָא</a> ch.</div>","alt":[]},"22815":{"h":"פליטין","r":"Q01055","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פּוֹלְיָיטוֹן\">פּוֹלְיָיטוֹן</a></div>","alt":[]},"22816":{"h":"פְּלֵיטִית","r":"Q01056","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"><i>P’leṭith</i>, name of a Sodomite woman who, according to a legend, was put to death for feeding a poor family (v. <span class=\"citation\">Gen. R. s. 49</span>). <span class=\"citation\">Targ. Y. I Gen. XVIII, 21</span>; <span class=\"citation\">Pirké d’R. El. ch. XXV</span> פלוטית וכ׳ P. daughter of Lot; <span class=\"citation\">Yalk. Gen. 83</span> <a href=\"#\" data-headword=\"פְּלֵטַת\">פְּלֵטַת</a>.</div>","alt":[]},"22817":{"h":"פְּלֵיטַר","r":"Q01057","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְטֵר II\"><span dir=\"rtl\">פַּלְטֵר</span> II</a></div>","alt":[]},"22818":{"h":"פַּלִּיָיא","r":"Q01058","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (παλαιά) <i>old</i>. <span class=\"citation\">Lev. R. s. 33</span> (not <span dir=\"rtl\">פיל׳</span>; Ar. <span dir=\"rtl\">פליאה</span>), v. <a href=\"#\" data-headword=\"בְּלֵי I\"><span dir=\"rtl\">בְּלֵי</span> I</a>; Yalk. Dan. 1061 <span dir=\"rtl\">פליא</span>. <span class=\"citation\">Cant. R. to III, 4</span> <a href=\"#\" data-headword=\"פילא\">פילאי</a> (corr. acc.), v. <a href=\"#\" data-headword=\"*באמי\">באמי</a>.</div>","alt":["פַּלִּיָיאָה"]},"22819":{"h":"פָּלְיַית","r":"Q01059","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> constr. (<a href=\"#\" data-headword=\"פְּלֵי\">פְּלֵי</a>) <i>searcher</i>; <span dir=\"rtl\">פ׳ חֵיוָא</span> <i>hedgehog</i>. <span class=\"citation\">Targ. Y. Lev. XI, 30</span> Ar. (Var. <a href=\"#\" data-headword=\"פְּיַילְתָּא\">פַּיְילַת</a>, fr. <a href=\"#\" data-headword=\"*פּוּל\">פּוּל</a>; ed. <span dir=\"rtl\">מינקת חויא</span>), v. <a href=\"#\" data-headword=\"יָילָא\">יָילָא</a>. Y’lamd. to Num. XXII, 29, quot. in Ar. (Tanḥ. Balak 9 <a href=\"#\" data-headword=\"נְאָקָה II\">אנקה</a>).</div>","alt":[]},"22820":{"h":"פָּלִיל","r":"Q01060","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">פְּלִילִים</span>(b. h.; <i>arbitration; arbiters, judges</i>. Mekh. Mishp., s. 8 אין פ׳ אלא דיינין <i>p’lilim</i> (<span class=\"citation\">Ex. XXI, 22</span>) means judges.</div>","alt":[]},"22821":{"h":"פְּלִילָה","r":"Q01061","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"פָּלִיל\">preced.</a>) <i>argument, plea; decision, judgment</i>. <span class=\"citation\">Snh. 111ᵇ</span> (ref. to <a href=\"#\" data-headword=\"פְּלִילִיָּה\">פליליה</a>, <span class=\"citation\">Is. XXVIII, 7</span>) <span dir=\"rtl\">אין פ׳ אלא דיינים</span> <i>p’lilah</i> means the verdict of judges; <span class=\"citation\">Yalk. Is. 302</span>; <span class=\"citation\">Meg. 15ᵇ</span>, v. next w.—Pl. <span dir=\"rtl\">פְּלִילוֹת</span>. <span class=\"citation\">Snh. 44ᵃ</span> (ref. to <span dir=\"rtl\">ויפלל</span>, <span class=\"citation\">Ps. CVI, 30</span>) <span dir=\"rtl\">עשה פ׳ עם קונו</span> he pleaded with his Maker; ib. 82ᵇ; <span class=\"citation\">Yalk. Ps. 865</span>; a. e.</div>","alt":[]},"22822":{"h":"פְּלִילִיָּה","r":"Q01062","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <a href=\"#\" data-headword=\"פְּלִילָה\">same</a>. <span class=\"citation\">Meg. 15ᵇ</span> אין פ׳ אלא משפט Ms. M. (ed. <span dir=\"rtl\">אין פ׳ אלא דיינין</span>; some ed. <a href=\"#\" data-headword=\"פְּלִילָה\">פלילה</a>, v. <a href=\"#\" data-headword=\"פְּלִילָה\">preced.</a>) <i>p’liliyyah</i> means verdict.</div>","alt":[]},"22823":{"h":"פְּלִימוֹ","r":"Q01063","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>P’limo</i>, name of a Tannai. <span class=\"citation\">Pes. 8ᵇ</span>. <span class=\"citation\">Men. 37ᵃ</span>. <span class=\"citation\">Sot. 4ᵃ</span>, v. <a href=\"#\" data-headword=\"פְּנִימוֹן\">פְּנִימוֹן</a>.</div>","alt":[]},"22824":{"h":"פליניא","r":"Q01064","html":"<div class=\"sense\">, <span class=\"citation\">Ned. 55ᵇ</span>, v. <a href=\"#\" data-headword=\"פִּמְלַנְיָא\">פִּמְלַנְיָא</a></div>","alt":[]},"22825":{"h":"פלינקרא","r":"Q01065","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּילוֹנִיקְיָא\">פִּילוֹנִיקְיָא</a></div>","alt":["פלינקריא"]},"22826":{"h":"פליסופוס","r":"Q01066","html":"<div class=\"sense\">, <span class=\"citation\">Sifré Deut. 307</span>; <span class=\"citation\">Yalk. Deut. 942</span> <span dir=\"rtl\">פילוסופ׳</span>, name of a Roman officer who condemned R. Ḥanania to be burnt with the book of the Law.</div>","alt":[]},"22827":{"h":"פליספוס","r":"Q01067","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלוֹסְלוֹס I\">פְּלוֹסְלוֹס</a></div>","alt":[]},"22828":{"h":"פְּלִיפָּא","r":"Q01068","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (philippus, Philippi) <i>Plippa, Pilippi, Pilpi</i>, name of an Amora. <span class=\"citation\">Y. Taan. IV, 68ᵇ</span> top (ed. Krot. <a href=\"#\" data-headword=\"פליטה\">פליטה</a>, corr. acc.). <span class=\"citation\">Y. Meg. IV, 75ᵃ</span> bot. <span dir=\"rtl\">פילפי</span>.—<span class=\"citation\">Gen. R. s. 71</span> <span dir=\"rtl\">פליפי</span>; <span class=\"citation\">Yalk. Kings 208</span> <a href=\"#\" data-headword=\"*פפי\">פפי</a>.</div>","alt":["פְּלִיפָּה","פִּילִיפִּי","פִּילְפִּי"]},"22829":{"h":"פליריכוס","r":"Q01069","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Deut. 813</span>, a corrupt., v. <a href=\"#\" data-headword=\"*קלידיקוס\">קלידיקוס</a></div>","alt":["פלירכוס"]},"22830":{"h":"פֶּלֶךְ","r":"Q01070","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> פלך <i>to cut out, round</i>; cmp. <a href=\"#\" data-headword=\"פֶּלַח\">פֶּלַח</a>) [<i>circle</i>,] </div><div class=\"sense\"><b>1)</b> <i>district</i>. <span class=\"citation\">B. Bath. 21ᵃ</span> <span dir=\"rtl\">התקינו … בכל פ׳ ופ׳</span> they ordained that teachers must be appointed, one for each district. <span class=\"citation\">Macc. 7ᵃ</span>. <span class=\"citation\">Ib. 12ᵇ</span> <span dir=\"rtl\">בן לוי … גולה מפ׳ לפ׳ … לפִלְכוֹ פִּלְכוֹ קולט</span> a Levite (native of a place of refuge) who has killed a person accidentally flees from one district to another, but if he flees to his own native (juridical) district, his district protects him; <span class=\"citation\">Zeb. 117ᵃ</span>; <span class=\"citation\">Yalk. Ex. 323</span>; a. fr.—Pl. <span dir=\"rtl\">פְּלָכִים</span>, <a href=\"#\" data-headword=\"פלכין\">פְּלָכִין</a>. <span class=\"citation\">Tosef. Bicc. II, 8</span> <span dir=\"rtl\">לא … יחידים אלא פ׳ פ׳</span> they did not go up (to Jerusalem, with the first-fruits) singly, but by districts.</div><div class=\"sense\"><b>—2)</b>  [<i>ball of tow, wool</i> &amp;c.,] <i>distaff</i> or <i>spindle</i>. <span class=\"citation\">Keth. IX, 4</span> (<span class=\"citation\">86ᵇ</span>) <span dir=\"rtl\">על פִּילְכָהּ ועל עיסתה</span> a husband may administer an oath to his wife on her distaff (on what she spins or weaves) and on her dough. <span class=\"citation\">Yoma 66ᵇ</span> (in answer to a woman’s question) <span dir=\"rtl\">אין חכמה לאשה אלא בפ׳</span> there is no wisdom for woman except at the distaff. <span class=\"citation\">Gen. R. s. 56</span>, end <span dir=\"rtl\">לאשה שנתעשרה מפִּלְכָהּ … ומן הפ׳ הזה וכ׳</span> (Ar. <span dir=\"rtl\">מפלחה … הפלח</span>) like a woman that became rich through her distaff (or spindle, spinning or weaving), and she says, since I have become rich through this distaff (spindle), it shall not part from &amp;c.; a. fr.—Trnsf. <i>vocation, duty</i>. <span class=\"citation\">Gen. R. s. 71</span>, v. <a href=\"#\" data-headword=\"הוֹדָאָה\">הוֹדָאָה</a>; <span class=\"citation\">ib.</span> <span dir=\"rtl\">רחל תפסה פ׳ שתיקה</span> Rachel made silence her duty (not to betray her sister when she was substituted for her); Midr. Sam. ch. XXVIII; a. e.—<span dir=\"rtl\">מחזיק בפ׳</span> holding the distaff, <i>being like a woman, forced to stay home, lame</i>. Tanḥ. Masʿé 12 (expl. <span dir=\"rtl\">מחזיק בפ׳</span>, <span class=\"citation\">II Sam. III, 29</span>, among the curses that fell back on the house of David) <span dir=\"rtl\">שנעשה כאשה שאחזתו פודגרה</span> he (Asa) became like a woman, for podagra seized him; <span class=\"citation\">Snh. 48ᵇ</span>; <span class=\"citation\">Y. Kidd. I, 61ᵃ</span> bot. <span dir=\"rtl\">ומחזיק בפ׳ זה יואש</span> ‘and holding a distaff’, that means Joash (who was abused like a woman); a. e.</div>","alt":[]},"22831":{"h":"פֶּלֶךְ ²","r":"Q01071","html":"<div class=\"sense\"><b>1)</b> <i>district</i>. <span class=\"citation\">Targ. Deut. III, 4</span> constr. <a href=\"#\" data-headword=\"פְּלַךְ\">פְּלָךְ</a> (O. ed. Berl. <a href=\"#\" data-headword=\"פְּלַךְ\">פַּלַךְ</a>, ed. Vien. <span dir=\"rtl\">פָּלָךְ</span>). <span class=\"citation\">Targ. Esth. I, 22</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"פלכין\">פִּלְכִין</a>, <span dir=\"rtl\">פִּלְכַיָּא</span>, <a href=\"#\" data-headword=\"פְּגִימִין\">פִּי׳</a>. Ib. <span dir=\"rtl\">פִּילְכֵי מלכא</span> ed. Lag. (ed. Vien. <span dir=\"rtl\">פַּלְחֵי</span>, corr. acc.). <span class=\"citation\">Targ. Josh. XVII, 11</span> (ed. Wil. <a href=\"#\" data-headword=\"פָּלָטוֹרָא\">פַּלְ׳</a>). <span class=\"citation\">Targ. Koh. I, 12</span>. <span class=\"citation\">Targ. Cant. III, 11</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>distaff, spindle</i>. <span class=\"citation\">Keth. 72ᵇ</span> <span dir=\"rtl\">קא שדיא פִילְכָהּ וטווה וכ׳</span> casting the spindle and spinning &amp;c. (v. <a href=\"#\" data-headword=\"וְרַד\">וָרָד</a>); <span dir=\"rtl\">פסיקתיה לפילכה וכ׳</span> she broke (the thread of) her spindle and threw it away (as if it had accidentally slipped); <span dir=\"rtl\">אמרה עולם הב לי פִילְכָאִי</span> Ar. (ed. <span dir=\"rtl\">פלך</span>) she said, young man, hand me my spindle; <span class=\"citation\">Snh. 95ᵃ</span>; <span class=\"citation\">Yalk. Sam. 155</span>; a. e.—<span class=\"citation\">Meg. 14ᵇ</span> (prov.) <span dir=\"rtl\">אתתא בהדי שותא פילכא</span> (sub. <a href=\"#\" data-headword=\"שַׁדְיָא I\">שדיא</a>) a woman handles the shuttle while she talks, i.e. pursues two aims at a time; [Ar. s. v. <a href=\"#\" data-headword=\"שׁוּתָא I\">שותא</a>: <span dir=\"rtl\">פַּלְכָה</span> <i>spins</i>.]</div>","alt":["פִּלְכָא","פִּי׳"]},"22832":{"h":"פְּלַךְ","r":"Q01072","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"פֶּלֶךְ ²\">preced.</a>) <i>to spin</i>, v. <a href=\"#\" data-headword=\"פֶּלֶךְ ²\">preced.</a></div>","alt":[]},"22833":{"h":"פִּלְכָא","r":"Q01073","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֶּלֶךְ\">פֶּלֶךְ</a> ch.</div>","alt":[]},"22834":{"h":"פלכין","r":"Q01074","html":"<div class=\"sense\">, Tanḥ. Vaëra 14 <span dir=\"rtl\">בפ׳</span>, v. <a href=\"#\" data-headword=\"פִּילְקִין\">פִּילְקִין</a></div>","alt":[]},"22835":{"h":"פָּלַל","r":"Q01075","html":"<div class=\"sense\"> (b. h.) <i>to separate, divide</i>.</div><div class=\"sense\"><b>Pi. פִּילֵּל</b> <div class=\"sense\"><i>to arbitrate, intercede</i>; trnsf. <i>to pray</i>. <span class=\"citation\">Sabb. 55ᵇ</span> (ref. to <span dir=\"rtl\">פ̇ח̇ז̇</span>, <span class=\"citation\">Gen. XLIX, 4</span>) <span dir=\"rtl\">פִּ֗ילַּלְתָּה ח̇לתה ז̇רחה וכ׳</span> thou didst plead, thou didst pray, thy prayer rose &amp;c. </div></div><div class=\"sense\"><b>Hithpa. הִתְפַּלֵּל</b> </div><div class=\"sense\"><b>Nithpa. נִתְפַּלֵּל</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"תְּפִלָּה\">תְּפִלָּה</a>) <i>to pray</i>. <span class=\"citation\">Ber. V, 1</span> <span dir=\"rtl\">להִתְפַּלֵּל</span>, v. <a href=\"#\" data-headword=\"כּוֹבֶד\">כּוֹבֶד</a>. Ib. <span dir=\"rtl\">היו שוהים … ומִתְפַּלְּלִים</span> used to tarry a while (in meditation) and then say the prayers. Ib. IV, 3 <span dir=\"rtl\">יִתְפַּלֵּל שמונה עשרה</span> should pray the eighteen benedictions. Ib. 4 <span dir=\"rtl\">מִתְפַּלֵּל תפלה קצרה</span> says a short prayer. Y. ib. 8ᵇ top <span dir=\"rtl\">ספק נתפ׳ ספק לא נ׳</span> if he is in doubt whether he has or has not said his prayers; a. v. fr.</div></div>","alt":[]},"22836":{"h":"פְּלַל","r":"Q01076","html":"<div class=\"sense\">, <i>to argue, debate</i> (v. <a href=\"#\" data-headword=\"פַּלְפֵּל I\">פלפל</a>). Y. Shebi. VIII, 38ᵇ top <span dir=\"rtl\">מאן גדם לך דלא פַלְתָּה עם חביריך</span> what brought it on thee (that thou couldst not solve that problem)? That thou didst not hold debates with thy fellow students; <span class=\"citation\">Y. Ned. XI, 42ᶜ</span> bot. <span dir=\"rtl\">ילפתה</span> (corr. acc.).</div>","alt":[]},"22837":{"h":"פְּלַלְגוּלָה","r":"Q01077","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (reduplic. of <a href=\"#\" data-headword=\"פְּלַג I\">פְּלַג</a>; cmp. pallacana) <i>dwarfonion</i>. <span class=\"citation\">Y. Kil. I, 27ᵃ</span>, expl. <a href=\"#\" data-headword=\"בְּצַלְצוּל\">בְּצַלְצוּל</a> q. v.</div>","alt":[]},"22838":{"h":"פָּלַם","r":"Q01078","html":"<div class=\"sense\"><i>to be round, smooth</i> (cmp. Arab. <i>tafailam</i> pinguis fuit); only in part. <i>Pu</i>. <a href=\"#\" data-headword=\"מְפוּלָּם\">מְפוּלָּם</a> <i>smooth, viscous.</i>—Pl. <span dir=\"rtl\">מְפוּלָּמִין</span>, <span dir=\"rtl\">מְפוּלָּמוֹת</span>. <span class=\"citation\">Bets. 24ᵇ</span> <span dir=\"rtl\">דגים המפ׳</span> moist fish (fresh-caught). <span class=\"citation\">Zeb. 54ᵃ</span> <span dir=\"rtl\">אבנים מפ׳</span> smooth stones (fresh from the ground). <span class=\"citation\">Ḥag. 12ᵃ</span> (expl. <span dir=\"rtl\">בהו</span> <span class=\"citation\">Gen. I, 2</span>) <span dir=\"rtl\">אלו אבנים המפ׳ וכ׳</span> that means the smooth (chaotic) stones which are sunk in the deep &amp;c. (with ref. to <span dir=\"rtl\">אבני בהו</span>, <span class=\"citation\">Is. XXXIV, 11</span>); <span class=\"citation\">Yalk. Gen. 4</span>.—<span class=\"citation\">Targ. Job XXVIII, 3</span> <span dir=\"rtl\">אבנין מפולמין וכ׳</span> (Ms. ed. Wil. <span dir=\"rtl\">מְפוּלָּמָן</span>) smooth (chaotic) stones out of which darkness proceeds (h. text <span dir=\"rtl\">אבן אפל</span>).</div>","alt":[]},"22839":{"h":"פְּלַם","r":"Q01079","html":"<div class=\"sense\"><i>Part. pass.</i> (h. form) <a href=\"#\" data-headword=\"מְפוּלָּם\">מְפוּלָּם</a>, v. <a href=\"#\" data-headword=\"פָּלַם\">preced.</a></div>","alt":[]},"22840":{"h":"פֹּלְמוֹס","r":"Q01080","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פּוֹלְמוֹס\">פּוֹלְמוֹס</a></div>","alt":[]},"22841":{"h":"פלמטרין","r":"Q01081","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ber. I, 3ᵇ</span> bot., v. <a href=\"#\" data-headword=\"פַּלְמַנְטָר\">פַּלְמַנְטָר</a></div>","alt":[]},"22842":{"h":"פלמיא","r":"Q01082","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Ned. IV, 3</span> ed. Zuck. (Var. <span dir=\"rtl\">פמליא</span>), v. <a href=\"#\" data-headword=\"פִּמְלַנְיָא\">פִּמְלַנְיָא</a></div>","alt":[]},"22843":{"h":"פלמיטוס","r":"Q01083","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶפִּימְלֵיטֵיס\">אֶפִּימְלֵיטֵיס</a></div>","alt":["פלמיטיס"]},"22844":{"h":"פַּלְמַנְטָר","r":"Q01084","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (frumentarius) <i>military purveyor, commissary, imperial agent</i> (v. Sm. Ant. s. v. Frumentarius). Y’lamd. to Deut. III, 23 sq., quot. in Ar. <span dir=\"rtl\">משה היה פַּלְמַנְטָרוֹ וכ׳</span> Moses was the Lord’s special agent (v. <span class=\"citation\">Num. XII, 7</span>). Yalk. Lam. 1001 <span dir=\"rtl\">פלמנסר של מלך</span> (corr. acc.)—Pl. <span dir=\"rtl\">פַּלְמַנְטָרִין</span>. <span class=\"citation\">Y. Ber. I, 3ᵇ</span> bot. <span dir=\"rtl\">למלך ששלח שני פ׳ וכ׳</span> Ar. a. ed. Lehm. (ed. <a href=\"#\" data-headword=\"פלמטרין\">פלמטרין</a>, corr. acc.) like a king who sent out two frumentarii (negotiators); with regard to one he wrote, give him no credit unless he shows my signature and seal &amp;c.; <span class=\"citation\">Cant. R. to I, 2</span>; Y. Ab. Zar. II, 41ᶜ bot. <a href=\"#\" data-headword=\"סִימַנְטֵיר\">סימנטירין</a> (corr. acc.). Tanḥ. B’midb. 26 [read:] <span dir=\"rtl\">אף אני מקרבן ועושם פ׳ שלי וכ׳ I</span>, too, shall bring them near, and make them my special agents, and entrust my house and my sanctity to none but them; <span class=\"citation\">Yalk. Num. 695</span> <a href=\"#\" data-headword=\"פלטנטירין\">פלטנטירין</a> (corr. acc.); v. <a href=\"#\" data-headword=\"פַּלְטֵרִין\">פַּלְטֵרִין</a>.—[<span class=\"citation\">Y. Taan. II, 65ᵈ</span>; <span class=\"citation\">Y. Bets. I, 60ᶜ</span> bot. <span dir=\"rtl\">פלמנטרין</span>, v. <a href=\"#\" data-headword=\"פְּלוּמַטְרִין\">פְּלוּמַטְרִין</a>.]</div>","alt":[]},"22845":{"h":"פלמניא","r":"Q01085","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּמְלַנְיָא\">פִּמְלַנְיָא</a></div>","alt":[]},"22846":{"h":"פלמנסר","r":"Q01086","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּלְמַנְטָר\">פַּלְמנְטָר</a></div>","alt":[]},"22847":{"h":"פלמרכוס","r":"Q01087","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פּוֹלִימַרְכוֹס\">פּוֹלִימַרְכוֹס</a></div>","alt":["פלמרכון"]},"22848":{"h":"פְּלַן","r":"Q01088","html":"<div class=\"sense\"> m. = h. <a href=\"#\" data-headword=\"פְּלוֹנִי\">פְּלוֹנִי</a>. <span class=\"citation\">Y. Kidd. III, 63ᵈ</span> top <span dir=\"rtl\">אנא פ׳ בר פ׳ … ליך אנת פלנית בת פ׳ … מיקמת פ׳ וכ׳ I</span>—son of—betroth thee—daughter of—, with the condition that I give thee an estate bearing the name of—, and to marry thee on the day—&amp;c. <span class=\"citation\">Y. Yeb. IV, 6ᵃ</span> bot. <span dir=\"rtl\">ביום פ׳</span> on such and such a day (naming the date). <span class=\"citation\">Gen. R. s. 21</span>, beg. (ref. to <span dir=\"rtl\">לפלמוני</span> <span class=\"citation\">Dan. VIII, 13</span>) <span dir=\"rtl\">לפלניא</span> (some ed. <span dir=\"rtl\">לפְלַנְיָיה</span>) to a certain defined person; Yalk. Dan. 1066. <span class=\"citation\">Koh. R. to X, 5</span> פסוק פ׳ בתר פ׳ I recited that certain verse, and then that. <span class=\"citation\">Gitt. 69ᵇ</span> (in an incantation) <span dir=\"rtl\">פלוני בר פלוניתא</span> thou—, son of—; a. v. fr.—Fem. <a href=\"#\" data-headword=\"פְּלֹנִית\">פְּלָנִית</a>, <a href=\"#\" data-headword=\"פְּלֹנִית\">פְּלָנִיתָא</a>, <a href=\"#\" data-headword=\"פְּלַנְתָּא\">פְּלַנְתָּא</a>, <a href=\"#\" data-headword=\"פְּלֹנִית\">(פְּלוֹנִיתָא</a>). Y. Keth. VIII, 31ᶜ <span dir=\"rtl\">אין הדא פ׳ תסבי להדין פלוני בעלה וכ׳</span> if that woman—be married to that man—, her betrothed husband, and &amp;c. <span class=\"citation\">Pes. 112ᵃ</span>; a. v. fr.</div>","alt":["פְּלָנִי","פְּלַנְיָא","(פְּלוֹנִי)"]},"22849":{"h":"פלן","r":"Q01089","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 48</span> <span dir=\"rtl\">פ׳ של אבינו אברהם</span>, v. <a href=\"#\" data-headword=\"פִּילוֹן\">פִּילוֹן</a></div>","alt":[]},"22850":{"h":"פְּלַנְדִּיסִין","r":"Q01090","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלְדַּרְסִין\">בַּלְדַּרְסִין</a></div>","alt":["פְּלַנְדְּסִין","פְּלַנְדַּרְסִין"]},"22851":{"h":"פְּלֹנִי","r":"Q01091","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלוֹנִי\">פְּלוֹנִי</a>, a. <a href=\"#\" data-headword=\"פְּלַן\">פְּלן</a>.</div>","alt":["פְּלָנִי"]},"22852":{"h":"פלניא","r":"Q01092","html":"<div class=\"sense\">, <span class=\"citation\">Nidd. 13ᵇ</span> bot. Ar., v. <a href=\"#\" data-headword=\"פִּמְלַנְיָא\">פִּמְלַנְיָא</a></div>","alt":[]},"22853":{"h":"פְּלַנְיָא","r":"Q01093","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלַן\">פְּלַן</a></div>","alt":["פְּלַנְיָיה"]},"22854":{"h":"פלנים","r":"Q01094","html":"<div class=\"sense\">, Y. Ḥag. I, 76ᵈ top, v. <a href=\"#\" data-headword=\"פִּינוֹלֵס\">פִּינוֹלֵס</a></div>","alt":[]},"22855":{"h":"פלניס","r":"Q01095","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to VII, 8</span> emend. by Mus., v. <a href=\"#\" data-headword=\"*טלנס\">טלנס</a></div>","alt":[]},"22856":{"h":"פְּלֹנִית","r":"Q01096","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלוֹנִי\">פְּלוֹנִי</a>, a. <a href=\"#\" data-headword=\"פְּלַן\">פְּלַן</a>.</div>","alt":["פְּלָנִית","פְּלָנִיתָא"]},"22857":{"h":"פלנקיא","r":"Q01097","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּילוֹנִיקְיָא\">פִּילוֹנֵיקְיָא</a></div>","alt":["פלנקריא"]},"22858":{"h":"פְּלַנְתָּא","r":"Q01098","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלַן\">פְּלַן</a></div>","alt":[]},"22859":{"h":"פְּלַס","r":"Q01099","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"פָּלַשׁ I\"><span dir=\"rtl\">פָּלַשׁ</span> I</a>) <i>to split, pick to pieces</i>. <span class=\"citation\">B. Kam. 19ᵇ</span> <span dir=\"rtl\">ההוא חמרא … ופַלְסֵיה לסלא</span> an ass ate (a neighbor’s) bread and picked the basket to pieces. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אכיל והדר פָּלֵיס</span> he eats first and then picks to pieces.</div><div class=\"sense\"><b>Pa. פַּלֵּיס</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"פְּלַנְתָּא\">same</a>. Ib. <span dir=\"rtl\">אורחיה נמי לפַלּוּסֵי סלא</span> it is also his habit to demolish a basket.</div></div>","alt":[]},"22860":{"h":"*פלסגר","r":"Q01100","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Ter. VII, 16</span> <span dir=\"rtl\">ובפ׳</span> ed. Zuck. (Var. <span dir=\"rtl\">ובאלפסנה</span>, missing in oth. eds.) a corrupt. of <span dir=\"rtl\">פלסגה</span>, <span dir=\"rtl\">פלאסגה</span> = φλάσγα, <i>flask</i>, a gloss to <a href=\"#\" data-headword=\"לגין\">לגין</a>, put in the text through misunderstanding.</div>","alt":[]},"22861":{"h":"פְּלַסְטוֹן","r":"Q01101","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πλαστόν) <i>fabricated, a fraud</i>. <span class=\"citation\">Num. R. s. 8</span> the nations said <span dir=\"rtl\">תורתן של אלו פ׳ הוא</span> that people’s Law is a fraud (they do not observe it themselves); Midr. Sam. ch. XXVIII <a href=\"#\" data-headword=\"פְּלַסְטִיר\">פלסתר</a>. <span class=\"citation\">Y. B. Mets. V, end, 10ᵈ</span> <span dir=\"rtl\">שעישין התורה פלסטרן ואת משה טפש</span> (corr. acc.) they (the usurers), declare the Law (forbidding usury) a fraud, and Moses a fool; <span class=\"citation\">Tosef. B. Mets. VI, 17</span> <a href=\"#\" data-headword=\"פְּלַסְטִיר\">פלסטר</a>; (Bab. ib. 75ᵇ <span dir=\"rtl\">משה חכם ותורתו אמת</span>, euphem.). Y’lamd. to Num. XVI, quot. in Ar. <span dir=\"rtl\">פ׳ הוא תורתו וכ׳</span> the law of Moses is a fraud. <span class=\"citation\">Yalk. Jer. 321</span> <span dir=\"rtl\">מה שאנו רואים … פלסטרו הוא</span> (corr. acc.) as far as we can judge your Law, it is a fraud (its predictions are not inspired); <span class=\"citation\">ib.</span> <span dir=\"rtl\">אין דבר בתורה פלסטרון ולא וכ׳</span> not a word in the Law is a fabrication or a falsehood. Tanḥ. ed. Bub. Lekh 10 <span dir=\"rtl\">פלסטין הוא</span> (corr. acc.) the document is forged.</div>","alt":[]},"22862":{"h":"פלסטוני","r":"Q01102","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלַסְטִינִי\">פְּלַסְטִינִי</a></div>","alt":["פלסטים"]},"22863":{"h":"פלסטין","r":"Q01103","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּלַסְטוֹן\">פְּלסְטוֹן</a></div>","alt":[]},"22864":{"h":"פלסטינו","r":"Q01104","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Gen. 109</span>, v. <a href=\"#\" data-headword=\"פילסונו\">פילסונו</a></div>","alt":[]},"22865":{"h":"פְּלַסְטִינִי","r":"Q01105","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (Παλαιστίνη) <i>Palestine (Philistæa)</i>. <span class=\"citation\">Gen. R. s. 90</span> end (ref. to <span class=\"citation\">Gen. XLI, 54</span>) <span dir=\"rtl\">בשלש ארצות בפניקיא ובפ׳ …</span> in the three countries, Phœnicia, Arabia and Palestine; Yalk. ib. 148 <span dir=\"rtl\">בקפוטיקי … ובפלסטים</span> (corr. acc.). <span class=\"citation\">Lev. R. s. 5</span> (ref. to <span dir=\"rtl\">גת פלשתים</span> <span class=\"citation\">Am. VI, 2</span>) <span dir=\"rtl\">אלין תלוליא דפ׳</span> that means the mounds of Philistia; <span class=\"citation\">Num. R. s. 10</span>; Yalk. Am. 545 <span dir=\"rtl\">דפלסתני</span> (corr. acc). <span class=\"citation\">Lam. R. to I, 5</span> <span dir=\"rtl\">דוכוס דפ׳</span> the dux (commander) of Palestine.</div>","alt":[]},"22866":{"h":"פְּלַסְטִיר","r":"Q01106","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  (πλάστηρ = πλάστης) <i>forger</i>. [This meaning of πλάστης is not recorded elsewhere.] <span class=\"citation\">Ab. Zar. 11ᵇ</span> בר קירי פ׳ Ms. M. (ed. <span dir=\"rtl\">סך קירי פלסתר</span>) (supposed to mean) <span dir=\"rtl\">אחוה דמרנא זייפנא</span> the brother of our lord, the forger.</div><div class=\"sense\"><b>—2)</b>  (πλαστήριον) <i>fraud, forgery, illegal document</i> [not recorded in this sense]. <span class=\"citation\">Tosef. B. Mets. VI, 17</span>, v. <a href=\"#\" data-headword=\"פְּלַסְטוֹן\">פְּלַסְטוֹן</a>. <span class=\"citation\">Lev. R. s. 19</span> (the Book of Deuteronomy complained) <span dir=\"rtl\">עיקרני … ועשאני פ׳ וכ׳</span> Solomon has uprooted me and made me a forgery, for a document of which two or three points are void, is null and void in its entirety. <span class=\"citation\">Ber. 31ᵇ</span> <span dir=\"rtl\">ואי אתה עושה תורתך פ׳</span> and thou wilt not make thy Law a fraud (by not fulfilling what is predicted, <span class=\"citation\">Num. V, 28</span>). <span class=\"citation\">Succ. 29ᵃ</span> <span dir=\"rtl\">כותבי פלסתר</span> forgers of documents or signatures; <span class=\"citation\">Tosef. ib. II, 5</span> פלסטיר Var. (ed. Zuck. <a href=\"#\" data-headword=\"פְּלַסְטִיר\">פלסתר</a>).</div>","alt":["פְּלַסְטֵר","(פלסתר)"]},"22867":{"h":"פלסטרו","r":"Q01107","html":"<div class=\"sense\"> read: <span dir=\"rtl\">פְּלַסְטְרִין</span> (πλαστήριον), v. <a href=\"#\" data-headword=\"פְּלַסְטִיר\">preced.</a>, or read <a href=\"#\" data-headword=\"פְּלַסְטוֹן\">פְּלַסְטוֹן</a>.</div>","alt":["פלסטרון"]},"22868":{"h":"פְּלֹסְלוֹס","r":"Q01108","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (reduplic. of <a href=\"#\" data-headword=\"פְּלַס\">פלס</a>; cmp. <a href=\"#\" data-headword=\"פּוּלְסָא\">פּוּלְסָא</a>) <i>p’loslos</i>, a sort of <i>lupine</i>, homogeneous with <a href=\"#\" data-headword=\"תּוּרְמוֹס\">תורמוס</a>. <span class=\"citation\">Kil. I, 3</span> (Ms. M. <span dir=\"rtl\">סלוסלות</span>, v. Rabb. D. S. a. l. note); <span class=\"citation\">Tosef. ib. I, 2</span>; expl. Y. ib. 27ᵃ <a href=\"#\" data-headword=\"פַּרְמוֹעָה\">פרמועה</a>.</div>","alt":["פְּלוֹסלוֹס"]},"22869":{"h":"פַּלְסְמוֹן","r":"Q01109","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"בַּלְסָם\">בַּלְסְמוֹן</a>. <span class=\"citation\">Gen. R. s. 33</span>; (<span class=\"citation\">Lev. R. s. 31</span> <a href=\"#\" data-headword=\"ב׳\">ב׳</a>). <span class=\"citation\">Num. R. s. 13</span>; a. e.</div>","alt":["פַּלְסְמָן"]},"22870":{"h":"פלסתני","r":"Q01110","html":"<div class=\"sense\">, v. sub. <span dir=\"rtl\">פְּלַסְט׳</span>.</div>","alt":["פְּלַסְתֵּר"]},"22871":{"h":"פִּלְפּוּל","r":"Q01111","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פִּלְפֵּל\">פִּלְפֵּל</a>) <i>discussion, debate</i>. <span class=\"citation\">B. Bath. 145ᵇ</span> <a href=\"#\" data-headword=\"פְּעוֹר\">בעל פ׳</a> master in dialectics. <span class=\"citation\">Ab. VI</span> <span dir=\"rtl\">פ׳ התלמידים</span> the debates among scholars. <span class=\"citation\">Tem. 16ᵃ</span> החזירן … מתוך פִּילְפּוּלוֹ Othniel … restored them (the lost interpretations of the Law) through his reasoning; a. e.</div>","alt":["פִּילְ׳"]},"22872":{"h":"פִּלְפּוּלָא","r":"Q01112","html":"<div class=\"sense\"> <span class=\"citation\">Ned. 38ᵃ</span> <span dir=\"rtl\">פ׳ בעלמא</span> only deductions by argument (were given to Moses exclusively, and he communicated them to the people). <span class=\"citation\">Y. Ter. IV, 42ᵈ</span> מפִּילְפּוּל חבירייא שמעית הא I learned this from the students’ arguments. <span class=\"citation\">Erub. 67ᵃ</span> רב ששת מרתע … מפִּילְפּוּלֵיה וכ׳ R. Sh. trembled all over his body, when R. H. argued. <span class=\"citation\">Keth. 103ᵇ</span> <span dir=\"rtl\">אם … מהדרני ליה מפִּילְפּוּלִי</span> if, God forefend, the Law should be forgotten in Israel, I could restore it by my argumentation; <span class=\"citation\">B. Mets. 85ᵇ</span>; a. e.</div>","alt":["פִּילְ׳"]},"22873":{"h":"פלפילין","r":"Q01113","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּלְפָּל\">פִּלְפָּל</a></div>","alt":[]},"22874":{"h":"פִּלְפֵּל","r":"Q01114","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"פָּלַל\">פָּלַל</a> a. <a href=\"#\" data-headword=\"*פּוּל\"><a href=\"#\" data-headword=\"*פּוּל\">פּוּל</a>)</a></div><div class=\"sense\"><b>1)</b> <i>to search</i>. Tanḥ. Vayesheb <span dir=\"rtl\">הוצרך … לפַלְפֵּל בעפר וכ׳</span> (some ed. <span dir=\"rtl\">לפַשְׁפֵּשׁ</span>) the king had need of searching in the dust and among the pebbles to find the pearl. <span class=\"citation\">Tosef. B. Bath. VII, 5</span> <span dir=\"rtl\">כל דבר שלא פִּלְפְּלוּ בו יתומין וכ׳</span> the first-born gets a double share of whatever the heirs had no need of searching for (being ready on hand at the father’s death). <span class=\"citation\">Sabb. 31ᵃ</span> (among the questions which the dead are asked on appearing before the seat of judgment) <span dir=\"rtl\">פִּלְפַּלְתָּה בחכמה</span> hast thou been a searcher after wisdom?</div><div class=\"sense\"><b>—2)</b> <i>to argue, debate</i>. <span class=\"citation\">B. Mets. 85ᵇ</span> לא פִּלְפַּלְתִּי בתורה כמותו Ms. R. (ed. <a href=\"#\" data-headword=\"תּוֹרָה\">תורה</a>) did I not argue on the Law like him? <span dir=\"rtl\">תורה כמותו פִּלְפַּלְתָּ וכ׳</span> thou didst argue … like him, but thou didst not spread learning like him; a. e.</div>","alt":[]},"22875":{"h":"פַּלְפֵּל I","r":"Q01115","html":"<div class=\"sense\">, <i>to argue, reason</i>. <span class=\"citation\">Targ. Job XI, 12</span> sec. vers. (first vers. <span dir=\"rtl\">חריף</span>; h. text <a href=\"#\" data-headword=\"נָבוּב\">נבוב</a>).</div>","alt":[]},"22876":{"h":"פַּלְפֵּל II","r":"Q01116","html":"<div class=\"sense\"> [<i>to be round</i>, v. <a href=\"#\" data-headword=\"פִּלְפָּל\">next w.</a>,] <i>to roll in, cover with</i> (cmp. <a href=\"#\" data-headword=\"פָּלַשׁ II\"><span dir=\"rtl\">פָּלַשׁ</span> II</a>; Syr. <a href=\"#\" data-headword=\"פַּלְפֵּל I\">פלפל</a> inquinavit, P. Sm. 3130). <span class=\"citation\">Targ. Job XVI, 15</span> (h. text <a href=\"#\" data-headword=\"עָלַל\">עלל</a>).—Part. pass. <span dir=\"rtl\">מְפַלְפַּל</span>. Targ. II Esth. IV, 16.</div><div class=\"sense\"><b>Ithpalp. אִתְפַּלְפֵּל</b> <div class=\"sense\"><i>to roll one’s self</i>. Ib. l.</div></div>","alt":[]},"22877":{"h":"פִּלְפָּל","r":"Q01117","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (פלל <i>to be round, roll) ball, grain</i>, esp. <i>pepper</i>. <span class=\"citation\">Sabb. VI, 5</span> (<span class=\"citation\">64ᵇ</span>) <span dir=\"rtl\">בפ׳ ובגרגיר מלח</span> with a grain of pepper (Rashi: a bit of ‘long pepper’) or a grain of salt (in the mouth); ib. 65ᵃ <span dir=\"rtl\">פ׳ לריח הפה</span> pepper (is put in the mouth) to dispel the bad odor &amp;c. Ib. IX, 6 (90ᵃ) <span dir=\"rtl\">פלפלת כל שהו</span> any quantity of (long) pepper; a. e.—Pl. <span dir=\"rtl\">פִּלְפָּלִין</span>, <a href=\"#\" data-headword=\"פִּלְפּוּל\">פִּילְ׳</a>. <span class=\"citation\">Ber. 36ᵇ</span> <span dir=\"rtl\">הפ׳ חייבין בערלה</span> pepper-trees are subject to the law of ʿOrlah. <span class=\"citation\">Bets. II, 9</span> <span dir=\"rtl\">הרחים של פ׳</span> pepper-mill. <span class=\"citation\">Treat. Sof’rim XV, 8</span> <span dir=\"rtl\">נמשלה … והמשנה כפ׳</span> the Torah is compared to salt, the Mishnah to pepper. <span class=\"citation\">Y. Hor. III, 48ᶜ</span> top <span dir=\"rtl\">מלח בזול פ׳ ביוקר</span> salt is cheap, pepper is dear; <span dir=\"rtl\">איפשר לעולם … בלא פ׳ וכ׳</span> (not <a href=\"#\" data-headword=\"פלפילין\">פלפילין</a>) the world can live without pepper, but not without salt; a. fr.—[<span class=\"citation\">Koh. R. to IX, 13</span>, v. <a href=\"#\" data-headword=\"פִּילוֹן\">פִּילּוֹן</a>.]</div>","alt":["פִּילְ׳","פִּלְפֶּלֶת","פִּילְ׳"]},"22878":{"h":"פִּלְפְּלָא","r":"Q01118","html":"<div class=\"sense\"> <span class=\"citation\">Keth. 75ᵃ</span> <span dir=\"rtl\">אפשר דנקיט פ׳ וכ׳</span> he may take a grain (or a bit) of pepper in his mouth (to dispel the bad smell) and perform his priestly function. <span class=\"citation\">Meg. 7ᵃ</span> <span dir=\"rtl\">חדא פ׳ חריפתא</span> one grain of sharp pepper, v. <a href=\"#\" data-headword=\"חָרִיף\">חָרִיף</a>; a. fr.—Pl. <a href=\"#\" data-headword=\"פִּלְפְּלָן\">פִּלְפְּלִין</a>, <a href=\"#\" data-headword=\"פִּלְפְּלָא\">פִּלְפְּלֵי</a>, <a href=\"#\" data-headword=\"פִּלְפּוּל\">פִּילְ׳</a>. <span class=\"citation\">Sabb. 141ᵃ</span> <span dir=\"rtl\">הני פ׳ וכ׳</span> (Ar. <a href=\"#\" data-headword=\"פרפלי\">פרפלי</a>) grains of pepper one may crush singly (on the Sabbath). <span class=\"citation\">Yoma 81ᵇ</span>, a. e. <span dir=\"rtl\">כס פ׳</span>, v. <a href=\"#\" data-headword=\"כְּסַס\">כְּסַס</a>. <span class=\"citation\">Pes. 42ᵇ</span> <span dir=\"rtl\">פי׳ אֲרִיכָתָא</span> (Ms. M. <span dir=\"rtl\">פילפלא אריכְתָּא</span>) long pepper; <span class=\"citation\">Gitt. 69ᵇ</span>; a. fr.</div>","alt":["פִּלְפַּלְתָּא","פִּילְ׳"]},"22879":{"h":"פִּלְפְּלָן","r":"Q01119","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פִּלְפֵּל\">פִּלְפֵּל</a>, with play on <a href=\"#\" data-headword=\"פִּלְפָּל\">פִּלְפָּל</a>) <i>one skilled in arguing, debater</i>. <span class=\"citation\">Y. Hor. III, 48ᶜ</span> top <span dir=\"rtl\">הסודרן קודם לפיל׳</span> (Bab. ed. <span dir=\"rtl\">סדרן … לפל׳</span>, not <span dir=\"rtl\">לין …</span>) the systematic collector of traditions is preferable to the dialectician. Ib. (Bab. ed.) <span dir=\"rtl\">מאי את בעי מר׳ אימי דהוא סדרן והוא פ׳</span> (not <a href=\"#\" data-headword=\"פְּקוֹלִי\">הפ׳</a>) what do you want of R. I., who is both a systematizer and a debater?; Y. ed. <span dir=\"rtl\">מיתבעי מר׳ אימי הוא הפ׳</span> (corr. acc.).</div>","alt":["פִּילְ׳"]},"22880":{"h":"פִּלְפֶּלֶת","r":"Q01120","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּלְפָּל\">פִּלְפָּל</a>, <a href=\"#\" data-headword=\"פִּלְפְּלָא\"><a href=\"#\" data-headword=\"פִּלְפְּלָא\">פִּלְפְּלָא</a>.</a></div>","alt":["פִּלְפַּלְתָּא"]},"22881":{"h":"פָּלַץ","r":"Q01121","html":"<div class=\"sense\"> (b. h.) <i>to split, shatter</i>.</div><div class=\"sense\"><b>Nithpa. נִתְפַּלֵּץ</b> <div class=\"sense\"><i>to be split, cracked</i>. <span class=\"citation\">Midr. Till. to Ps. LX</span>, ed. Bub. <span dir=\"rtl\">בשעה שאמר לו יואב הדברים האלו רעשה הארץ נִתְפַּלְּצָה עליהם ונתקפלה תחתיו ונמצא עומד דוד להכותו</span> when Joab said to him (Moab) these words, the earth quaked; it was split around them, and folded itself under his feet, and presently David stood there to smite him (Moab).</div></div>","alt":[]},"22882":{"h":"*פְּלָצוּר","r":"Q01122","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> a kind of <i>snare</i> (Arab. <i>wahaḳ</i>). <span class=\"citation\">Kel. XXIII, 5</span>. <span class=\"citation\">Yalk. Num. 762</span> (gloss: <span dir=\"rtl\">עגול הקרון</span> <i>wheel</i>; Syr. <span dir=\"rtl\">פלצורא</span>, <span dir=\"rtl\">פלסורא</span> <i>press</i>, P. Sm. 3161, sq.).</div>","alt":[]},"22883":{"h":"*פְּלַק","r":"Q01123","html":"<div class=\"sense\"><i>to split, create a gaping wound</i>. <span class=\"citation\">Gitt. 69ᵃ</span> הדרי עילויה ופַלְקוּ ליה Ar. (ed. only <span dir=\"rtl\">הדרי עילויה</span>) they (the demons) will come back and wound him.</div>","alt":[]},"22884":{"h":"פַּלְקָא","r":"Q01124","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*פְּלַק\">preced.</a>) <i>fissure, wound</i>. <span class=\"citation\">Koh. R. to VI, 11</span> <span dir=\"rtl\">או חד פ׳ וכ׳</span> he receives either a wound &amp;c., v. <a href=\"#\" data-headword=\"פְּדַע II\">פִּדְעָא</a>.</div>","alt":[]},"22885":{"h":"פִּלַּקְתָּא","r":"Q01125","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"פִּלֶּגֶשׁ\">פִּלֶּגֶשׁ</a>. <span class=\"citation\">Targ. Y. Gen. XXXVI, 12</span>. <span class=\"citation\">Ib. XXII, 24</span>. <span class=\"citation\">Targ. I Chr. I, 32</span> (some ed. <a href=\"#\" data-headword=\"פִּלַּקְתָּא\">פַּלְקְתָא</a>); a. e.—Pl. <span dir=\"rtl\">פִּילַּקְתִין</span>, <a href=\"#\" data-headword=\"פִּלַּקְתָּא\">פִּילַ׳</a>. <span class=\"citation\">Ib. III, 9</span>. <span class=\"citation\">Targ. Y. Gen. XXV, 6</span> (ed. Vien. <a href=\"#\" data-headword=\"פְּרַגְמַטְיָא\">פְּלַקְ׳</a>); a. e.</div>","alt":["פִּילַ׳"]},"22886":{"h":"פָּלַשׁ I","r":"Q01126","html":"<div class=\"sense\"><i>to divide, go through</i>.</div><div class=\"sense\"><b>Pi. פִּילֵּשׁ</b> <div class=\"sense\"><b>1)</b> <i>to penetrate, go from end to end, perforate</i>, v. infra., v. infra.</div><div class=\"sense\"><b>—2)</b> <i>to search</i>. <span class=\"citation\">Num. R. s. 14</span>; Y. Snh. X, 29ᵇ bot. (play on <span dir=\"rtl\">עלי פלשת התרועעי</span>, <span class=\"citation\">Ps. LX, 10</span>) <span dir=\"rtl\">עלי לפַלֵּשׁ להם מעשים טובים לעשותן ריעים וכ׳</span> it is for me to search for their good deeds and make them friendly to wards one another.</div><div class=\"sense\"><b>—3)</b>  (with <span dir=\"rtl\">אחר</span>) [<i>to dig after</i>,] <i>to go to extremes</i>. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">הם לא פִּלְּשׁוּ אחר מדת הדין והיא לא פִלְּשָׁה</span> (<span dir=\"rtl\">היתה</span>) <span dir=\"rtl\">אחריהם</span> (Ar. <span dir=\"rtl\">פִילְּ׳</span>) they (the Israelites) did not go to the extreme of rebellion against Justice, and she (Justice) did not go to the extreme in punishing them; (Var. in Ar. <span dir=\"rtl\">חִיפְּשׁוּ</span>, <span dir=\"rtl\">חִיפְּשָׁה</span>); ib. to II, 4; 5; <span class=\"citation\">Yalk. Hos. 521</span>.</div></div><div class=\"sense\"><b>Pu. פּוּלָּשׁ</b> <div class=\"sense\"><i>to be perforated</i>. Y. Succ. III, 53ᵈ <span dir=\"rtl\">ניקב ולא פ׳ מבפנים</span> (not <a href=\"#\" data-headword=\"פָּלַשׁ I\">פילש</a>) if the Ethrog is punctured but not perforated within (all through the skin).—Part. <a href=\"#\" data-headword=\"מְפוּלָּשׁ\">מְפוּלָּשׁ</a>; f. <span dir=\"rtl\">מְפוּלֶּשֶׁת</span>; pl. <span dir=\"rtl\">מְפוּלָּשִׁים</span>, <span dir=\"rtl\">מְפוּלָּשִׁין</span>; <span dir=\"rtl\">מְפוּלָּשׁוֹת</span>. Bab. <span class=\"citation\">Succ. 36ᵃ</span> <span dir=\"rtl\">נקב מפ׳</span> a puncture going through (into the flesh). <span class=\"citation\">Sabb. XVI, 1</span> <span dir=\"rtl\">מפ׳</span> (<a href=\"#\" data-headword=\"מָבוֹי\">מבוי</a>) an open alley, expl. <span class=\"citation\">ib. 117ᵃ</span> an alley opening into a street, not closed by a legally required fictitious partition, v. <a href=\"#\" data-headword=\"לֶחִי I\">לֶחִי</a>. <span class=\"citation\">Erub. IX, 4</span>, a. e. <span dir=\"rtl\">גשרים המפ׳</span>, v. <a href=\"#\" data-headword=\"גֶּשֶׁר\">גֶּשֶׁר</a>. Y. ib. VIII, 25ᵇ top (ref. to <a href=\"#\" data-headword=\"פִּיוְסָרוֹס\">פִּיוְסָרוֹס</a>) <span dir=\"rtl\">לעולם אין … מפ׳ מסוף העולם וכ׳</span> we never call a road a public area (v. <a href=\"#\" data-headword=\"רָשׁוּת I\">רָשׁוּת</a>), unless it is cut through from one end of the world to the other, i.e. runs in a straight line. <span class=\"citation\">Tosef. Kil. II, 1</span> <span dir=\"rtl\">תלמים שלשה מפ׳ וכ׳</span> three furrows running from one end of the field to the other. <span class=\"citation\">Gen. R. s. 70</span>; <span class=\"citation\">Yalk. ib. 124</span> (play on <a href=\"#\" data-headword=\"בָּנוֹת\">בנות</a>, <span class=\"citation\">Gen. XXIX, 16</span> = <span dir=\"rtl\">בונית</span>) <span dir=\"rtl\">כשתי קורות המפ׳ וכ׳</span> like two joists extending from one end of the world to the other, the one reared princes &amp;c. <span class=\"citation\">Gen. R. s. 44</span> (ref. to <span dir=\"rtl\">ומאציליה</span>, <span class=\"citation\">Is. XLI, 9</span>) <span dir=\"rtl\">ממפ׳ שבה וכ׳</span> from the parts of the world that have been gone through (explored) have I called thee; a. fr.</div></div>","alt":[]},"22887":{"h":"פָּלַשׁ II","r":"Q01127","html":"<div class=\"sense\"><i>to roll in, cover with</i>.</div><div class=\"sense\"><b>Hithpa. הִתְפַּלֵּשׁ</b> </div><div class=\"sense\"><b>Nithpa. נִתְפַּלֵּשׁ</b> <div class=\"sense\"><i>to roll one’s self, cover one’s self</i>. <span class=\"citation\">Gitt. 58ᵃ</span> <span dir=\"rtl\">קרעתו ונִתְפַּלְּשָׁח באפר</span> (not <span dir=\"rtl\">קרעתה</span>) she rent it (the shirt) and rolled herself in the dust; <span class=\"citation\">Yalk. Jer. 276</span>.</div></div>","alt":[]},"22888":{"h":"פְּלַשׁ","r":"Q01128","html":"<div class=\"sense\"><i>Ithpa.</i> <span dir=\"rtl\">אִתְפַּלֵּשׁ</span> same. <span class=\"citation\">Targ. Mic. I, 10</span>.</div>","alt":[]},"22889":{"h":"פְּלִשְׁתָּאָה","r":"Q01129","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Targ. I Sam. XVII, 23</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"פְּלִשְׁתָּאָה\">פְּלִשְׁתָּאֵי</a>. Ib.; a. fr.—<span class=\"citation\">Num. R. s. 14</span> (fr. <span class=\"citation\">Targ. Is. XI, 14</span>) <span dir=\"rtl\">לממחי ית פ׳</span> to beat the Philistines.</div>","alt":[]},"22890":{"h":"פְּלִשְׁתִּי","r":"Q01130","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>Philistine.</i>—Pl. <a href=\"#\" data-headword=\"פְּלִשְׁתִּי\">פְּלִשְׁתִּים</a>. <span class=\"citation\">Sot. VIII, 1</span> <span dir=\"rtl\">פ׳ באו וכ׳</span> the Philistines came with boastful reliance on &amp;c., v. <a href=\"#\" data-headword=\"נִצָּחוֹן\">נִצָּחוֹן</a>. <span class=\"citation\">Midr. Till. to Ps. LX</span>. <span class=\"citation\">Num. R. s. 14</span> ארץ פ׳ Philistia; a. fr.</div>","alt":[]},"22891":{"h":"*פָּלָתָא","r":"Q01131","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">פול</span> or <span dir=\"rtl\">פלל</span> <i>to split</i>) <i>fins</i>. Pesik. Par. p. 35ᵃ פ׳ דנוני Vers. in Ar., v. <a href=\"#\" data-headword=\"חַרְסְפִיתִין\">חַרְסְפִיתִין</a>.</div>","alt":[]},"22892":{"h":"פלתה","r":"Q01132","html":"<div class=\"sense\">, <span class=\"citation\">Y. Shebi. VIII, 38ᵇ</span> top, v. <a href=\"#\" data-headword=\"פְּלַל\">פְּלַל</a></div>","alt":[]},"22893":{"h":"פְּלֵתִי","r":"Q01133","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) gent. n. <i>P’lethi, Pelethi</i>; (collect.) <i>the body-guard of David</i>; (homilet.) <i>the Urim and Tummim</i>; (oth. opin.) <i>the Sanhedrin</i>. <span class=\"citation\">Ber. 4ᵃ</span>; <span class=\"citation\">Snh. 16ᵇ</span>, v. <a href=\"#\" data-headword=\"מוּפְלָא\">מוּפְלָא</a>.</div>","alt":[]},"22894":{"h":"פלתנים","r":"Q01134","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Deut. 942</span>, v. <a href=\"#\" data-headword=\"פַּתְלָן\">פַּתְלָן</a></div>","alt":[]},"22895":{"h":"פֻּם","r":"Q01135","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פּוּם\">פּוּם</a></div>","alt":[]},"22896":{"h":"פָּמוֹט","r":"Q01136","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>a shaft with a receptacle for a lamp, a plain candlestick</i> <span class=\"citation\">Men. 28ᵃ</span> <span dir=\"rtl\">ההוא פ׳ מקרי</span> such a candlestick without branches is named <i>pamoṭ</i> (and not <i>m’norah</i>); <span class=\"citation\">Yalk. Ex. 369</span> <span dir=\"rtl\">פסוק</span> (corr. acc.). <span class=\"citation\">Sabb. 44ᵃ</span> פ׳ שהדליקו עליו באותה שבת Ms. M. (v. Rabb. D. S. a. l. note) a lampholder on which a lamp has been burnt on that (the present) Sabbath day. Y. ib. III, 6ᶜ top (also <a href=\"#\" data-headword=\"פומט\">פומט</a>), contrad. to <a href=\"#\" data-headword=\"נֵר\">נר</a>.—Pl. <a href=\"#\" data-headword=\"פָּאוֹטוֹת\">פָּמוֹטוֹת</a>. Bab. ib. 121ᵇ</div>","alt":[]},"22897":{"h":"פמוליניא","r":"Q01137","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּמְלַנְיָא\">פִּמְלַנְיָא</a></div>","alt":[]},"22898":{"h":"פָּמִיאַס","r":"Q01138","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנְיָיס\">פַּנְיָיס</a></div>","alt":["פַּמְיָיס"]},"22899":{"h":"פמילאות","r":"Q01139","html":"<div class=\"sense\">, v. <span dir=\"rtl\">פמליאות</span></div>","alt":[]},"22900":{"h":"פַּמִּילְיָיא","r":"Q01140","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (familia) <i>the slaves in a household, family servants</i>; frequ. <i>divine agencies, ministers</i>. <span class=\"citation\">Targ. Cant. I, 15</span>.—<span class=\"citation\">Y. Sot. V, 20ᶜ</span> bot. <span dir=\"rtl\">איוב … ומגדולי פמילייא וכ׳</span> Job was one of Pharaoh’s servants and of the grandees of his household. <span class=\"citation\">Ḥull. 7ᵇ</span>; <span class=\"citation\">Snh. 67ᵇ</span> <span dir=\"rtl\">פ׳ של מעלה</span> the heavenly household, v. <a href=\"#\" data-headword=\"כַּשָּׁף\">כַּשָּׁף</a>. <span class=\"citation\">Ber. 16ᵇ</span> sq. <span dir=\"rtl\">שתשים שלים בפ׳ של מעלה ובפ׳ של מטה</span> let peace reign in the heavenly household and in the household here below (thy servants on earth). <span class=\"citation\">Num. R. s. 4</span>, beg. (ref. to <span class=\"citation\">Gen. XXVIII, 13</span>) <span dir=\"rtl\">ראה המלך ופ׳ שלו וכ׳</span> he saw the King, and his attendants stood by him to guard him. Sifra K’dosh. beg.; <span class=\"citation\">Yalk. Lev. 604</span>, v. <a href=\"#\" data-headword=\"חָקָה\">חָקָה</a>; a. fr.</div>","alt":["פַּמַּלְיָא","פְּמַ׳"]},"22901":{"h":"פַּמְיָס","r":"Q01141","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנְיָיס\">פַּנְיָיס</a></div>","alt":[]},"22902":{"h":"פַּמַּלְיָא","r":"Q01142","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּמִּילְיָיא\">פַּמִּילְיָיא</a></div>","alt":["פְּמַ׳"]},"22903":{"h":"פמלליא","r":"Q01143","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּמְלַנְיָא\">next w.</a></div>","alt":[]},"22904":{"h":"פִּמְלַנְיָא","r":"Q01144","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (corrupt. of <i>feminalia</i>) <i>bandages, knee-breeches</i>. <span class=\"citation\">Ned. 55ᵇ</span> <a href=\"#\" data-headword=\"פליניא\">פליניא</a> (Ar. <a href=\"#\" data-headword=\"פלניא\">פלניא</a>; corr. acc.). <span class=\"citation\">Nidd. 13ᵇ</span> <span dir=\"rtl\">כמין פ׳ של פרשים</span> (Vers. in Ar. <a href=\"#\" data-headword=\"פלניא\">פלניא</a>) like the <i>feminalia</i> of horsemen. <span class=\"citation\">Gen. R. s. 84</span> (ref. to <span dir=\"rtl\">אשר עליו</span>, <span class=\"citation\">Gen. XXXVII, 23</span>) <span dir=\"rtl\">זו פ׳ שלו</span> this refers to his breeches; Yalk. ib. 142 <a href=\"#\" data-headword=\"פלמניא\">פלמניא</a>. <span class=\"citation\">Kel. XXVII, 6</span> <a href=\"#\" data-headword=\"פמוליניא\">פמוליניא</a> (ed. Dehr. <a href=\"#\" data-headword=\"פִּימְלַנְיָיה\">פימלנייה</a>). <span class=\"citation\">Gen. R. s. 99</span> <span dir=\"rtl\">אלו … לובשי פמלליא</span> these (the priests) wear trousers, and those (the Greeks) wear <i>feminalia</i>. <span class=\"citation\">Num. R. s. 4</span> <span dir=\"rtl\">עטוף פעליונין</span> (read: <span dir=\"rtl\">פִּמְלְיוֹנִין</span>) he was wrapped in feminalia.</div>","alt":[]},"22905":{"h":"פן","r":"Q01145","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Jon. I, 8</span> some ed. <span dir=\"rtl\">ומפן</span>, read <span dir=\"rtl\">ומנן</span>, v. <a href=\"#\" data-headword=\"מְנָן\">מְנָן</a></div>","alt":[]},"22906":{"h":"פֶּן","r":"Q01146","html":"<div class=\"sense\"> [<i>eventually</i>,] <i>lest.</i> <span class=\"citation\">Zeb. 106ᵃ</span> <span dir=\"rtl\">כל מקום שנאמר השמר פן ואל וכ׳</span> wherever the Scripture has ‘be guarded, lest’, or <i>al</i>, it introduces a prohibitory law (v. <a href=\"#\" data-headword=\"עָשָׂה\">עָשָׂה</a>); <span class=\"citation\">Sot. 5ᵃ</span>, a. fr. <span class=\"citation\">Sifré Deut. 70</span>, quot. in <span class=\"citation\">Yalk. ib. 882</span> השמר בלא תעשה פן בלא תעשה ‘be guarded’ means a prohibitory law, and so does ‘lest’.</div>","alt":[]},"22907":{"h":"פְּנָא","r":"Q01147","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּנֵי I\">פְּנֵי</a></div>","alt":[]},"22908":{"h":"פְּנַאי","r":"Q01148","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּנָה\">פָּנָה</a>) </div><div class=\"sense\"><b>1)</b> <i>emptiness, vacancy</i>. <span class=\"citation\">Num. R. s. 14</span> (play on <span dir=\"rtl\">אל תבהל מפניו</span>, <span class=\"citation\">Koh. VIII, 3</span>) <span dir=\"rtl\">לא נתבהל מפ׳ הבית</span> he (Joseph) was not bewildered by the emptiness of the house (his being alone with Potiphar’s wife).</div><div class=\"sense\"><b>—2)</b> <i>vacation, leisure, time, opportunity</i>. <span class=\"citation\">Ab. Zar. V, 6</span> <span dir=\"rtl\">לפי שאין פ׳ לנסך</span> because the invaders do not take time to offer a libation (so as to make the wine forbidden, v. <a href=\"#\" data-headword=\"נָסַךְ\">נָסַךְ</a>). <span class=\"citation\">Ib. 71ᵃ</span> <span dir=\"rtl\">לנסך אין פ׳ לבעול יש פ׳</span> for libation they do not take time, but for outrage they do. Y. ib. V, 45ᵃ top <span dir=\"rtl\">אין פ׳ להטיל אירס</span> the snake (being pursued) finds no opportunity to shed venom; a. fr.</div>","alt":["פְּנַיי"]},"22909":{"h":"פנג","r":"Q01149","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Gen. XXII, 20</span> <span dir=\"rtl\">ופנגת</span>, some ed., read: <span dir=\"rtl\">ופַגְנַת</span>.</div>","alt":[]},"22910":{"h":"פִּנְגּוּס","r":"Q01150","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (transp. of pignus) <i>pledge</i> deposited with the creditor, the usufruct of which remained the debtor’s (v. Sm. Ant. s. v. Pignus). Mekh. Yithro, Baḥod., s. 1 (ref. to <span class=\"citation\">Is. XLV, 19</span>) [read:] <span dir=\"rtl\">לא אמרתי לזרע יעקב לאלו אני נותנה ולא תהו בקשוני לא נתתיה פ׳ וכ׳</span> I did not say, ‘to the seed of Jacob’, to them only will I give the Law (and not to other nations), nor (did I say,) ‘seek me for naught’, I have not given it as a pledge (of which you cannot have the usufruct), … long before I gave you the commands, have I advanced to you the reward for them &amp;c.; <span class=\"citation\">Yalk. Ex. 275</span>; <span class=\"citation\">Yalk. Is. 325</span> (omitting <span dir=\"rtl\">לאלו אני נותנה ולא</span>).</div>","alt":["פִּנְגָּס"]},"22911":{"h":"פנגיות","r":"Q01151","html":"<div class=\"sense\">, <span class=\"citation\">Pirké d’R. El. ch. XXV</span>, read: <span dir=\"rtl\">פגניות</span>, v. <a href=\"#\" data-headword=\"*פַּגְנוּת\">פַּגְנוּת</a></div>","alt":[]},"22912":{"h":"פִּנְגָּס","r":"Q01152","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּנְגּוּס\">פִּנְגּוּס</a></div>","alt":[]},"22913":{"h":"פַּנְגַּר","r":"Q01153","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (an adaptation of πανεγυρίστης) <i>Pangar (Encomiast)</i>, name of one of the generals (duces) before Jerusalem under Vespasian. <span class=\"citation\">Lam. R. to I, 5</span> <span dir=\"rtl\">חד אמר קילוס שמיה וחד אמר פ׳ שמיה</span> one says, the name of that dux was Ḳillus (Praise), and one says, his name was Pangar.</div>","alt":[]},"22914":{"h":"פַּנְדָּא I","r":"Q01154","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּדָּא\">פַּדָּא</a></div>","alt":[]},"22915":{"h":"*פַּנְדָּא II","r":"Q01155","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Panda</i>, </div><div class=\"sense\"><b>1)</b>  name of an Amora (?). <span class=\"citation\">Ber. 55ᵇ</span> (Ms. M. <span dir=\"rtl\">פבנא</span> a. <a href=\"#\" data-headword=\"פְּרָן\">פרנא</a>; En Yaăk. ed. pr., a. Yoḥăsin <a href=\"#\" data-headword=\"פַּרְנָךְ\">פרנך</a>, v. Rabb. D. S. a. l. note).</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">בר שיריקא פ׳</span> name of a demon. <span class=\"citation\">Sabb. 67ᵃ</span> (Rashi <span dir=\"rtl\">פנדאי</span>; Ms. M. <span dir=\"rtl\">פניא</span>).</div>","alt":[]},"22916":{"h":"פנדודה","r":"Q01156","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנְדּוּרָה\">פַּנְרּוּרָה</a></div>","alt":[]},"22917":{"h":"פנדור","r":"Q01157","html":"<div class=\"sense\">, read:</div>","alt":[]},"22918":{"h":"פַּנְדּוּרָה","r":"Q01158","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (πανδοῦρα, v. Hesych. s. v.) <i>pandean pipe (syrinx), the shepherd’s pipe</i>. Y. B. Bath. VII, end, 15ᵈ <span dir=\"rtl\">נותן לו כמין פ׳</span> he must give him a portion of his field in the shape of a syrinx (a quadrangle one side of which is half as long as its opposite). Ib. III, beg. 13ᵈ (expl. <a href=\"#\" data-headword=\"מַשְׁכּוֹכִיתָא\">מַשְׁכּוֹכִיתָא</a>) <span dir=\"rtl\">אית דמרין פ׳</span> (ed. Krot. <a href=\"#\" data-headword=\"פנדודה\">פנדודה</a>, corr. acc.) some say, the deliverance of the shepherd’s pipe (as symbolical possession); <span class=\"citation\">Y. B. Kam. X, end, 7ᶜ</span> (expl. <a href=\"#\" data-headword=\"בַּרְחָא\">ברחא</a>), v. <a href=\"#\" data-headword=\"שַׁרְקוּקִיתָה\">שַׁרְקוּקִיתָא</a>.</div>","alt":[]},"22919":{"h":"פַּנְדֵּירָא","r":"Q01159","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Pandera</i>, (<i>Panṭera, Panṭeri</i>), surname of Joseph the father of Jesus of Nazareth. <span class=\"citation\">Koh. R. to X, 5</span> <span dir=\"rtl\">חד מן אילין דבר פ׳</span> one of the followers of the son of P.—<span class=\"citation\">Tosef. Ḥull. II, 22</span>; <span class=\"citation\">24</span>; a. fr.; v. <a href=\"#\" data-headword=\"יֵשׁוּ\">יֵשׁוּ</a>.</div>","alt":["פַּנְדֵּרָא","(פַּנְטֵירָא","פַּנְטֵרָא","פַּנְטֵירִי)"]},"22920":{"h":"פנדר","r":"Q01160","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 50</span>, v. <a href=\"#\" data-headword=\"קְלָאפַנְדָּר\">קְלָאפנְדָּר</a></div>","alt":[]},"22921":{"h":"פַּנְדֵּרָא","r":"Q01161","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנְדֵּירָא\">פַּנְדֵּירָא</a></div>","alt":[]},"22922":{"h":"פָּנָה","r":"Q01162","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פני\">פני</a></div>","alt":[]},"22923":{"h":"פָּנֶה","r":"Q01163","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פָּנִים\">פָּנִים</a></div>","alt":[]},"22924":{"h":"פִּנָּה","r":"Q01164","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּינָּה\">פִּינָּה</a></div>","alt":[]},"22925":{"h":"פָּנוּטְיָה","r":"Q01165","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פָּגוּטְיָה\">פָּגוּטְיָה</a></div>","alt":[]},"22926":{"h":"פִּנּוּי","r":"Q01166","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּינּוּי\">פִּינּוּי</a></div>","alt":[]},"22927":{"h":"פָּנוּי","r":"Q01167","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּנָה\">פָּנָה</a>) </div><div class=\"sense\"><b>1)</b> <i>vacant, empty; free; superfluous</i>. <span class=\"citation\">Erub. 16ᵇ</span> <span dir=\"rtl\">ובלבד … בית סאתים פ׳</span> provided there is not an area of two S’ah unoccupied; expl. <span class=\"citation\">ib. 17ᵃ</span> <span dir=\"rtl\">פ׳ מכלים</span> unoccupied by travelling implements, contrad. to <span dir=\"rtl\">פ׳ מאדם</span> superfluous as regards the number of travellers (to each of whom an area of two S’ah is assigned). <span class=\"citation\">Ex. R. s. 5</span>; Tanḥ. Vaëra 6 <span dir=\"rtl\">שבטו … פ׳ היה מעבודת פרך</span> the tribe of Levi was exempt from hard labor; ed. Bub. ib. 4; <span class=\"citation\">Yalk. Ex. 176</span> <span dir=\"rtl\">פְּנוּי וכ׳</span>, v. <a href=\"#\" data-headword=\"לטרגיה\">לטרגיה</a>. <span class=\"citation\">Sabb. 23ᵃ</span> <span dir=\"rtl\">שלא יראה בעל הבית שעה פ׳ וכ׳</span> that the owner may not look out for a free moment (when there are no poor about), and say to his poor relative, here is the corner <a href=\"#\" data-headword=\"פֵּאָה\">(פֵּאָה</a>); Y. Peah IV, 18ᵇ <span dir=\"rtl\">קנויה</span> (corr. acc.); a. e.—Pl. <span dir=\"rtl\">פְּנוּיִים</span>, <span dir=\"rtl\">פְּנוּיִין</span>; <span dir=\"rtl\">פְּנוּיוֹת</span>. Tanḥ. l. c. <span dir=\"rtl\">בשביל שאתם פ׳ וכ׳</span> because you are idle, you say &amp;c.; Ex. R. l. c. <span dir=\"rtl\">פְּנוּיִם</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>síngle, unmarríed</i>. Sifra Emor, Par. 1, ch. I <span dir=\"rtl\">הפ׳ הבא על הפ׳ שלא וכ׳</span> if an unmarried man has connection with an unmarried woman without the intention of thereby making her his wife; <span class=\"citation\">Yeb. 61ᵇ</span>; a. fr.—Pl. as ab. <span class=\"citation\">Num. R. s. 3</span> (ref. to <span dir=\"rtl\">מעין חתום</span>, <span class=\"citation\">Cant. IV, 12</span>) <span dir=\"rtl\">אלו הפנויות</span> this refers to the unmarried (men and women in Egypt). Tanḥ. Vayesheb 8 <span dir=\"rtl\">השתא הפ׳ שלכם אסורות לנו וכ׳</span> even the unmarried of your people are forbidden to us, how much more thou who art a man’s wife; a. fr.</div>","alt":["פְּנוּיָה"]},"22928":{"h":"פְּנוּיַיְתָא","r":"Q01168","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּנִיּוּתָא\">פְּנִיּוּתָא</a></div>","alt":[]},"22929":{"h":"פִּנּוּכָא","r":"Q01169","html":"<div class=\"sense\">, v. sub. <a href=\"#\" data-headword=\"פֶּנְטִיגוֹן\">פִּינּ׳</a>.</div>","alt":["פִּנּוּקָא"]},"22930":{"h":"פַּנּוּקְטִין","r":"Q01170","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנִּיקְטִין\">פַּנִּיקְטִין</a></div>","alt":[]},"22931":{"h":"פְּנַחְיָא","r":"Q01171","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (supposed to be fr. Pers. <i>pânah</i>) <i>protection, safeguard</i>. <span class=\"citation\">B. Kam. 103ᵃ</span> <span dir=\"rtl\">מידע … ופ׳ הוא דקבעינא</span> (Ms. M. <span dir=\"rtl\">פנחייה</span>) you know very well that I bought the field for myself, and that (in buying it in behalf of a third, influential person) I had in view only protection (against legal disputes). <span class=\"citation\">Yeb. 115ᵇ</span> <span dir=\"rtl\">לפ׳ שבקיה</span> he left the letters that were to mark the contents as sacred on the vessel merely for protection (that it might be spared by thievish servants).</div>","alt":["פְּנַחְיָה"]},"22932":{"h":"פנחרין","r":"Q01172","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנְתֵּיר\">פַּנְתֵּיר</a></div>","alt":[]},"22933":{"h":"פנטון","r":"Q01173","html":"<div class=\"sense\">, <span class=\"citation\">Esth. R. to VI, 10</span>, a. e., read: <span dir=\"rtl\">פְּרִיבָטוֹן</span>, v. <a href=\"#\" data-headword=\"דומין\">דומין</a>, a. <a href=\"#\" data-headword=\"קוֹמֵיס\">קוֹמֵיס</a>.</div>","alt":[]},"22934":{"h":"פַּנְטוֹס","r":"Q01174","html":"<div class=\"sense\"> (πάντως) <i>at all events, by all means</i>. <span class=\"citation\">Y. Snh. VI, beg. 23ᵇ</span>, v. <a href=\"#\" data-headword=\"נִיבְזִין\">נִיבְזִין</a>.</div>","alt":[]},"22935":{"h":"פַּנְטֵי","r":"Q01175","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַפַּנְטֵי\">אַפַּנְטֵי</a></div>","alt":[]},"22936":{"h":"*פַּנְטִי","r":"Q01176","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Panṭi</i>. <span class=\"citation\">Koh. R. to VIII, 3</span> <span dir=\"rtl\">לוי בן פ׳</span>; <span class=\"citation\">Meg. 31ᵇ</span> <span dir=\"rtl\">בר בוטי</span> (Ms. M. <a href=\"#\" data-headword=\"בּוּטָא\">בוטא</a>); <span class=\"citation\">Treat. Sof’rim XII, 3</span> <span dir=\"rtl\">בר פדא</span>; Y. Meg. III, 74ᵇ bot. <a href=\"#\" data-headword=\"פָּאטִי\">פאטי</a> (ed. Krot. <a href=\"#\" data-headword=\"פַּסְטִי\">פסטי</a>; ed. Crac. <span dir=\"rtl\">פכטי</span>); <span class=\"citation\">Yalk. Prov. 932</span> <a href=\"#\" data-headword=\"בּוּטָא\">בוטא</a>.</div>","alt":[]},"22937":{"h":"פֶּנְטִיגוֹן","r":"Q01177","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  (πεντάγωνος) <i>pentagonal</i>. <span class=\"citation\">Naz. 8ᵇ</span>; <span class=\"citation\">B. Bath. 164ᵇ</span> <a href=\"#\" data-headword=\"פ׳\">פ׳</a> (<span dir=\"rtl\">בית</span>) a pentagonal building; <span class=\"citation\">Tosef. Neg. VI, 3</span> <span dir=\"rtl\">פנטיגין</span> ed. Zuck. (oth. ed. <a href=\"#\" data-headword=\"פנטניז\">פנטניז</a>, corr. acc.).</div><div class=\"sense\"><b>—2)</b>  (πεντάγονος) <i>for the fifth time</i>. Naz. l. c.; B. Bath. l. c., v. <a href=\"#\" data-headword=\"דִּיגוֹן\">דִּיגוֹן</a>.</div><div class=\"sense\"><b>—3)</b> <i>fivefold</i>. <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 49</span> <span dir=\"rtl\">פ׳ היה</span> (not <span dir=\"rtl\">היא</span>; ed. Bub. <span dir=\"rtl\">טטראגון הוא</span>, corr. acc.) each Egyptian plague was fivefold.</div>","alt":["פִּינְ׳","פּוּנְ׳"]},"22938":{"h":"פַּנְטֵירָא","r":"Q01178","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנְדֵּירָא\">פַּנְדֵּירָא</a></div>","alt":["פַּנְטֵירִי I"]},"22939":{"h":"פַּנְטֵירִי II","r":"Q01179","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנְתֵּירִי\">פַּנְתֵּירִי</a></div>","alt":[]},"22940":{"h":"פנטיתא","r":"Q01180","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בָּטְנִיתָא\">בָּטְנִיתָא</a></div>","alt":[]},"22941":{"h":"פנטניז","r":"Q01181","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פֶּנְטִיגוֹן\">פֶּנְטִיגוֹן</a></div>","alt":[]},"22942":{"h":"פַּנְטַסְכִינָאֵי","r":"Q01182","html":"<div class=\"sense\"> nom. gent. pl. (denom. of πεντάσχοινος) <i>inhabitants of Pentaschoinos</i>, an Egyptian district [prob. meant for <i>Dodekaschoinos</i>, by confusion with next w.]. <span class=\"citation\">Targ. I Chr. I, 11</span> (ed. Rahmer <span dir=\"rtl\">פנטסכיינ׳</span>); <span class=\"citation\">Targ. Y. I Gen. X, 13</span> (h. text <span dir=\"rtl\">נפתחים</span>); <span class=\"citation\">Targ. Y. II ib. 14</span> (ed. Amst. <a href=\"#\" data-headword=\"פַּנְטַסְכִינָאֵי\">פְּנַטְסַכְנָ׳</a>; h. text <span dir=\"rtl\">כסלחים</span>).</div>","alt":["פַּנְטַסְכְנָ׳"]},"22943":{"h":"פנטפולוטי","r":"Q01183","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנְטַפּוֹלִיטָאֵי\">next w.</a></div>","alt":[]},"22944":{"h":"פַּנְטַפּוֹלִיטָאֵי","r":"Q01184","html":"<div class=\"sense\"> nom. gent. pl. (πενταπολῖται) <i>inhabitants of Pentapolis</i>, an Egyptian district (also called <i>Cyrenaica</i>). <span class=\"citation\">Targ. I Chr. I, 12</span> (h. text <span dir=\"rtl\">פתרסים</span>); <span class=\"citation\">Targ. Y. I Gen. X, 14</span> (ed. Vien. <a href=\"#\" data-headword=\"פנטפולוטי\">פַּנְטַפּוּלוֹטֵי</a>; h. text <span dir=\"rtl\">כסלחים</span>). [<span class=\"citation\">Targ. Y. II ib. 13</span> (ed. Vien. <span dir=\"rtl\">פַּנְטַפּוֹלַטָ׳</span>; h. text <span dir=\"rtl\">ענמים</span> or <span dir=\"rtl\">להבים</span>), prob. misplaced; v. <a href=\"#\" data-headword=\"פנטפולוטי\">preced.</a> art.]</div>","alt":[]},"22945":{"h":"פֶּנְטַקָקָה","r":"Q01185","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Penṭaḳaḳah</i>, surname of one who was said to have committed five sins (πέντα κακά) every day. <span class=\"citation\">Y. Taan. I, 64ᵇ</span> bot.</div>","alt":[]},"22946":{"h":"פַּנְטֵרָא","r":"Q01186","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנְדֵּירָא\">פַּנְדֵּירָא</a></div>","alt":["פַּנְטֵרִי I"]},"22947":{"h":"פַּנְטֵרִי II","r":"Q01187","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנְתֵּירִי\">פַּנְתֵּירִי</a></div>","alt":[]},"22948":{"h":"פני","r":"Q01188","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to turn</i> (one’s face). <span class=\"citation\">Yoma 17ᵇ</span>, a. e. <span dir=\"rtl\">שאתה פוֹנֶה</span>, v. <a href=\"#\" data-headword=\"פִּינָּה\">פִּינָּה</a>. <span class=\"citation\">Y. Ab. Zar. III, 42ᵇ</span> sq. (ref. to <span class=\"citation\">Lev. XIX, 4</span>) <span dir=\"rtl\">אל תִּפְנֶה לעובדן</span> do not turn thy face to them to worship them; <span dir=\"rtl\">אל תפנה לראותן ממש</span> it is meant literally, do not turn thy face to look at them; Sifra K’dosh. beg. <span dir=\"rtl\">אל תפנה לראותם וַדַּיי</span>. Ib. <span dir=\"rtl\">תחלתם אלילים הם אם פּוֹנֶה את אחריהן וכ׳</span> at first they are ‘nothings’, but if thou turnest after them, thou wilt make them (thy) gods; <span class=\"citation\">Yalk. Lev. 604</span>. Ib.; <span class=\"citation\">Sabb. 149ᵃ</span> (ref. to Lev. l. c.) <span dir=\"rtl\">אל תִּפְנוּ אֶל מדעתכם</span> turn not to the creation of your fancy (Rashi; anoth. interpret., v. infra); a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>to turn around, go away</i>. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\"><span dir=\"rtl\">כיון ששתה ופ׳ לילך</span> (<a href=\"#\" data-headword=\"מַעֲשֶׂה\">מעשה</a>) <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a></span> when he had drunk and turned to go away. <span class=\"citation\">Gen. R. s. 68</span> <span dir=\"rtl\">יצא משם פ׳ זיוה פ׳ הדרה</span> when he (the righteous) goes away from a place, its splendor is gone, its glory is gone; <span class=\"citation\">Ruth R. to I, 7</span>. Sifra K’dosh., ch. VIII, Par. 4, a. e. (ref. to <span dir=\"rtl\">ונתתי את פני</span>, <span class=\"citation\">Lev. XX, 6</span>; cmp. <a href=\"#\" data-headword=\"פְּנַאי\">פְּנַאי</a>) <span dir=\"rtl\">פּוֹנֶה אני מכל וכ׳</span>, v. <a href=\"#\" data-headword=\"עֵסֶק I\">עֵסֶק</a>. <span class=\"citation\">Midr. Prov. to XVI, 11</span> <span dir=\"rtl\">לִפְנוֹת היום</span> when the day was going away (towards evening); a. v. fr.</div><div class=\"sense\"><b>—3)</b>  (act. verb) <i>to turn, pervert</i>. <span class=\"citation\">Cant. R. to VII, 9</span> (play on <span dir=\"rtl\">אח̇ש̇ד̇רפ̇נ̇יא</span>, <span class=\"citation\">Dan. III, 2</span>) <span dir=\"rtl\">אלו ארכונות שהן נש̇ח̇ד̇ין ופ̇וני̇ן דין וכ׳</span> (not <span dir=\"rtl\">נחשדין</span>) those are the officers that are bribed and turn justice in any direction; ib. <span dir=\"rtl\">שמה̇ד̇ר̇ין פ̇נ̇ים ופ̇ונ̇ין דין</span> who respect persons and pervert justice; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to turn aside, go out</i>, (euphem.) <i>to ease one’s self</i>. <span class=\"citation\">Y. Sot. I, 16ᵈ</span> <span dir=\"rtl\">אם יִפְנֶה אחד מהן לצורכו</span> if one of them goes out for a human need. <span class=\"citation\">Toh. X, 2</span> <span dir=\"rtl\">ופוֹנִים</span> (<span class=\"citation\">Ber. 62ᵃ</span> <span dir=\"rtl\">ונִפְנִין</span>, <i>Nif.</i>).</div><div class=\"sense\"><b>—5)</b> <i>to vacate</i> (v. infra); <i>to free, release</i>. <span class=\"citation\">Pesik. R. s. 42</span> <span dir=\"rtl\">הספינה … ולא תטריח עליה לִפְנוֹתָהּ</span> (not <a href=\"#\" data-headword=\"טָרַח\">הטריח</a>) thy friend’s ship has been seized (for public service), and wilt thou not take pains to release it? <span dir=\"rtl\">ועכשיו של אחרים הוא פוֹנֶה ושלו אינה נפנית</span> and now he releases other men’s ships, and shall not his be released.?—<i>Part. pass.</i> <a href=\"#\" data-headword=\"פָּנוּי\">פָּנוּי</a>; f. <a href=\"#\" data-headword=\"פָּנוּי\">פְּנוּיָה</a> <i>vacant, empty, free</i>. <span class=\"citation\">Ber. 43ᵃ</span> <span dir=\"rtl\">אין בית הבליעה פ׳</span> his œsophagus is not free (which makes speaking dangerous). Y. Kil. III, beg. 28ᶜ <span dir=\"rtl\">אי אפשר … נקב אחד פ׳ וכ׳</span> it is not possible that there should not be one cavity free for planting &amp;c.; <span class=\"citation\">Y. Sabb. IX, 11ᵈ</span> bot. <span dir=\"rtl\">אפשר … פניי</span> (corr. acc.). <span class=\"citation\">Num. R. s. 14</span> <span dir=\"rtl\">והיה הבית פ׳</span> and the house was empty (none at home); a. fr.—V. <a href=\"#\" data-headword=\"פָּנוּי\">פָּנוּי</a>.</div><div class=\"sense\"><b>Pi. פִּינָּה</b> <div class=\"sense\"><b>1)</b> <i>to empty, remove, transfer</i>. <span class=\"citation\">Sabb. III, 5</span> <span dir=\"rtl\">המיחם שפִּינָּהוּ וכ׳</span> in the kettle which one has emptied (or: which one has removed from the oven) &amp;c.; <span class=\"citation\">ib. 41ᵃ</span> <span dir=\"rtl\">המיחם שפ׳ ממנו מים וכ׳</span> in the kettle out of which one has removed the hot water. <span class=\"citation\">Ib. XVIII, 1</span> <span dir=\"rtl\">מְפַנִּין אפי׳ וכ׳</span> you may clear away (on the Sabbath) even four or five piles … to make room for guests. Y. Gitt. VIII, 49ᵈ top <span dir=\"rtl\">אם … איש מְפַנֶּה</span> if the court belongs to the wife, the husband (after divorce) must vacate it, <span dir=\"rtl\">ושל איש אשה מְפַנָּה</span> and if it belongs to the husband, the wife must vacate it; <span dir=\"rtl\">מי מפנה מפני מי</span> which of them must vacate it for the other? <span class=\"citation\">Taan. 21ᵃ</span> <span dir=\"rtl\">בקשו תלמידיו לפַנּוֹת את וכ׳</span> his disciples wanted to move his bed first and then his furniture; <span dir=\"rtl\">פַּנּוּ את הכלים וכ׳</span> move the furniture first. <span class=\"citation\">Ab. III, 4</span> <span dir=\"rtl\">מפנה לבו לבטלה</span> empties his heart (of serious thoughts to make room) for frivolous subjects. <span class=\"citation\">Sabb. 149ᵃ</span> (ref. to <span class=\"citation\">Lev. XIX, 4</span>, v. supra) <span dir=\"rtl\">אל תְּפַנוּ אֵל מדעתכם</span> do not remove God from your minds (to make room for idols). <span class=\"citation\">B. Kam. 81ᵇ</span> <span dir=\"rtl\">מְפַנֵּיהוּ לשדה וכ׳</span> he must remove the corpse to &amp;c. Y. Maasr. II, 49ᵈ <span dir=\"rtl\">רוצה אדם לפנות עסקיו וכ׳</span> (ed. Krot. <span dir=\"rtl\">רוצה הוא אדם לפנע</span>; ed. Zyt. <span dir=\"rtl\">לפלה</span>, corr. acc.) a man is anxious to dispose of his goods in the first place he strikes &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to free, acquit</i>. Tanḥ. <span class=\"citation\">Vayikra 6</span> <span dir=\"rtl\">פ׳ לקרתני ולבן פלטרין וכ׳</span> he acquitted the commoner, but convicted the courtier. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לקרתני פִּנִּיתִי וכ׳</span> I acquitted the commoner, because he knows not the royal customs; a. fr.</div></div><div class=\"sense\"><b>Nif. נִפְנֶה</b> <div class=\"sense\"><b>1)</b> <i>to turn</i>. <span class=\"citation\">Midr. Till. to Ps. XVIII, 5</span> נִפְנֵיתִי לכאן וכ׳ I turned in all directions, and there is no redeemer but thee; <span class=\"citation\">Yalk. Sam. 157</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be removed, to die</i>. <span class=\"citation\">Gen. R. s. 98</span> <span dir=\"rtl\">שהיה נ׳ מן העולם</span> who was going to die. <span class=\"citation\">Tosef. Par. III</span> (<span class=\"citation\">II), 8</span> <span dir=\"rtl\">נ׳ בני</span> my son is dead (v. infra); a. e.</div><div class=\"sense\"><b>—3)</b> <i>to be free, at leisure</i>. Ib. <span dir=\"rtl\">לכשאֶפָּנֶה לך</span> when I shall have leisure for thee, i.e. I shall take revenge on thee, when opportunity offers; <span dir=\"rtl\">אמר לו כשתִּפָּנֶה</span> said he to him, when thou shalt be at leisure (or when thou shalt be dead, v. supra); ib. (Vers. of R. S. to <span class=\"citation\">Par. III, 8</span>) <span dir=\"rtl\">לא נ׳ בני שהעריב שמשו</span> my son has found no leisure (to take revenge), for his sun has set (he is dead). <span class=\"citation\">Ab. II, 4</span> <span dir=\"rtl\">אל תאמר לכשאפנה אשנה שמא לא תפנה</span> say not, when I shall be at leisure, I will study; may be thou wilt never find leisure; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to ease one’s self</i>. <span class=\"citation\">Sabb. 82ᵃ</span> <span dir=\"rtl\">הנצרך לִפָּנוֹת ואינו נפנה</span> (Alf. <span dir=\"rtl\">להִפָּנוֹת</span>) he who feels the want of easing himself, and is not relieved; ib. <span dir=\"rtl\">הנצרך ליפנות ואינו יכול ליפנות</span>. <span class=\"citation\">Ber. 62ᵃ</span> <span dir=\"rtl\">ונִפְנִין</span>, v. supra; a. fr.</div><div class=\"sense\"><b>—5)</b> <i>to be released</i>. Pesik. R. l. c., v. supra.</div></div><div class=\"sense\"><b>Hif. הִפְנָה</b> <div class=\"sense\"><i>to vacate.</i> <i>—Part. pass.</i> מוּפְנֶה <i>a</i>) <i>free, disengaged, single</i>. <span class=\"citation\">Yeb. III, 5</span> <span dir=\"rtl\">שלשה אחין … ואחד מ׳</span> three brothers two of whom were married to two sisters, and one is free (unmarried or married to one who is a stranger to his brothers’ wives); Y. ib. III, 4ᵈ top; a. e.—<i>b</i>) (dialectical exegesis) <i>free for interpretation, unnecessary for the plain sense or context</i>. <span class=\"citation\">Nidd. 22ᵇ</span> וייצר מ׳ משני צדדין מ׳ … ומ׳ גבי בהמה <i>vayitser</i> is free for interpretation on both sides, it is free with regard to man (<span class=\"citation\">Gen. II, 7</span>, because man’s creation is mentioned in <span dir=\"rtl\">ויברא</span>, <span class=\"citation\">ib. I, 27</span>), and free with regard to beasts (ib. II, 19, their creation being stated in <span dir=\"rtl\">ויעש</span>, ib. I, 25). Ib. <span dir=\"rtl\">כל גזירה שוה שאינה מוּפְנָה כל עיקר וכ׳</span> analogous words which are not entirely free (in both texts) cannot be made the basis for interpretation as <i>g’zerah shavah</i> (v. <a href=\"#\" data-headword=\"גְּזֵרָה\">גְּזֵרָה</a>). Ib. <span dir=\"rtl\">מ׳ מצד אחד</span> free in one of the texts; <span class=\"citation\">Sabb. 64ᵃ</span>; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְפַּנָּה</b> <div class=\"sense\"><b>1)</b> <i>to be vacated, cleared, removed</i>. Y. Naz. IX, 57ᵈ bot. <span dir=\"rtl\">כל הקברות מִתְפַּנִּין וכ׳</span> all graves may be vacated (transferred), except &amp;c.; <span class=\"citation\">Treat. S’maḥ. ch. XIV</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be released</i>. Pesik. R. l. c. <span dir=\"rtl\">כדי הוא</span> (<a href=\"#\" data-headword=\"ש\">ש</a>)<span dir=\"rtl\">תִּיתְפִּנֶּה</span> he deserves it to have his ship released (ed. Prag <span dir=\"rtl\">כדי הוא שיִתְפַּנֶּה</span> he deserves to be released).</div></div>","alt":["פָּנָה"]},"22949":{"h":"פְּנֵי I","r":"Q01189","html":"<div class=\"sense\"><b>1)</b> <i>to turn to</i> or <i>from; to go</i>. <span class=\"citation\">Targ. Y. Gen. XXIV, 49</span> (O. <i>Ithpe.</i>). <span class=\"citation\">Targ. O. Deut. XXIX, 17</span> (Y. I <i>Ithpe.</i>). <span class=\"citation\">Targ. O. Gen. XXIV, 63</span> <span dir=\"rtl\">למִפְנֵי רמשא</span> (ed. Amst. <span dir=\"rtl\">למִפַּנֵּי</span> <i>Ithpa.</i>) towards evening; a. fr.—<span class=\"citation\">Gen. R. s. 20</span>; <span class=\"citation\">Yalk. ib. 30</span> <span dir=\"rtl\">כמִפְנֵי רמשא</span> at the turn (approach) of the evening. <span class=\"citation\">Gen. R. s. 63</span> <span dir=\"rtl\">שלח … מִפְנֵי רמשא דערובתא</span> sent letters to Tiberias (to reach the elders) towards the evening of Friday; (Y. Ter. VIII, 46ᵇ bot. <span dir=\"rtl\">בערובתא עם מטמעי שמשא</span>); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to remove, empty</i>, v. infra., v. infra.</div><div class=\"sense\"><b>—3)</b> <i>to ease one’s self</i>. <span class=\"citation\">Ber. 62ᵃ</span> <span dir=\"rtl\">דבעינא למִפְנֵי</span> (Ms. F. <span dir=\"rtl\">לאַפְנוּיֵי</span> <i>Af.</i>).</div><div class=\"sense\"><b>Pa. פַּנֵּי</b> <div class=\"sense\"><b>1)</b> <i>to clear, empty, remove</i>. <span class=\"citation\">Targ. Y. Gen. XXIV, 20</span> Ar. (ed. <span dir=\"rtl\">ורוקינת</span>; h. text <span dir=\"rtl\">ותער</span>). <span class=\"citation\">Targ. Ps. LXXX, 10</span> (ed. Wil. <a href=\"#\" data-headword=\"פָּנִים\">פָּנִי׳</a> <i>Pe.</i>). <span class=\"citation\">Targ. O. Gen. XXIV, 31</span> (Y. <i>Pe.</i>). <span class=\"citation\">Targ. Is. XL, 3</span>; a. fr.—<i>Part. pass.</i> מְפַנָּא <i>clear, levelled</i>. <span class=\"citation\">Targ. Gen. XIV, 17</span> (O. ed. Vien. <span dir=\"rtl\">מַפְנָא</span> <i>Af.</i>).—Ber. l. c. <span dir=\"rtl\">פַּנּוּ לי דוכתא</span> Ms. M. (ed. <a href=\"#\" data-headword=\"פְּנֵי I\">פַּנִּי</a>, v. Rabb. D. S. a. l. note) clear a place for me. <span class=\"citation\">Taan. 20ᵇ</span> <span dir=\"rtl\">בעי לפַנּוּיֵיה</span> wanted to remove it (the wine); <span dir=\"rtl\">משכיה בשמעתא עד דפַנְּיֵיה</span> he kept him engaged in discussion on a tradition until he had removed it. <span class=\"citation\">Lam. R. to V, 1</span> (expl. <span dir=\"rtl\">ערו</span>, <span class=\"citation\">Ps. CXXXVII, 7</span>) <span dir=\"rtl\">פַּנּוּן פנון</span> clear, clear (the place, with ref. to <span dir=\"rtl\">ותער</span>, <span class=\"citation\">Gen. XXIV, 20</span>, v. supra), contrad. to <a href=\"#\" data-headword=\"פְּגַר I\">פגר</a>; Pesik. Zakhor, p. 26ᵃ <a href=\"#\" data-headword=\"פאטן\">פאטן</a> (read <span dir=\"rtl\">פָּאנוּן</span>); ib. ʿÃniya, p. 135ᵃ; <span class=\"citation\">Pesik. R. s. 32</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to free, acquit</i>. Y. Ber. IX, 13ᵃ sq. <span dir=\"rtl\">פַּנִּינָן יתיה</span>, v. <a href=\"#\" data-headword=\"דְּיוֹ I\">דֵּיו</a>. Y. Taan. I, 64ᵇ bot. <span dir=\"rtl\">מה מיעבד ומְפַנִּינֵיה</span> what to do in order to release him (from prison); <span dir=\"rtl\">הא לך פַּנְּיִי בעליך</span> here is money for thee, release thy husband; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to ease one’s self</i>. Y. Sabb. VI, 8ᶜ bot. <span dir=\"rtl\">עאל לפַנּוּיֵיה</span> (not <span dir=\"rtl\">לפונייה</span>) went to ease himself (v. infra).</div></div><div class=\"sense\"><b>Af. אַפְנֵי</b> <div class=\"sense\"><b>1)</b> <i>to turn, direct; to take aside</i>. <span class=\"citation\">Targ. II Sam. III, 27</span>. <span class=\"citation\">Ib. VI, 10</span>. <span class=\"citation\">Targ. Josh. XXIV, 23</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to vacate, free</i> (one’s mind); <i>to take time</i>. <span class=\"citation\">Targ. Nah. II, 9</span> <span dir=\"rtl\">לית דמַפְנֵי וכ׳</span> none take time to stand still.—Esp. <i>to make a text free for interpretation, to use as</i> <span dir=\"rtl\">מוּפְנֶה</span> (v. <a href=\"#\" data-headword=\"פני\">preced.</a>). <span class=\"citation\">Nidd. 22ᵇ</span> ויברא לגופיה וייצר לאַפְנוּיֵי <i>vayibra</i> (<span class=\"citation\">Gen. I, 27</span>) is needed for its own sake (to state the fact), <i>vayitser</i> (ib. II, 7) is to be used for interpretation. <span class=\"citation\">Sabb. 64ᵃ</span> <span dir=\"rtl\">בגד ועור … שמע מינה לאפנויי</span> what need was there to mention ‘garment and skin’ again in connection with creeping things? Learn from it, that it is to be used for exegetical purposes. Ib.; <span class=\"citation\">Snh. 40ᵇ</span> <span dir=\"rtl\">לאי אפנויי וכ׳</span>, v. <a href=\"#\" data-headword=\"לַאי\">לַאי</a>; a. fr.—Part. pass. <a href=\"#\" data-headword=\"מִפְנֵי\">מַפְנֵי</a>. Sabb. l. c. <span dir=\"rtl\">מ׳ דאי לא מ׳ וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">ומופנה דאי לאו מופנה</span>) it is free for exegesis, for if it were not free (but needed for its own sake) &amp;c. Ib. <span dir=\"rtl\">דמת נמי אפנויי מ׳</span> ed. Sonc. a. Ven. (v. Rabb. D. S. a. l. note 10; ed. <span dir=\"rtl\">מופנה</span>) ‘garment and skin’ in connection with corpses is likewise (unnecessary, and) free for exegesis; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to ease one’s self</i>. Ib. 140ᵇ <span dir=\"rtl\">לא תִיפְנוּן היכא דמַפְני וכ׳</span> do not go out to the same place that your men use &amp;c. <span class=\"citation\">Ber. 62ᵃ</span>, v. supra.</div></div><div class=\"sense\"><b>Ithpe. אִתְפְּנֵי  אִיפְּנֵי</b> <div class=\"sense\"><i>to turn; to go away</i>. <span class=\"citation\">Targ. Ex. III, 3</span> sq. <span class=\"citation\">Targ. Jud. XIX, 8</span>; a. fr.—<span class=\"citation\">Kidd. 65ᵃ</span> <span dir=\"rtl\">עד דמִיפְּני פיסחא</span> (prob. to be read: <span dir=\"rtl\">עד מ׳</span>) until Passover is past.</div></div>","alt":["פְּנָא"]},"22950":{"h":"פּנַי","r":"Q01190","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּנִים\">פְּנִים</a></div>","alt":["לִפְנַי"]},"22951":{"h":"פְּנֵי II","r":"Q01191","html":"<div class=\"sense\"> c. = h. <a href=\"#\" data-headword=\"פָּנוּי\">פָּנוּי</a> </div><div class=\"sense\"><b>1)</b> <i>free</i> (from service). <span class=\"citation\">Targ. Deut. XXIV, 5</span> (O. ed. Berl. <a href=\"#\" data-headword=\"פַּצִּיד\">פְּ׳</a>; h. text <a href=\"#\" data-headword=\"נקי\">נקי</a>).</div><div class=\"sense\"><b>—2)</b> <i>empty</i>. <span class=\"citation\">Gen. R. s. 65</span>, v. <a href=\"#\" data-headword=\"סוּלְגִּיתָא\">סוּלְגִּיתָא</a>; <span class=\"citation\">Koh. R. to V, 10</span>; <span class=\"citation\">Yalk. Gen. 115</span>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>turning around, restless</i>. <span class=\"citation\">Midr. Till. to Ps. XVIII, 5</span> (expl. <span dir=\"rtl\">אפפוני</span> ib.) <span dir=\"rtl\">פניא אנא מן עקיא</span> (ed. Bub. <span dir=\"rtl\">פנייא מן עקתא אנא</span>) I am restless on account of troubles.</div>","alt":["פָּנֵי","פַּנְיָא","(פַּנְיָה ) I"]},"22952":{"h":"פַּנְיָא","r":"Q01192","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּנֵי I\">פְּנֵי</a>; sub. <span dir=\"rtl\">דרמשא</span> or <span dir=\"rtl\">דשמשא</span>) <i>afternoon, sunset, evening; first part of the night</i>. <span class=\"citation\">Targ. O. Gen. XLIX, 27</span>. <span class=\"citation\">Targ. Y. Lev. VII, 16</span>. <span class=\"citation\">Targ. Y. Deut. VI, 7</span>; a. e.—<span class=\"citation\">B. Mets. 49ᵃ</span> <span dir=\"rtl\">אפ׳ דמעלי שבתא הוה</span> it was on a Friday towards evening. <span class=\"citation\">Yoma 14ᵇ</span> <span dir=\"rtl\">ולפ׳ מדו ליה</span> and towards evening they sprinkle upon him; <span class=\"citation\">ib. 19ᵃ</span> <span dir=\"rtl\">לבהדי פ׳</span>, <span dir=\"rtl\">להדי פ׳</span>; a. e.</div>","alt":["פַּנְיָיא II"]},"22953":{"h":"פַּנְיָא III","r":"Q01193","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> נְהַר פַּ׳ <i>N’har (Canal of) Pania</i> in Babylonia. <span class=\"citation\">Gitt. 65ᵇ</span> bot.</div>","alt":[]},"22954":{"h":"פַּנְיָאס","r":"Q01194","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנְיָיס\">פַּנְיָיס</a></div>","alt":[]},"22955":{"h":"פְּנִיּוּתָא","r":"Q01195","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּנֵי I\">פְּנֵי</a>; cmp. <a href=\"#\" data-headword=\"פְּנַאי\">פְּנַאי</a>) <i>turning away from everything, special business</i>. <span class=\"citation\">Targ. Y. Lev. XX, 6</span> (cmp. <a href=\"#\" data-headword=\"פָּנָה\">פָּנָה</a>); <span class=\"citation\">ib. 3</span> <span dir=\"rtl\">(פְּנוּיָי׳</span>); <span class=\"citation\">5</span>; a. e.</div>","alt":["פְּנוּיַיְתָא"]},"22956":{"h":"פְּנַיי","r":"Q01196","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּנַאי\">פְּנַאי</a>. [<span class=\"citation\">Y. Sabb. IX, 11ᵈ</span> bot., read: <a href=\"#\" data-headword=\"פָּנוּי\">פָּנוּי</a>, v. <a href=\"#\" data-headword=\"פָּנָה\">פָּנָה</a>]–<a href=\"#\" data-headword=\"לִפְנַי\">לִפְנַיי</a>, v. <a href=\"#\" data-headword=\"פְּנִים\">פְּנִים</a>.</div>","alt":[]},"22957":{"h":"פַּנְיָיס","r":"Q01197","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Paneas</i> (Cæsaræa Philippi, modern Bânias), a city in the north of Palestine. <span class=\"citation\">Targ. Y. I Num. XXXIV, 11</span> <span dir=\"rtl\">מערת פניאס</span> (not <a href=\"#\" data-headword=\"סְנִיאָס\">סניאס</a>); (Y. II <span dir=\"rtl\">אפמים</span>, <span dir=\"rtl\">אפמיס</span>; ib. 10 <span dir=\"rtl\">אפמיאה</span>, <span dir=\"rtl\">אפמיאם</span>, v. <a href=\"#\" data-headword=\"אַפַּמְיָא\">אַפַּמְיָא</a>). <span class=\"citation\">Targ. Cant. V, 4</span> <a href=\"#\" data-headword=\"פָּמִיאַס\">פָּמִיאַס</a> (some ed. <a href=\"#\" data-headword=\"פַּמְיָס\">פָּמְיַס</a>). <span class=\"citation\">Targ. I Chr. XXI, 2</span> (h. text <span dir=\"rtl\">דן</span>).—Y. Shebi. IX, 38ᵈ bot. <span dir=\"rtl\">דיקליטינוס אעיק לבני פנ׳</span> Diocletian oppressed the inhabitants of P. Y. Dem. II, 22ᵈ top. <span class=\"citation\">Gen. R. s. 63</span> <span dir=\"rtl\">נחת … בהדא פנ׳</span> (Var. <span dir=\"rtl\">פמ׳</span>) he (Diocletian) came down and made his stay at P. <span class=\"citation\">Meg. 6ᵃ</span>; <span class=\"citation\">Bekh. 55ᵃ</span> לשם זו פמ׳ Leshem is P.; Tanḥ. Ki Thissa 14 ליש זו פ׳ Layish is P.; Pirké d’R. EI. ch. XXVII דן הוא פ׳ Dan is P.; Midr. Sam. ch. XXXII (ref. to <span dir=\"rtl\">דנה</span>, <span class=\"citation\">II Sam. XXIV, 6</span>) <span dir=\"rtl\">דנה פ׳</span>. <span class=\"citation\">Gen. R. s. 33</span> <span dir=\"rtl\">מעיין … מערת פ׳</span> the spring … of the cavern of P.; Bekh. l. c. <span dir=\"rtl\">ירדן יוצא ממערת פ׳</span> the Jordan issues from the cavern of P.; <span class=\"citation\">B. Bath. 74ᵇ</span>.—<span class=\"citation\">Yalk. Deut. 820</span> (Moses prays) <span dir=\"rtl\">אכנס לה במחילה … מתחת לפַמְיָס</span> let me enter Palestine by the cave of Cæsarion, which is below P.; Mekh. B’shall., ʿĂmal., s. 2 <span dir=\"rtl\">לפניי ולפנים</span> (corr. acc.); a. fr.—Tanḥ. Naso 10; <span class=\"citation\">Num. R. s. 11</span> (ref. to <span class=\"citation\">Num. VI, 24</span>) <span dir=\"rtl\">יברכד … וישמרך שלא תהא עשוי במדינת פ׳ וכ׳</span> the Lord bless thee with wealth, and guard thee, that thou be not forced (to take office) in the city (or district) of P., and no <i>zimia</i> (v. <a href=\"#\" data-headword=\"זִימְיָא\">זִימְיָא</a>) be decreed over the city, and they say to thee, give gold (a reference to Roman extortions, v. supra).</div>","alt":["פַּנְיָאס","פַּמְיָיס"]},"22958":{"h":"פָּנִים","r":"Q01198","html":"<div class=\"sense\"> c. pl. (b. h.; <i>front, face; countenance, person</i>. Pesik. Baḥod., p. 110ᵃ, a. e. <span dir=\"rtl\">(<span dir=\"rtl\">פ׳ זעופות</span>) <span dir=\"rtl\">פ׳ זועפות</span></span>, v. <a href=\"#\" data-headword=\"זָעַף\">זָעַף</a>. Mekh. B’shall., Vayassʿa, s. 2; <span class=\"citation\">Yalk. Ex. 258</span>, v. <a href=\"#\" data-headword=\"חָשׁוּךְ\">חָשׁוּךְ</a>. <span class=\"citation\">Gen. R. s. 91</span> (ref. to <span class=\"citation\">Gen. XLI, 56</span>) <span dir=\"rtl\">אין פְּנֵי הארץ אלא עשירים</span> ‘the face of the land’ means the wealthy; <span dir=\"rtl\">בזמן שאדם עשיר יש לו פ׳ שמחים וכ׳</span> when a man is rich, he has a countenance which is glad to see his friend, but when he is poor <span dir=\"rtl\">אין לו פ׳ לראות וכ׳</span> he has not the face to see (his friend), because he is ashamed &amp;c. <span class=\"citation\">Keth. 7ᵇ</span> <span dir=\"rtl\">והוא שבאו פ׳ חדשות</span> provided a new face appears, i.e., a person that has not attended the wedding festivities before this. <span class=\"citation\">Ib. 8ᵃ</span> <span dir=\"rtl\">אי איכא פ׳ חדשות</span> if there is a new guest.—<span class=\"citation\">B. Kam. 96ᵇ</span> <span dir=\"rtl\">פ׳ חדשות באו לכאן</span> things have assumed a new face, i.e. the object after its transmutation is no longer the same as the one stolen; a. v. fr.—<span dir=\"rtl\">נשא פ׳</span>; <span dir=\"rtl\">גלה פ׳</span> &amp;c., v. <a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a>, <a href=\"#\" data-headword=\"גָּלָה\">גָּלָה</a> &amp;c.—<span class=\"citation\">Cant. R. to VII, 9</span> <span dir=\"rtl\">מהדרין פ׳</span>, v. <a href=\"#\" data-headword=\"פָּנָה\">פָּנָה</a>.—<span dir=\"rtl\">לחם הפ׳</span>, v. <a href=\"#\" data-headword=\"לֶחֶם\">לֶחֶם</a>.—Euphem. <span dir=\"rtl\">פ׳ של מטה</span>, or <a href=\"#\" data-headword=\"פ׳\">פ׳</a> <i>pudenda</i>. <span class=\"citation\">Sabb. 41ᵃ</span>. <span class=\"citation\">Ber. 24ᵃ</span> <span dir=\"rtl\">יכולה לכסות פָּנֶיהָ וכ׳</span> she can cover her nakedness &amp;c. <span class=\"citation\">Nidd. 14ᵇ</span>; a. fr.—Trnsf. <i>aspect, manner, way of interpretation</i>. <span class=\"citation\">Cant. R. to II, 4</span> <span dir=\"rtl\">התורה שנדרשת מ&quot;ט פ׳ טהור ומ&quot;ט פ׳ טמא</span> the Torah on the laws of which arguments are held, forty-nine in favor of ‘clean’ (permitted), and forty nine in favor of ‘unclean’ (forbidden); <span class=\"citation\">Num. R. s. 2</span> <span dir=\"rtl\">תורה שהיא נדרשת מ&quot;ט פ׳</span> the Torah which is interpreted in forty-nine ways; a. fr.—לְפָ׳ <i>a) for appearance sake, formally</i>. <span class=\"citation\">Meg. 12ᵃ</span> <span dir=\"rtl\">הם לא עשו אלא לפ׳ … אלא לפ׳</span> they (in bowing to the idol) acted merely for show (yielding to force), so the Lord dealt with them merely formally (not in full earnest, ref. to <span class=\"citation\">Lam. III, 33</span>).—<i>b</i>) <i>in front</i>; (of time) <i>before this, in the past</i>. <span class=\"citation\">Ḥag. II, 1</span> <span dir=\"rtl\">מה לפ׳ ומה לאחור</span> what was before (creation), and what will be in the future (when the world will be no more; <span class=\"citation\">Gen. R. s. 1</span> <span dir=\"rtl\">מה בי&quot;ת זה סתום … ופתוח מִלְּפָנָיו וכ׳</span> as the letter <a href=\"#\" data-headword=\"ב\">ב</a> (of <a href=\"#\" data-headword=\"בְּרֵאשִׁית\">בראשית</a>, <span class=\"citation\">Gen. I, 1</span>) is closed on all sides and open in front, so art thou not permitted to ask what is above and what is below, what was before and what will be hereafter; [oth. opin. <span dir=\"rtl\">מה לפ׳ ומה לאחור</span> what is in the extreme east beyond the sphere, and what in the west; v., however, Rashi Hag. l. c. (<span class=\"citation\">Ḥag. 11ᵇ</span>), a. <span class=\"citation\">Ḥag. 16ᵃ</span>].—<span class=\"citation\">Ber. 5ᵇ</span> <span dir=\"rtl\">לפני מטתי</span> in front of my bed, expl. <span dir=\"rtl\">סמוך למיטתי</span> immediately after rising. <span class=\"citation\">Ib. 7ᵃ</span>, a. fr. <span dir=\"rtl\">יהי רצון מִלְּפָנֶיךָ</span> (abbrev. <span dir=\"rtl\">יהר&quot;מ</span> may it be thy will. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">יהי רצון מִלְּפָנַי</span> may it be my will. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שלשה דברים בקש משה מִלִּפְנֵי וכ׳</span> for three things Moses prayed I before the Lord. <span class=\"citation\">Ib. I, 4</span> <span dir=\"rtl\">שתים לְפָנֶיהָ</span> two benedictions preceding it (the reading of the Sh’mʿa); a. v. fr.—Sifra Vayikra, Ḥobah, Par. 13, ch. XXIII <span dir=\"rtl\">אמש ושֶׁלְּפָנָיו ושֶׁלִּפְנֵי פנָיו</span> yesterday and the day before yesterday, and the day before that.—<span dir=\"rtl\">לִפְנֵי עִוֵּר</span> (also <span dir=\"rtl\">לפני</span> only, v. <a href=\"#\" data-headword=\"עִוֵּר I\"><span dir=\"rtl\">עִוֵּר</span> I</a>) <i>the law prohibiting an act which may lead a person to sin</i> (<span class=\"citation\">Lev. XIX, 14</span>). <span class=\"citation\">Ab. Zar. 14ᵃ</span> <span dir=\"rtl\">וליחוש … אל׳ מפקדינן אל׳ דל׳ לא וכ׳</span> (Ms. M. <span dir=\"rtl\">אל׳ עור</span>) but should we not apprehend, that he might sell (the incense) to others, who will burn it for idols? Said A., we are commanded to guard against an act directly leading to sin, but not against one that may indirectly cause sin; <span class=\"citation\">ib. 21ᵃ</span>.—מִפְּנֵי <i>for the sake of, on account of</i>; <span dir=\"rtl\">מפני ש־</span> <i>because</i>. <span class=\"citation\">Sabb. II, 5</span> <span dir=\"rtl\">מ׳ שהוא מתיירא מ׳ גוים וכ׳</span> because he is afraid of invaders, of robbers, or of an evil wind. <span class=\"citation\">Ber. I, 3</span> <span dir=\"rtl\">וסכנתי בעצמי מ׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"סָכַן II\"><span dir=\"rtl\">סָכַן</span> II</a>. <span class=\"citation\">Ib. 3ᵃ</span> <span dir=\"rtl\">מ׳ מה נכנסת וכ׳</span> why didst thou enter these ruins? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מ׳ שלשה דברים</span> for three reasons; <span dir=\"rtl\">מ׳ חשד</span> because you give cause to suspicion; <span dir=\"rtl\">מ׳ המפולת</span> because debris may fall on you; <span dir=\"rtl\">מ׳ המזיקין</span> on account of demons; a. v. fr.—בִּפְנֵי <i>in the presence of</i>. Ib.ᵇ <span dir=\"rtl\">ב׳ המת</span> in the presence of a dead person. Ib. 31ᵇ <span dir=\"rtl\">המורה הלכה ב׳ רבו</span> he who gives a decision in his teacher’s presence; a. v. fr.—<span class=\"citation\">Kidd. 64ᵇ</span> <span dir=\"rtl\">הנודר עד פְּנֵי פסח וכ׳</span>; <span class=\"citation\">Ned. VIII, 2</span> <span dir=\"rtl\">הנודר עד לִפְנֵי הפסח וכ׳</span> if one says in his vow, ‘until <i>p’né (lifné)</i> Passover’, R. M. says, he is bound until Passover begins; R. J. says, until it is passed; <span class=\"citation\">Kidd. 65ᵃ</span>, v. <a href=\"#\" data-headword=\"פְּנֵי I\"><span dir=\"rtl\">פְּנֵי</span> I</a>.</div>","alt":[]},"22959":{"h":"פְּנִים","r":"Q01199","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <span class=\"citation\">I Kings VI, 29</span>; <a href=\"#\" data-headword=\"פָּנִים\">preced.</a>, cmp. ἐνώπια) [<i>that which is in front of you when you enter,] inside, interior</i>; <a href=\"#\" data-headword=\"לִפְנַי\">לִפְנַי</a> (<a href=\"#\" data-headword=\"וְ\">וְ</a>)לִפְ׳ <i>the innermost</i>. Tosef. Yom. II, 5 <span dir=\"rtl\">היו מסיקין מבחוץ והיה נאפה ונרדה מבפ׳</span> they heated the oven towards the outside (placed the fuel in front), and it (the show-bread) was baked and shoveled out from the interior; <span class=\"citation\">Yoma 38ᵃ</span>, v. <a href=\"#\" data-headword=\"נָסַק\">נָסַק</a>. <span class=\"citation\">B. Mets. 16ᵃ</span> <span dir=\"rtl\">זו אינה צריכה לפ׳</span> this (question) need not be brought inside (the college); <span dir=\"rtl\">צריכה לפ׳ ולפני לפ׳</span> it must be brought inside and even to the innermost. <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> bot. <span dir=\"rtl\">יכנס … לפ׳</span> let R. Ḥ. the elder go into the interior (to the front benches); <span dir=\"rtl\">לפ׳ ממני</span> in front of me?; <span dir=\"rtl\">ר׳ … לפ׳ ור׳ ישמעאל … לפני לפ׳</span> R. Ḥ. … to the interior, R. I. … to the innermost (the very first); <span class=\"citation\">Y. Keth. XII, 35ᵃ</span> bot. <span dir=\"rtl\">לפני ולפ׳</span>. <span class=\"citation\">Y. Yeb. VI, 7ᶜ</span> <span dir=\"rtl\">אחותו לעולם היא</span> (<span dir=\"rtl\">מִ</span>)<span dir=\"rtl\">בִּפְ׳ וכ׳</span> a priest’s sister is always inside (a member of the priestly family), until she steps outside (by marriage). <span class=\"citation\">Sabb. I, 1</span>; a. v. fr.—<span dir=\"rtl\">לפ׳ משורת הדין</span>, v. <a href=\"#\" data-headword=\"דִּין II\"><span dir=\"rtl\">דִּין</span> II</a>.—Esp. <i>the Temple precincts, the Temple and the priests’ court</i>; <span dir=\"rtl\">לפני ולפ׳</span> <i>the innermost, Holy of Holies</i>. <span class=\"citation\">Ab. Zar. 50ᵃ</span> <span dir=\"rtl\">בעינא כעין פ׳</span> (for a gift to an idol to be permanently forbidden for use, even after cancellation,) it is required that it be like the offerings in the interior Temple (sacrifices, incense &amp;c., to the exclusion of votive gifts like candles, jewels &amp;c.). <span class=\"citation\">Men. 9ᵃ</span> <span dir=\"rtl\">לא בעיא בפ׳</span> must not necessarily be done within the Temple precincts, opp. to <span dir=\"rtl\">חוץ לחומת העזרה</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נהי … פ׳ מיהת בעיא</span> although it may be done by a non-priest, it must at least be done within &amp;c. <span class=\"citation\">Y. Yoma V, 42ᵇ</span> bot. <span dir=\"rtl\">כלפי לפ׳</span> towards the interior; a. fr.—Ib.; <span class=\"citation\">Y. Kil. VIII, 31ᶜ</span> bot. <span dir=\"rtl\"><span dir=\"rtl\">מהו מבפ׳</span> (<a href=\"#\" data-headword=\"מָהוּ\">מהו</a>) <span dir=\"rtl\">מבחוץ</span></span> does it belong inside (to the Holy of Holies) or outside (to the Holy)?, v. <a href=\"#\" data-headword=\"טְרַקְסִין\">טְרַקְסִין</a>.</div>","alt":[]},"22960":{"h":"פְּנִימוֹן","r":"Q01200","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>P’nimon</i>. <span class=\"citation\">Y. Ter. III, end, 42ᵇ</span> אבא פ׳ Abba P.—<span class=\"citation\">Num. R. s. 9</span> (<span class=\"citation\">Tosef. Sot. I, 1</span> Var. ed. Zuck.; <span class=\"citation\">Sot. 4ᵃ</span> <a href=\"#\" data-headword=\"פְּלִימוֹ\">פלימו</a>, Y. ib. I, 16ᶜ bot. <span dir=\"rtl\">מיניימין</span>).</div>","alt":[]},"22961":{"h":"פְּנִימִי","r":"Q01201","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>inner, interior, innermost, central</i>. <span class=\"citation\">Erub. 65ᵇ</span> <span dir=\"rtl\">ישראל ונכרי בפ׳ וכ׳</span> if an Israelite and a gentile live in the inner court, and an Israelite in the outer court. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פ׳ במקומו מהו</span> dare the resident of the inner court move things within its precincts? Tanḥ. Naso 5 <span dir=\"rtl\">פתח את הפ׳ וכ׳</span> he opened the central door and went to the outer room. <span class=\"citation\">Zeb. 51ᵃ</span>, a. fr. <span dir=\"rtl\">מזבה הפ׳</span> the inner altar (in the Holy); a. v. fr.—<span class=\"citation\">Gen. R. s. 21</span> (ref. to <span dir=\"rtl\">פלמוני</span>, <span class=\"citation\">Dan. VIII, 13</span>) <span dir=\"rtl\">תרגם עקילס לפ׳ … לפנים ממלאכי וכ׳</span> Aquila translated it ‘to him who was inside’, which means Adam whose partitioned seat was in front of the ministering angels (v. <a href=\"#\" data-headword=\"פְּנִים\">פְּנִים</a>); Yalk. Dan. 1066.—Pl. <span dir=\"rtl\">פְּנִימִיִּים</span>; f. <span dir=\"rtl\">פְּנִימִיּוֹת</span>. <span class=\"citation\">Zeb. 52ᵇ</span> <span dir=\"rtl\">דמים הפ׳</span> blood to be sprinkled in the Holy; <span dir=\"rtl\">שיריים הפ׳</span> the remnants of blood sprinkled in the Holy. <span class=\"citation\">Tam. I, 4</span>; Y. Yoma II, 39ᶜ, v. <a href=\"#\" data-headword=\"אָכַל\">אָכַל</a>; a. fr.</div>","alt":["פְּנִימִית"]},"22962":{"h":"פניקא","r":"Q01202","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 26</span> some ed., v. <a href=\"#\" data-headword=\"פָּגָנִיקָא\">פָּגָנִיקָא</a>.</div>","alt":[]},"22963":{"h":"פַּנִּיקְטִין","r":"Q01203","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (παννύκτοι = παννύχιοι, S.) <i>all-night watches</i> (<i>pervigilia</i>), in gen. <i>camps</i>. <span class=\"citation\">Targ. Ps. LXVIII, 30</span> מפַּנִּיקְטֵיהוֹן Ar. a. Ms. (ed. <span dir=\"rtl\">מִפַּנְקְטֵי׳</span>, ed. Wil. <span dir=\"rtl\">מְפַ׳</span>, corr. acc.).—<span class=\"citation\">Lev. R. s. 1</span> <span dir=\"rtl\">היו אומות העולם … מתוך פַּנִּיקְטֵיהֶן</span> (some ed. <span dir=\"rtl\">פַּנּוּקְ׳</span>) the nations were in danger of hearing the voice of divine revelation and being frightened out of their camps (Tanḥ. T’rum. 9 <span dir=\"rtl\">לתוך אהליהם</span>), v. <a href=\"#\" data-headword=\"תָּרַז\">תָּרַז</a>.—<span class=\"citation\">Gen. R. s. 16</span> in three things Greece was in advance of Rome, <span dir=\"rtl\">בנימוסין ובפניקטין וכ׳</span> Ar. (Ms. Paris <span dir=\"rtl\">בפנקיטין</span>, ed. <span dir=\"rtl\">בפנקיסין</span>, <span dir=\"rtl\">בפנקיסון</span></div>","alt":[]},"22964":{"h":"פְּנִיקְיָא","r":"Q01204","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (Phœnicia) <i>Phœnicia</i>. <span class=\"citation\">Gen. R. s. 90</span> end, v. <a href=\"#\" data-headword=\"פְּלַסְטִינִי\">פְּלַסְטִינִי</a>.</div>","alt":["פְּנִקְ׳"]},"22965":{"h":"פְּנַךְ","r":"Q01205","html":"<div class=\"sense\">, <i>Pa.</i> פַּנֵּיךְ <i>to drive on, speed</i>. <span class=\"citation\">Targ. Jud. V, 22</span>.—Part. pass. <span dir=\"rtl\">מְפַנַּךְ</span>, pl. <span dir=\"rtl\">מְפַנְּכִין</span>. <span class=\"citation\">Targ. Nah. III, 2</span>. <span class=\"citation\">Targ. Jer. LI, 27</span>.</div>","alt":[]},"22966":{"h":"פָּנָס","r":"Q01206","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (φανός) <i>torch; lantern.</i> <span class=\"citation\">Kel. II, 4</span> <span dir=\"rtl\">פ׳ שיש בו וכ׳</span> a lantern which contains a receptacle for oil; <span class=\"citation\">Tosef. Kel. B. Bath. VII, 11</span> <span dir=\"rtl\">פ׳ של זכוכית וכ׳</span> a glass lantern &amp;c. (v. <a href=\"#\" data-headword=\"פוקטו\">פוקטו</a>). <span class=\"citation\">Tosef. Ber. VI</span> (<span class=\"citation\">V), 7</span> <a href=\"#\" data-headword=\"פָּאנָס\">פָאנָס</a> ed. Zuck. (Var. <a href=\"#\" data-headword=\"פָּנָס\">פנס</a>); <span class=\"citation\">Ber. 53ᵇ</span>; Y. ib. VIII, 12ᵇ bot. <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">היה נוטל הפ׳ וכ׳</span> he (the Lord) took the torch and carried light before them (ref. to <span class=\"citation\">Ex. XIII, 21</span>). <span class=\"citation\">Ex. R. s. 25</span> <span dir=\"rtl\">בשר ודם תלמוד טוען פ׳ וכ׳</span> among human beings, the pupil carries the light before his teacher; not so the Lord &amp;c.; a. fr.—Pl. <span dir=\"rtl\">פְּנָסִין</span>. <span class=\"citation\">Gen. R. s. 3</span>, beg. <span dir=\"rtl\">הדליק נרות ופ׳</span> lighted lamps and torches. Ib. s. 68 <span dir=\"rtl\">כבו את הנרות כבו הפ׳</span> put out the lamps, put out the torches. <span class=\"citation\">Koh. R. to XII, 7</span> <span dir=\"rtl\">הדליק נרות ופ׳ לשמה וכ׳</span> he lighted lamps and torches in the name of Rome (as an augury for a war against Rome), and they would not burn; a. e.</div>","alt":[]},"22967":{"h":"פנסטה","r":"Q01207","html":"<div class=\"sense\">, <span class=\"citation\">Y. B. Bath. VIII, 16ᵃ</span> <span dir=\"rtl\">בעי מימר פ׳</span>, read: <span dir=\"rtl\">פְּשָׁטֵיה</span>, v. <a href=\"#\" data-headword=\"פְּשָׁטָא\">פְּשָׁטָא</a></div>","alt":[]},"22968":{"h":"פנע","r":"Q01208","html":"<div class=\"sense\">, <span class=\"citation\">Y. Maasr. II, 49ᵈ</span> <span dir=\"rtl\">לפנע</span> ed. Krot., v. <a href=\"#\" data-headword=\"פָּנָה\">פָּנָה</a> <i>Pi.</i>—<span class=\"citation\">Targ. Jer. XXIII, 29</span>, v. <a href=\"#\" data-headword=\"נְפַע\">נְפַע</a>.</div>","alt":[]},"22969":{"h":"פָּנַק","r":"Q01209","html":"<div class=\"sense\"> [<i>to go out</i>,] <i>to be a freeman; to live in luxury</i> (cmp. <a href=\"#\" data-headword=\"חִטָּא I\"><span dir=\"rtl\">חָטָא</span> I</a>).</div><div class=\"sense\"><b>Pi. פִּנֵּק</b> <div class=\"sense\"><b>1)</b> <i>to treat as a freeman, to indulge, spoil by indulgence</i>. <span class=\"citation\">Gen. R. s. 22</span> (ref. to <span class=\"citation\">Prov. XXIX, 21</span>) <span dir=\"rtl\">שמְפַנֵּק וכ׳</span>, v. <a href=\"#\" data-headword=\"מָנוֹן\">מָנוֹן</a>; <span class=\"citation\">Yalk. Prov. 962</span> (<span class=\"citation\">ib. 961</span> <span dir=\"rtl\">ממתק</span>).</div><div class=\"sense\"><b>—2)</b> <i>to treat tenderly; to cultivate, improve, embellish</i>. <span class=\"citation\">Sifré Deut. 306</span> <span dir=\"rtl\">מְפַנְּקִים</span>; <span class=\"citation\">Yalk. ib. 942</span>, v. <a href=\"#\" data-headword=\"עָדַן\">עָדַן</a>; a. e.—<i>Part. pass.</i> מְפוּנָּק <i>delicately reared</i>. Mekh. Mishp. s. 8, v. <a href=\"#\" data-headword=\"עָדַן\">עָדַן</a>; <span class=\"citation\">Yalk. Ex. 339</span>. <span class=\"citation\">Lev. R. s. 19</span> <span dir=\"rtl\">היה מפ׳ ומת בידם</span> he was delicate (unused to hardship), and died under their hands.</div></div>","alt":[]},"22970":{"h":"פְּנַק","r":"Q01210","html":"<div class=\"sense\"><i>Pa.</i> <span dir=\"rtl\">פַּנֵּיק</span> <a href=\"#\" data-headword=\"פָּנַק\">same</a>. <span class=\"citation\">Targ. Is. XXIII, 4</span>. <span class=\"citation\">Targ. Esth. II, 9</span>. <span class=\"citation\">Ib. 12</span>; a. fr.—Part. pass. <a href=\"#\" data-headword=\"מְפַנַּק\">מְפַנַּק</a> q. v.—V. <a href=\"#\" data-headword=\"אִסְפְּנִיקִי\">אִסְפְּנִיקָא</a>.</div><div class=\"sense\"><b>Ithpa. אִתְפַּנֵּק</b> </div><div class=\"sense\"><b>Ithpe. אִתְפְּנֵיק</b> <div class=\"sense\"><b>1)</b> <i>to delight one’s self</i>. <span class=\"citation\">Targ. Ps. XXXVII, 4</span>; <span class=\"citation\">11</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to play the nobleman, be imperious</i>. <span class=\"citation\">Targ. Prov. XXIX, 21</span> <span dir=\"rtl\">מִתְפְּנֵיק מן וכ׳</span> he who plays the gentleman in his youth, will become a servant and finally be driven out (h. text <a href=\"#\" data-headword=\"מְפַנַּק\">מְפַנֵּק</a>).</div></div>","alt":[]},"22971":{"h":"פִּנְקַאי","r":"Q01211","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּינְקַאי\">פִּינְקֵאי</a></div>","alt":[]},"22972":{"h":"פַּנִּקְטִין","r":"Q01212","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנִּיקְטִין\">פַּנִּיקְטִין</a></div>","alt":["פנקיסין"]},"22973":{"h":"פִּנְקֵס","r":"Q01213","html":"<div class=\"sense\">, v. sub. <a href=\"#\" data-headword=\"פֶּנְטִיגוֹן\">פִּינ׳</a>.</div>","alt":["פִּנַקְסָא","פִּנַקְסָה"]},"22974":{"h":"פַּנְקְרִיסִין","r":"Q01214","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (πάγχρυσος) [<i>all-gold</i>,] name of <i>a fruit</i>, prob. <i>apricots</i>. <span class=\"citation\">Y. Sot. I, 17ᵇ</span> top <span dir=\"rtl\">יפה מפ׳ וכ׳ …</span> better were the late fruits … than the apricots &amp;c.; ib. IX, 24ᵇ bot.; (<span class=\"citation\">Y. Peah VII, 20ᵃ</span> bot. <span dir=\"rtl\">מפרסקין</span>). <span class=\"citation\">Y. Sabb. III, 5ᵈ</span> <span dir=\"rtl\">וטעמן יפה כפ׳</span> and their taste was as delicious as that of apricots; <span class=\"citation\">Y. Ter. II, 41ᶜ</span> bot. (corr. acc.).—Y. Ab. Zar. II, 41ᵈ <span dir=\"rtl\">פ׳ … שלהן</span> apricots pressed by gentiles (prob. to be read, as Bab. <span class=\"citation\">Ab. Zar. 38ᵇ</span>; <span class=\"citation\">Tosef. ib. IV</span> (<span class=\"citation\">V), 11</span> <a href=\"#\" data-headword=\"קַפְרִיסִין\">קַפְרִיסִין</a>).</div>","alt":["פַּנְקְרִסִין"]},"22975":{"h":"פנרתא","r":"Q01215","html":"<div class=\"sense\">, Targ. II Esth. I, 2, v. <a href=\"#\" data-headword=\"פַּרְוָותָא\">פַּרְוָותָא</a></div>","alt":[]},"22976":{"h":"פַּנְתָּא","r":"Q01216","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַפַּנְתָּא\">אַפַּנְתָּא</a></div>","alt":[]},"22977":{"h":"פַּנְתֵּיר","r":"Q01217","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πάνθηρ) <i>panther</i> or <i>leopard</i>.—Pl. <a href=\"#\" data-headword=\"פַּנְתֵּר\">פַּנְתֵּירִין</a>, <a href=\"#\" data-headword=\"פַּנְתֵּר\">פַּנְתֵּרִין</a>. <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 45</span> (expl. <span dir=\"rtl\">ערב</span> ib.) <span dir=\"rtl\">מין חיה הוא ושמה פ׳ והביאן וכ׳</span> (not <span dir=\"rtl\">והביאו</span>) it is a species of wild beasts named leopards, and the Lord sent them &amp;c.; <span class=\"citation\">Yalk. ib. 820</span>.</div>","alt":["פַּנְתֵּר"]},"22978":{"h":"פַּנְתֵּירִי","r":"Q01218","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פַּנְתֵּיר\">preced.</a>) [<i>spotted stone</i>,] name of a <i>jewel</i> (corresp. to h. <a href=\"#\" data-headword=\"יָשְׁפֵּה\">ישפה</a>). <span class=\"citation\">Targ. O. Ex. XXVIII, 20</span> ed. Berl. (ed. <a href=\"#\" data-headword=\"פַּנְדֵּירָא\">פַּנְטֵירֵי</a>; Y. <a href=\"#\" data-headword=\"אַפַּנְטוֹר\">אַפַּנְטוּרִין</a>, ed. Vien. <span dir=\"rtl\">אפנטורע</span>, corr. acc.); ib. XXXIX, 13 (ed. Vien. <a href=\"#\" data-headword=\"פַּנְתֵּר\">פַּנְתֵּרֵי</a>, corr. acc.). <span class=\"citation\">Targ. Ez. XXVIII, 13</span> <a href=\"#\" data-headword=\"פַּנְתֵּר\">פַּנְתֵּירִין</a>.</div>","alt":[]},"22979":{"h":"פַּנְתֵּר","r":"Q01219","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּנְתֵּירִי\">preced.</a> wds.</div>","alt":["פַּנְתֵּרִי","פַּנְתֵּרִין"]},"22980":{"h":"פָּס","r":"Q01220","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"אָפֵס\">אָפֵס</a>, <i>Pas</i>, name of two Amoraim. <span class=\"citation\">Y. Taan. IV, 68ᵃ</span>. <span class=\"citation\">Y. Yoma V, 43ᵃ</span> bot.—<span class=\"citation\">Y. Kidd. III, 64ᵃ</span> bot. (v. Fr. M’bo, p. 122ᵃ).</div>","alt":[]},"22981":{"h":"פַּס I","r":"Q01221","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסַס\">פְּסַס</a></div>","alt":[]},"22982":{"h":"פַּס II","r":"Q01222","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>strip, stripe</i>.—Pl. <a href=\"#\" data-headword=\"פַּסִּים\">פַּסִּים</a>, <a href=\"#\" data-headword=\"פַּסִּים ²\">פַּסִּין</a>. <span class=\"citation\">Gen. R. s. 84</span> (ref. to <span class=\"citation\">Gen. XXXVII, 3</span> sq., a. <span class=\"citation\">Ps. LXVI, 5</span> sq.; v. <a href=\"#\" data-headword=\"עֲלִילָה\">עֲלִּילָה</a>) why ‘did they hate him’? That (in the course of events it should come about that) <span dir=\"rtl\">שיקרע הים לפניהם פ׳ פ׳</span> the sea be rent before them in strips (ed. Wil. <span dir=\"rtl\">פ̇ס̇י̇ם̇ פס ים</span> <i>passim</i> alludes to ‘strip of the sea’).—Esp. (cmp. <a href=\"#\" data-headword=\"פֶּרֶק\">פֶּרֶק</a>) <span dir=\"rtl\">פס יד</span>, <i>palm, the hand from the wrist to the tip of the finger</i>; <span dir=\"rtl\">פס רגל</span> <i>the foot to the ankle</i>, interch. with <span dir=\"rtl\">פִּסַּת</span>, <a href=\"#\" data-headword=\"פִּיסָּא\">פִּיסַּת</a> (constr. of <a href=\"#\" data-headword=\"פִּסָּה\">פִּסָּה</a>). Ib. (expl. <span dir=\"rtl\">פסים</span>, Gen. l. c.) <span dir=\"rtl\">שהיתה מגעת עד פס ידו</span> the coat reached with its sleeves to his wrist; <span dir=\"rtl\">שהיתה … בפס ידו</span> it was very fine and light, and could be (compressed and) hidden in his hand (cmp. <a href=\"#\" data-headword=\"מַלְמֵלָה\">מַלְמֵלָה</a>). <span class=\"citation\">Meg. IV, 8</span> (<span class=\"citation\">24ᵇ</span>) <span dir=\"rtl\">נתנה … על פס ידו וכ׳</span> if he placed the T’fillin on his forehead or on his palm. <span class=\"citation\">Yoma 87ᵃ</span> (play on <span dir=\"rtl\">ה̇ת̇ר̇פ̇ס̇</span>, <span class=\"citation\">Prov. VI, 3</span>) [read:] <span dir=\"rtl\">אם ממון יש לו בידך ה̇ת̇ר לו פ̇ס̇ת יד וכ׳</span> if thou owest him (whom thou hast wronged) money, untie thy hand to him (pay him), if not (if thou hast otherwise wronged him), get several friends around him (to ask his pardon in their presence); <span class=\"citation\">B. Mets. 115ᵃ</span>; <span class=\"citation\">B. Bath. 173ᵇ</span>; <span class=\"citation\">Yalk. Prov. 938</span>. <span class=\"citation\">Gen. R. s. 78</span> (play on <span dir=\"rtl\">מ̇ת̇ר̇פ̇ס בר̇צ̇י</span>, <span class=\"citation\">Ps. LXIV, 31</span>) <span dir=\"rtl\">מ̇ת̇יר̇ את הפ̇ס̇ ומ̇ת̇ר̇צ̇ה בכסף</span> he (Edom-Rome) opens his hand (for bribery), and is appeased with silver; <span class=\"citation\">Ex. R. s. 35</span> <span dir=\"rtl\">מתרת את הפס וכ׳</span> she (Rome) opens &amp;c.; <span class=\"citation\">Yalk. Ps. 800</span> <span dir=\"rtl\">שפושטין פסת יד … ואין עושין ר̇צ̇ון וכ׳</span> they stretch forth their hand to accept silver, and then do not what the givers desire; <span class=\"citation\">Pes. 118ᵇ</span> שפושטין פסת יד וכ׳ Ms. M. (ed. <span dir=\"rtl\">שפושטין יד</span>). <span class=\"citation\">Yoma 47ᵃ</span> <span dir=\"rtl\">על פ׳ ידו</span> up to his wrist, v. <a href=\"#\" data-headword=\"חָפָה\">חָפָה</a>; Sifra Vayikra, N’dab., ch. X, Par. 9 <span dir=\"rtl\">חופה את פס ידו וכ׳</span> he bends his hand (grabbing) in the pan &amp;c. Ohol. I, 8 <span dir=\"rtl\">שלשים בפס הרגל</span> thirty joints in the foot. <span class=\"citation\">Yalk. Sam. 143</span> <span dir=\"rtl\">חלילה … פ׳ יד ופ׳ רגל ועקב מגולין</span> never were their wrists or their feet or their heels seen uncovered; Midr. Sam. ch. XXV (corr. acc.); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>partition, board, barrier</i>. <span class=\"citation\">Erub. 5ᵃ</span> <span dir=\"rtl\">אם יש שם פם ארבעה</span> if a bar of four handbreadths is left or placed above the breach. <span class=\"citation\">Ib. 10ᵇ</span> <span dir=\"rtl\">עושה פם גבוה עשרה וכ׳</span> he cuts a board ten handbreadths high and four cubits long &amp;c.; a. fr.—Pl. as ab. <span class=\"citation\">Ib. II, 1</span> <span dir=\"rtl\">עושין פ׳ לביראות וכ׳</span> you must place partitions around watering stations in the shape of four cornerpieces &amp;c., v. <a href=\"#\" data-headword=\"דְּיוֹמַד\">דְּיוֹמַד</a>. <span class=\"citation\">Ib. 11ᵃ</span> <span dir=\"rtl\">פַּסֵּי ביראות</span> the partitions of watering stations; a. fr.—[<span class=\"citation\">Maasr. I, 7</span>, v. <a href=\"#\" data-headword=\"פַּץ\">פַּץ</a>.]</div><div class=\"sense\"><b>—3)</b> pl. (v. ) <i>tax</i>; <span dir=\"rtl\">פַּסֵּי העיר</span> town tax (used for maintaining the safety of the town). <span class=\"citation\">Tosef. Peah IV, 9</span> <span dir=\"rtl\">לפ׳ העיר לשנים וכ׳</span> ed. Zuck. (ed. <span dir=\"rtl\">לעניי</span>, corr. acc.) in order to be assessed for the town tax one must have been a resident for twelve months; <span class=\"citation\">B. Bath. 8ᵃ</span>; <span class=\"citation\">Y. Peah VIII, 21ᵃ</span> bot. <span dir=\"rtl\">לפסין ולצדקות</span> for the town tax and for the charities, expl. for the salaries of public school teachers; <span class=\"citation\">Y. B. Bath. I, beg. 12ᵈ</span> <span dir=\"rtl\">לפסים ולזימיות</span> for town tax and town fines.</div>","alt":[]},"22983":{"h":"פַּס","r":"Q01223","html":"<div class=\"sense\"><b>1)</b> <i>strip, stripe.</i>—Pl. <a href=\"#\" data-headword=\"פְּסַל\">פַּסֵּי</a>. <span class=\"citation\">Targ. O. Gen. XXXVII, 3</span>; <span class=\"citation\">23</span> (ed. Berl. <a href=\"#\" data-headword=\"פְּסֵי\">פָּסֵי</a>, <a href=\"#\" data-headword=\"פְּסֵי\">פַּסֵי</a>). <span class=\"citation\">Targ. II Sam. XIII, 18</span> (ed. Wil. <a href=\"#\" data-headword=\"פְּסֵי\">פַּסֵי</a>).</div><div class=\"sense\"><b>—2)</b>  פ׳ ידא <i>palm</i>; <span dir=\"rtl\">פס רגלא</span> <i>foot</i>, v. <a href=\"#\" data-headword=\"פִּיסְּתָא\">פִּיסְּתָא</a>.</div><div class=\"sense\"><b>—3)</b> <i>piece, portion; bread</i>. <span class=\"citation\">Bekh. 43ᵇ</span>, v. <a href=\"#\" data-headword=\"סְקִיפַס\">סְקִיפַס</a>. <span class=\"citation\">Lam. R. to III, 16</span> Ar., v. <a href=\"#\" data-headword=\"*פּטִילִיק\">פְּטִילִיק</a>.—<span class=\"citation\">Y. Ber. VI, 10ᵇ</span> bot., v. <a href=\"#\" data-headword=\"פִּיסְּתָא\">פִּיסְּתָא</a>.</div><div class=\"sense\"><b>—4)</b>  (from its shape, cmp. <a href=\"#\" data-headword=\"כַּף\">כַּף</a>) <i>spade</i> or <i>shovel</i>. <span class=\"citation\">Lev. R. s. 24</span>; s. 25 Ar., v. <a href=\"#\" data-headword=\"מַכּוֹשָׁא II\"><span dir=\"rtl\">מַכּוֹשָׁא</span> II</a>.—</div><div class=\"sense\"><b>*5)</b>  <span dir=\"rtl\">פ׳ דביר</span> (v. <a href=\"#\" data-headword=\"פַּס II\">preced.</a>) <i>watering station</i>. <span class=\"citation\">Targ. Y. I Deut. XXXIII, 3</span> <span dir=\"rtl\">ושריין כמין פ׳ דב׳</span> (not <span dir=\"rtl\">דבַר</span>) and they rest as it were at a watering station; (Y. II <span dir=\"rtl\">על פום דבירוי</span>).</div>","alt":["פַּסָּא","פִּסָּא","פִּי׳"]},"22984":{"h":"פְּסָא","r":"Q01224","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסֵי\">פְּסֵי</a></div>","alt":[]},"22985":{"h":"פסאני","r":"Q01225","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּסְיוֹנִי\">פִּסְיוֹנִי</a></div>","alt":[]},"22986":{"h":"פְּסָאקָא","r":"Q01226","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>P’saḳa</i>, surname of one R. Yitsḥaḳ. <span class=\"citation\">Lam. R. to I, 9</span> <span dir=\"rtl\">ר׳ יצחק פ׳</span> (<span class=\"citation\">Yalk. Is. 302</span> <span dir=\"rtl\">יצחק פסיקתא</span>); cmp. <a href=\"#\" data-headword=\"פַּסְקַת\">פַּסְקַת</a>.</div>","alt":[]},"22987":{"h":"פָּסַג","r":"Q01227","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">פִּסֵּג</span> </div><div class=\"sense\"><b>1)</b> <i>to divide, branch off</i>; denom. <a href=\"#\" data-headword=\"פְּסִיגָא\">פְּסִיגָה</a>. <span class=\"citation\">Par. XI, 9</span> <span dir=\"rtl\">מְפַסְּגוֹ ואוגדו</span> he severs the stalks of hyssop and ties them; <span dir=\"rtl\">פְּסָגוֹ ולא אגדו</span> if he severed, but failed to tie them.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"פְּסִיגָא\">פְּסִיגָה</a>) <i>to cut off sprays, to thin</i>. <span class=\"citation\">B. Kam. 119ᵇ</span> <span dir=\"rtl\">מְפַסְּגֵי אילנות ומפסגי גפנים</span> (Ms. F. <span dir=\"rtl\">ומפסיקי</span>; Ar. <span dir=\"rtl\">ומפסקי</span>) those hired to thin trees or vines; (Tosef. ib. XI, 18 <span dir=\"rtl\">מפסקי גפנים</span> only). <span class=\"citation\">M. Kat. 3ᵃ</span> <span dir=\"rtl\">אין מְפַסְּגִין באילן</span> you must not thin trees (during the festive week; Rashi: <i>support the branches</i>); a. e.—<span class=\"citation\">Tosef. B. Mets. II, 28</span>, v. infra.</div><div class=\"sense\"><b>Hif. הִפְסִיג</b> <div class=\"sense\"><i>to cut one’s way through branches, pass through woods, vineyards</i> &amp;c., <i>trespass; to lead through thickets</i> &amp;c. <span class=\"citation\">B. Kam. 81ᵇ</span> <span dir=\"rtl\">התועה … מַפְסִיג ויורד מפסיג ועולה וכ׳</span> if one loses his way in vineyards, he may cut his way through up and down &amp;c.; <span dir=\"rtl\">הרואה … מפסיג וכ׳</span> he who sees a fellowman lost in vineyards, may make a way for him … until he brings him &amp;c.; <span class=\"citation\">Tosef. B. Mets. II, 28</span> <span dir=\"rtl\">מְפַסְּגוֹ בשדות וכ׳</span> may lead him through fields and vineyards. Ib. <span dir=\"rtl\">הוא עצמו … מפסיג וכ׳</span> ed. Zuck. (ed. <span dir=\"rtl\">מפסג</span></div></div>","alt":[]},"22988":{"h":"פְּסַג","r":"Q01228","html":"<div class=\"sense\"><b>1)</b> <i>to divide, cut apart</i>. <span class=\"citation\">Targ. Y. Gen. XV, 10</span> (O. <a href=\"#\" data-headword=\"פְּלַג I\">פלג</a>, h. text <span dir=\"rtl\">בתר</span>). <span class=\"citation\">Ib. XXVI, 31</span>. <span class=\"citation\">Targ. Y. Lev. I, 6</span>; a. e.—Part. pass. <a href=\"#\" data-headword=\"פְּסַג\">פָּסִיג</a>. <span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">פ׳ תִּרְעָךְ</span> may thy ill-luck be broken (no more evil befall thee,—which allowing the meaning ‘may thy gate (<a href=\"#\" data-headword=\"תְּרַע\">תַּרְעָא</a>) be broken’, is corrected to <span dir=\"rtl\">יסוג תורעך</span>, v. <a href=\"#\" data-headword=\"סוּג\">סוּג</a> ch.).</div><div class=\"sense\"><b>—2)</b> <i>to break through a snare, escape</i>. <span class=\"citation\">Gen. R. s. 79</span> <span dir=\"rtl\">כד שמע … פַּסְגָּא</span> when R. S. heard the heavenly voice say <i>demos</i> (v. <a href=\"#\" data-headword=\"דִּימוֹס II\"><span dir=\"rtl\">דִּימוֹס</span> II</a>), it (the bird) escaped; Yalk. ib. 133 <span dir=\"rtl\">פשגא</span> (Ar. <span dir=\"rtl\">הות פשגה</span>).—<span class=\"citation\">B. Kam. 81ᵇ</span> <span dir=\"rtl\">דנִיפְסוֹג</span> that he may be permitted to break through (the vineyard), v. <a href=\"#\" data-headword=\"פָּסַג\">preced.</a></div><div class=\"sense\"><b>Pa. פַּסֵּיג</b> </div><div class=\"sense\"><b>Af. אַפְסֵיג</b> <div class=\"sense\"><i>to divide</i>. <span class=\"citation\">Targ. Y. Lev. I, 12</span> <span dir=\"rtl\">יַפְסֵיג</span> (some ed. <span dir=\"rtl\">יְפַסֵּיג</span>; ed. Vien. <span dir=\"rtl\">פַּיְסֵג</span>, corr. acc.). Targ. Y. I. <span class=\"citation\">Ex. XXIX, 17</span> <span dir=\"rtl\">תַּפְסֵיג</span> (Y. II <span dir=\"rtl\">תְּפַסֵּג</span>; ed. Vien. <span dir=\"rtl\">תְּפַסֵּק</span>).—<span class=\"citation\">Lam. R. to V, 5</span> <span dir=\"rtl\">מְפַסֵּג ליה וכ׳</span> (ed. Wil. <span dir=\"rtl\">מפסל</span>, corr. acc.) he cut him up limb by limb.</div></div>","alt":[]},"22989":{"h":"פַּסְגָּא","r":"Q01229","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"פְּסַג\">preced.</a>) <i>piece, part.</i> <span class=\"citation\">Targ. Y. Gen. XXVI, 31</span>. <span class=\"citation\">Ib. XV, 10</span>.—<i>Pl.</i> <span dir=\"rtl\">פַּסְגִּין</span>, <a href=\"#\" data-headword=\"פִּיסְטִין\">פִּסְ׳</a>, <span dir=\"rtl\">פִּסְגַּיָּא</span>, <a href=\"#\" data-headword=\"פְּגִימִין\">פִּי׳</a>. Ib. <span class=\"citation\">Targ. Y. Ex. XXIX, 17</span>; a. e.—<i>Fem.</i> pl. <span dir=\"rtl\">פִּסְגָּתָא</span>, <a href=\"#\" data-headword=\"פְּגִימִין\">פִּי׳</a>. Y. Ned. IV, 38ᵈ top (expl. <span dir=\"rtl\">תמחוי החוזר</span>) <a href=\"#\" data-headword=\"פ׳\">פ׳</a> cut portions on the plate.</div>","alt":["פִּסְ׳","פִּיסְ׳"]},"22990":{"h":"פִּסְגָּה","r":"Q01230","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פַּסְגָּא\">preced.</a> wds., v. <a href=\"#\" data-headword=\"פְּסִיגָא\">פְּסִיגָה</a>) </div><div class=\"sense\"><b>1)</b> <i>branch, bough</i>, opp. to <a href=\"#\" data-headword=\"אֶשְׁכּוֹל\">אשכול</a> the trunk with the grape clusters. the trunk with the grape clusters.</div><div class=\"sense\"><b>—2)</b>  (b. h.) pr. n. <i>Pisgah</i>, the summit of Mount Nebo. <span class=\"citation\">Sifré Deut. 357</span> (ref. to XXXIV, 1) <span dir=\"rtl\">מה פ׳ זו מופרשת מן האשכול ואינה מופרשת וכ׳</span> as the branch is separate from the trunk, yet not detached, so was Moses’ grave &amp;c., v. <a href=\"#\" data-headword=\"תָּאַם\">תָאַם</a>; <span class=\"citation\">Yalk. ib. 963</span>.</div>","alt":[]},"22991":{"h":"פָּסַד","r":"Q01231","html":"<div class=\"sense\"><i>to cut, diminish</i>; <a href=\"#\" data-headword=\"פָּסַד\">פָּסֵד</a> (cmp. <span dir=\"rtl\">פגם</span>, <span dir=\"rtl\">פסל</span>) <i>to lose in value, deteriorate</i>. <span class=\"citation\">Y. Maasr. V, beg. 51ᶜ</span> <span dir=\"rtl\">שהן פְּסֵידִין</span> because they spoil; <span dir=\"rtl\">חטין אינן פ׳</span> wheat does not spoil.</div><div class=\"sense\"><b>Hif. הִפְסִיד</b> <div class=\"sense\"><b>1)</b> <i>to suffer loss, to lose, be at a disadvantage</i>. <span class=\"citation\">B. Mets. III, 4</span>, sq. <span dir=\"rtl\">אם כן מה ה׳ הרמאי</span> if this is the law, what does the dishonest man lose (what risk does he run to prevent him from claiming more than his due)? <span class=\"citation\">Ber. I, 2</span> <span dir=\"rtl\">הקורא … לא ה׳</span> he who reads the Sh’mʿa after this, loses nothing; expl. <span class=\"citation\">ib. 10ᵇ</span> <span dir=\"rtl\">לא ה׳ ברכות</span> he does not lose the benedictions (he may recite the benedictions preceding and following the Sh’mʿa as usual). Y. ib. I, 2ᵇ top <span dir=\"rtl\">אין תפלה מַפְסֶדֶת</span> a prayer never loses its value. <span class=\"citation\">Gen. R. s. 70</span> <span dir=\"rtl\">נדרו והִפְסִידוּ</span> vowed and suffered thereby. <span class=\"citation\">Keth. XIII, 3</span> <span dir=\"rtl\">אדמון אומר … הִפְסַרְתִּי</span> upon which Admon said, shall I be at a disadvantage, because I am a male heir?; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to injure, cause loss to</i>. <span class=\"citation\">Tosef. Bets. II, 6</span> <span dir=\"rtl\">שמא יַפְסִידוּ את וכ׳</span> lest they do harm to the inhabitants; a. e.—[Y. Ber. IX, 14ᵇ bot. <span dir=\"rtl\">והפסיד אלא</span>, read: <span dir=\"rtl\">והפשיר עמו</span>, v. <a href=\"#\" data-headword=\"פָּשַׁר\">פָּשַׁר</a>.]</div></div><div class=\"sense\"><b>Nif. נִפְסַד</b> <div class=\"sense\"><i>to lose</i>. <span class=\"citation\">Pes. 50ᵇ</span> <span dir=\"rtl\">יש זריז ונ׳</span>, v. <a href=\"#\" data-headword=\"זָרִיז\">זָרִיז</a>; <span class=\"citation\">Tosef. Yeb. IV, 8</span> <span dir=\"rtl\">ומַפְסִיד</span> (<i>Hif.</i>).</div></div>","alt":[]},"22992":{"h":"פְּסַד","r":"Q01232","html":"<div class=\"sense\"><b>1)</b> <i>to be diminished, scarce</i>. <span class=\"citation\">Targ. Y. Gen. XLVII, 16</span> (h. text) <span dir=\"rtl\">אפס</span>).</div><div class=\"sense\"><b>—2)</b> <i>to diminish, destroy</i>. <span class=\"citation\">Targ. Ps. XLIV, 3</span> (ed. Lag. <span dir=\"rtl\">שלח</span>).</div><div class=\"sense\"><b>—3)</b> <i>to ruin, spoil</i>. <span class=\"citation\">Pes. 55ᵇ</span> <span dir=\"rtl\">פַּסְדָא לה ביעי לגמרי</span> she (the hatching hen) has spoiled the eggs entirely (made them unfit to be eaten).—Part. pass. <a href=\"#\" data-headword=\"פָּסֵיד\">פָּסֵיד</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אכתי לא פְסֵידֵי ביעי וכ׳</span> (Ms. M. <span dir=\"rtl\">פסיד לה ביעא</span>; Ms. K. <span dir=\"rtl\">לא פַסְדָּה לה</span>) the eggs are not yet entirely spoiled.</div><div class=\"sense\"><b>Af. אַפְסַד  אַפְסֵיד</b> <div class=\"sense\"><i>to injure; to spoil, ruin</i>. <span class=\"citation\">Keth. 56ᵃ</span> <span dir=\"rtl\">איהו הוא דא׳ אנפשיה</span> he brought the loss upon himself. <span class=\"citation\">B. Bath. 139ᵇ</span> <span dir=\"rtl\">אינהו אַפְסִידוּ אנפשייהו</span> they brought the loss &amp;c. <span class=\"citation\">Sabb. 108ᵇ</span> <span dir=\"rtl\">אַפְסוּדֵי קא מַפְסִידְנָא ליה</span> (by salting the radish) I vitiate it. <span class=\"citation\">Keth. 61ᵇ</span> <span dir=\"rtl\">אַפְסְדַת לסעודתא וכ׳</span> (Rashi: <span dir=\"rtl\">אַפְסַדְתָּא</span>) thou hast spoiled the king’s meal. <span class=\"citation\">B. Mets. 117ᵇ</span> כמה מַפְסְדָה עלייה בבית Ar. (ed. <span dir=\"rtl\">מפסיד</span>, corr. acc.) by how much does the upper story impair (the durability of) the lower story?; a. fr.</div></div>","alt":[]},"22993":{"h":"פְּסֵדָא","r":"Q01233","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסִידָא\">פְּסִידָא</a></div>","alt":[]},"22994":{"h":"פסדיות","r":"Q01234","html":"<div class=\"sense\">, Y’lamd. to <span class=\"citation\">Gen. XXVIII, 10</span> sq., quot. in Ar., read: <span dir=\"rtl\">בֵּי סַדְיוֹת</span>, v. <a href=\"#\" data-headword=\"סַדְיָא\">סַדְיָא</a></div>","alt":[]},"22995":{"h":"פִּסָּה","r":"Q01235","html":"<div class=\"sense\">, constr. <span dir=\"rtl\">פִּסַּת</span>, v. <a href=\"#\" data-headword=\"פַּס II\"><span dir=\"rtl\">פַּס</span> II</a></div>","alt":[]},"22996":{"h":"פָּסָה","r":"Q01236","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פסי\">פסי</a></div>","alt":[]},"22997":{"h":"פְּסוּגָא","r":"Q01237","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּסַג\">פְּסַג</a>) <i>piece.</i>—Pl. <span dir=\"rtl\">פְּסוּגַיָּא</span>. <span class=\"citation\">Targ. Y. Ex. XII, 40</span>; <span class=\"citation\">Targ. I Chr. VII, 21</span> <span dir=\"rtl\">ביני פ׳</span> at the covenant between the pieces, v. <a href=\"#\" data-headword=\"בְּתָרִים\">בְּתָרִים</a>; Targ. Y. I. <span class=\"citation\">Lev. XXVI, 42</span> <span dir=\"rtl\">פִּיסּוּגַיָּא</span>.</div>","alt":[]},"22998":{"h":"פסוורוס","r":"Q01238","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּוְוסָרוֹס\">פִּוְוסָרוֹס</a></div>","alt":[]},"22999":{"h":"פְּסוֹל","r":"Q01239","html":"<div class=\"sense\">(denom. of <a href=\"#\" data-headword=\"פָּסוּל\">פָּסוּל</a>) <i>to be</i> or <i>become disqualified, unfit</i>. <span class=\"citation\">Men. 100ᵃ</span> <span dir=\"rtl\">ליפסל ליקדוש ולִיפְסוֹל</span> (strike out <span dir=\"rtl\">ליפסל</span>, v. Rabb. D. S. a. l. note) let it become sacred (by being put in a sacred vessel) and subsequently become unfit (when it becomes overdue); <span class=\"citation\">ib.ᵇ</span>; <span class=\"citation\">Yoma 29ᵇ</span> <span dir=\"rtl\">תקדוש ותִפְסוֹל</span>; a. e.—V. <a href=\"#\" data-headword=\"פְּסַל\">פְּסַל</a>.</div>","alt":[]},"23000":{"h":"פִּסּוּל","r":"Q01240","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיסּוּל\">פִּיסּוּל</a></div>","alt":[]},"23001":{"h":"פָּסוּל","r":"Q01241","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַל\">פָּסַל</a>; cmp. <span dir=\"rtl\">פגם</span>) <i>defective, blemished, unfit, disqualified</i>, opp. <a href=\"#\" data-headword=\"כָּשֵׁר I\">כשר</a>. <span class=\"citation\">Zeb. II, 1</span> <span dir=\"rtl\">נשפך ואספו פ׳ …</span> if the blood was spilt over the pavement, and one collects it again, it is unfit for sprinkling. <span class=\"citation\">Ib. 3</span>, v. <a href=\"#\" data-headword=\"פִּיגּוּל\">פִּיגּוּל</a>. <span class=\"citation\">Ḥull. I, 4</span> <span dir=\"rtl\">שחיטתו פ׳</span> his slaughtering act is illegitimate (the animal so slaughtered is forbidden to be eaten). Ib. <span dir=\"rtl\">כשר בשחיטה פ׳ במליקה וכ׳</span> what is right in slaughtering, is illegal in pinching (the neck) &amp;c. <span class=\"citation\">Zeb. III, 2</span> <span dir=\"rtl\">קבל הכשר ונתן לפ׳</span> if a person qualified for the service received the blood and handed it to one disqualified. <span class=\"citation\">Gen. R. s. 70</span> אליעזר פְּסוּל הבית היה וכ׳ Eliezer was the disqualified (servant) of the house, and yet it is written &amp;c. <span class=\"citation\">Kidd. IV, 6</span> <span dir=\"rtl\">פ׳ מן הכהונה לעולם</span> is forever unfit for priesthood (his female descendants are forbidden to priests); <span dir=\"rtl\">בתו פ׳ לכהונה</span> his daughter cannot marry a priest; a. v. fr.—Pl. <span dir=\"rtl\">פְּסוּלִים</span>, <span dir=\"rtl\">פְּסוּלִין</span>; <span dir=\"rtl\">פְּסוּלוֹת</span>. <span class=\"citation\">Snh. III, 3</span> <span dir=\"rtl\">אלו הן הפ׳</span> the following are disqualified (for judges or witnesses). <span class=\"citation\">Gitt. IX, 4</span> <span dir=\"rtl\">שלשה גטין פ׳</span> three kinds of letters of divorce are invalid. <span class=\"citation\">Zeb. III, 1</span> <span dir=\"rtl\">כל הפ׳ ששחטו וכ׳</span> if any of those unfit for priestly service did the slaughtering, his act is legal. <span class=\"citation\">Kidd. 77ᵃ</span> <span dir=\"rtl\">כל שנולדה מן הפ׳</span> born of disqualified parents; <span dir=\"rtl\">מאי פ׳ אילימא פ׳ לו</span> what do you mean by ‘disqualified’? Do you mean disqualified (forbidden in marriage) to him (the father)? Ib. <span dir=\"rtl\">פְּסוּלֵי כהונה</span> persons disqualified for the priesthood (degraded priests). Y. ib. III, 64ᶜ <span dir=\"rtl\">כשרין הוזהרו על הפ׳ וכ׳</span> qualified persons are cautioned (in the Law) not to marry disqualified women, … but qualified women are not forbidden to marry disqualified men. <span class=\"citation\">Shek. VII, 7</span> <span dir=\"rtl\">הקינין הפ׳</span> consecrated birds that became disqualified (or unavailable) for sacrificial purposes. <span class=\"citation\">Bekh. V, 1</span>, a. fr. <span dir=\"rtl\">פסולי המוקדשים</span> dedicated objects which became unfit for the purpose to which they were dedicated; a. v. fr.</div>","alt":["פְּסוּלָה"]},"23002":{"h":"פְּסוּל","r":"Q01242","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסוּל\">preced.</a>) <i>blemish, disqualification.</i> <span class=\"citation\">Yoma I, 1</span> <span dir=\"rtl\">שמא יארע בו פ׳</span> because something might happen that would disqualify him for the service of the day. <span class=\"citation\">Pes. 56ᵃ</span> <span dir=\"rtl\">שמא … יש במיטתי פ׳</span> is there perhaps, which God forbid, a blemish in my couch (an unworthy person among my descendants)? <span class=\"citation\">Tosef. Mikv. I, 19</span>, a. e. <span dir=\"rtl\">מקוה פְּסוּלוֹ בעצמו</span> a bath (that has become unfit for ritual purposes) has its unfitness in itself; <span dir=\"rtl\">בן גרושה … שפסולו באחרים</span> whereas the son of a divorced woman (married to a priest) owes his disqualification to others (his parents). Ib. <span dir=\"rtl\">פסולו ביחיד</span> his (its) unfitness is caused by a single person; <span dir=\"rtl\">פסולו בבית דין</span> by a court; <span class=\"citation\">Mikv. III, 1</span> <span dir=\"rtl\">לעולם הוא בפסולו וכ׳</span> it remains in its condition of unfitness until &amp;c. <span class=\"citation\">Zeb. VIII, 3</span> <span dir=\"rtl\">אין מביאין קדשים לבית הפ׳</span> we must not wittingly cause sacred meat to be brought to the place where the unfit things are burnt. <span class=\"citation\">Ib. X, 7</span> <span dir=\"rtl\">שלא יביא … לידי פ׳</span> for one must not cause T’rumah to become unfit; a. v. fr.</div>","alt":[]},"23003":{"h":"פְּסוּלָא I","r":"Q01243","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"פְּסוּל\">same</a>. <span class=\"citation\">Targ. Y. I Gen. XXII, 10</span> (ed. Vien. <a href=\"#\" data-headword=\"פְּסוּלָה\">פְּסוּלָה</a>). <span class=\"citation\">Targ. Y. I Deut. VI, 4</span>. <span class=\"citation\">Targ. II Sam. XXII, 27</span>, v. <a href=\"#\" data-headword=\"פְּסִילָא\">פְּסִילָא</a>; a. e.—<span class=\"citation\">Keth. 62ᵇ</span> <span dir=\"rtl\">חס ושלום פ׳ איכא</span> is there, which God forbid, a blemish in the family?—Pl. <span dir=\"rtl\">פְּסוּלַיָּיא</span>. Y. Kidd. III, 64ᵈ top <span dir=\"rtl\">הב דעתך דאית תמן מן אינון פ׳ וכ׳</span> be careful, for disqualifications (persons disqualified for intermarriage) are there, that thou connect not thyself with them.</div>","alt":[]},"23004":{"h":"פְּסוּלָא II","r":"Q01244","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּסַל\">פְּסַל</a>) </div><div class=\"sense\"><b>1)</b> <i>chip, block</i>. <span class=\"citation\">Targ. Is. LI, 1</span>.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"פִּסּוּלָא\">next art.</a>) <i>worthless matter, dross</i>. Ib. I, 22 (h. text <a href=\"#\" data-headword=\"סיגים\">סיגים</a>). <span class=\"citation\">Targ. Ez. XXII, 18</span> <a href=\"#\" data-headword=\"פְּסוֹלֶת\">פְּסוּלַת</a> constr.; a. e.—Pl. m. <span dir=\"rtl\">פְּסוּלַיָּיא</span>. <span class=\"citation\">Targ. Ps. CXIX, 119</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">סוּלַיָּא</span>; h. text <span dir=\"rtl\">סגים</span>).</div>","alt":[]},"23005":{"h":"פִּסּוּלָא","r":"Q01245","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיסּוּלָא\">פִּיסּוּלָא</a></div>","alt":[]},"23006":{"h":"פְּסוּלָה","r":"Q01246","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פָּסוּל\">פָּסוּל</a>, a. <a href=\"#\" data-headword=\"פְּסוּלָא I\"><span dir=\"rtl\">פְּסוּלָא</span> I</a>.</div>","alt":[]},"23007":{"h":"פְּסוֹלֶת","r":"Q01247","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַל\">פָּסַל</a>) </div><div class=\"sense\"><b>1)</b> <i>chips, stone-dust</i>. <span class=\"citation\">Y. Shek. V, 49ᵃ</span> bot. <span dir=\"rtl\">פסל לך שתהא הפ׳ שלך</span> ‘hew for thyself’ (<span class=\"citation\">Ex. XXXIV, 1</span>) that the chips be thine; <span class=\"citation\">Ned. 38ᵃ</span> <span dir=\"rtl\">פְּסוֹלְתָּן שלך</span> their chips be thine. Ib.; Y. Shek. l. c. <span dir=\"rtl\">מפ׳ של לוחית העשיר וכ׳</span> Moses became rich from the chips of the tablets; a. e.</div><div class=\"sense\"><b>—2)</b> <i>refuse, base metal, worthless matter</i>. <span class=\"citation\">Sabb. 138ᵃ</span> <span dir=\"rtl\">נוטל אוכל ומניח את הפ׳</span> he takes up what is eatable, and leaves the refuse. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פ׳ למעלה וכ׳</span> (when you sift,) the refuse is on the surface, and the eatable peas are at the bottom. <span class=\"citation\">Num. R. s. 16</span> <span dir=\"rtl\">שהפ׳ שלה משובח וכ׳</span> the inferior soil of Palestine was much superior to the best of &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שכן התגרין מראין את הפ׳ וכ׳</span> so the merchants show the inferior goods first &amp;c. <span class=\"citation\">Y. Gitt. I, 43ᵈ</span> top (ref. to <span dir=\"rtl\">מקצות</span>, <span class=\"citation\">I Kings XII, 31</span>) <span dir=\"rtl\">מן הקוצים שבעם ומן הפ׳ וכ׳</span> of the thorns among the people, the refuse &amp;c. <span class=\"citation\">Sifré Deut. 312</span> <span dir=\"rtl\">יצא ממנו פ׳</span> (sub. <a href=\"#\" data-headword=\"זְרַע I\">זרע</a>) unworthy offspring came from him; <span class=\"citation\">Gen. R. s. 68</span>; a. fr.—Pl. <span dir=\"rtl\">פְּסוֹלוֹת</span>. <span class=\"citation\">Num. R. s. 7</span>, beg., v. <a href=\"#\" data-headword=\"סָנַן\">סָנַן</a>.</div>","alt":[]},"23008":{"h":"פִּסּוּק","r":"Q01248","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיסּוּק\">פִּיסּוּק</a></div>","alt":[]},"23009":{"h":"פָּסוּק","r":"Q01249","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>) [<i>division, interval</i>,] <i>Biblical verse</i>. <span class=\"citation\">Yeb. 16ᵇ</span> <span dir=\"rtl\">פ׳ זה שר וכ׳</span> this verse (<span class=\"citation\">Ps. XXXVII, 25</span>) has been said by the archangel of the world. <span class=\"citation\">Snh. 99ᵃ</span> <span dir=\"rtl\">אפי׳ אמר … חוץ מפ׳ זה</span> even if one says, the whole Torah is from heaven, except this one verse; a. v. fr.—Pl. <span dir=\"rtl\">פְּסוּקִים</span>, <span dir=\"rtl\">פְּסוּקִין</span>. <span class=\"citation\">Taan. 27ᵇ</span> <span dir=\"rtl\">הקורא בתורה … משלשה פ׳</span> he who reads from the Law, must read no less than three verses. <span class=\"citation\">Meg. 22ᵃ</span> <span dir=\"rtl\">אין מתחילין בפרשה … פ׳</span> in reading from a section of the Torah you must not begin with less than three verses, i.e. you must begin with at least the fourth verse from the beginning of the section. <span class=\"citation\">Kidd. 30ᵃ</span> <span dir=\"rtl\">חמשת … פ׳ הוו פְסוּקֵי ספר תורה וכ׳</span> the number of verses of the Book of the Law (Pentateuch) is 5888; <span class=\"citation\">ib.</span> <span dir=\"rtl\"><span dir=\"rtl\">והתגלח</span> (<span dir=\"rtl\">חציין</span>) <span dir=\"rtl\">של פ׳</span></span> the verse beginning with <i>v’hithgallaḥ</i> (<span class=\"citation\">Lev. XIII, 33</span>) marks the middle of the verses of the Pentateuch; <span class=\"citation\">Yalk. Deut. 855</span> (needs emend.). <span class=\"citation\">Lev. R. s. 6</span> בארי לא נתנבא אלא שני פ׳ וכ׳ Beeri prophesied no more than two verses, … and they were attached to the book of Isaiah; a. v. fr.—[<span class=\"citation\">Sifré Num. 131</span> <span dir=\"rtl\">מתחת פסוקין</span>, v. <a href=\"#\" data-headword=\"פְּסִיקְיָא\">פְּסִיקְיָא</a>.]</div>","alt":[]},"23010":{"h":"פְּסוּקָא","r":"Q01250","html":"<div class=\"sense\"> <span class=\"citation\">Taan. 27ᵇ</span> <span dir=\"rtl\">כל פ׳ דלא פסקיה וכ׳</span> you must not divide a verse which Moses has not divided, i.e. in reading you must not stop in the middle of a verse; <span class=\"citation\">Meg. 22ᵃ</span>. <span class=\"citation\">Ib. 25ᵃ</span> <span dir=\"rtl\">דאמר פ׳ פ׳ וכ׳</span> (Ms. M. <a href=\"#\" data-headword=\"פ׳\">פ׳</a> only) when he recites each verse (of the Sh’mʿa) and repeats it; <span class=\"citation\">Ber. 33ᵇ</span> <span dir=\"rtl\">פְּסוּקָה פסוקה</span>. <span class=\"citation\">Ḥag. 15ᵃ</span> sq. <span dir=\"rtl\">אמר ליה פסוק לי פְּסוּקָךְ</span> he said to a child, tell me thy verse; a. fr.—Pl. <span dir=\"rtl\">פְּסוּקִין</span>, <span dir=\"rtl\">פְּסוּקַיָּא</span>, <span dir=\"rtl\">פְּסוּקֵי</span>. <span class=\"citation\">Y. M. Kat. III, 83ᵇ</span> bot. (expl. <span dir=\"rtl\">דלתות</span>, <span class=\"citation\">Jer. XXXVI, 23</span>) <span dir=\"rtl\">תלת ארבע פ׳</span> (ed. Krot. <a href=\"#\" data-headword=\"פְּסִיקָה\">פְּסִיקָן</a>) three or four verses. <span class=\"citation\">Kidd. 30ᵃ</span> <span dir=\"rtl\">פ׳ מיהא ליתו וכ׳</span> let us bring up the Torah and count the verses; <span dir=\"rtl\">בפ׳ נמי לא בקיאינן</span> we (Babylonians) know not even the division of verses. Ib. <span dir=\"rtl\">במערבא פסקי ליה … תלתא פ׳</span> in Palestine they divided this verse (<span class=\"citation\">Ex. XIX, 9</span>) into three verses; a. fr.</div>","alt":[]},"23011":{"h":"פְּסוּקָה","r":"Q01251","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"פְּסוּקָא\">preced.</a></div>","alt":[]},"23012":{"h":"פְּסוּקָה ²","r":"Q01252","html":"<div class=\"sense\"> f., constr. <a href=\"#\" data-headword=\"פְּסוּקָא\">פְּסוּקַת</a>, v. <a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a></div>","alt":[]},"23013":{"h":"פָּסַח","r":"Q01253","html":"<div class=\"sense\"> (b. h.) <i>to leap over; to spare</i>. <span class=\"citation\">Ex. R. s. 15</span> שאני פוֹסֵחַ עליכם ומגין וכ׳ I (the Lord) will pass over and protect you. <span class=\"citation\">Pes. X, 5</span> <span dir=\"rtl\">פֶּסַח על שום שפ׳ המקום וכ׳</span></div><div class=\"sense\"><b>Nif. נִפְסַח</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"פִּסֵּחַ\">פִּסֵּחַ</a>) <i>to become lame</i>. Y. Ber. I, 3ᶜ bot. <span dir=\"rtl\">ונ׳ ונתרפא</span> and became lame, but was cured; <span class=\"citation\">Gen. R. s. 39</span>; a. e.</div></div>","alt":[]},"23014":{"h":"פסח","r":"Q01254","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Is. XXXIII, 12</span> <span dir=\"rtl\">מפסחין</span>, v. <a href=\"#\" data-headword=\"*פְּסַךְ\">פְּסַךְ</a></div>","alt":[]},"23015":{"h":"פִּסֵּחַ","r":"Q01255","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"פסח\">preced. art.</a>) <i>limping, lame</i>. Sifra Emor ch. II, Par. 3 פ׳ בין חגר וכ׳ ‘lame’ (<span class=\"citation\">Lev. XXI, 18</span>), whether lame on both feet or on one. <span class=\"citation\">Sifré Deut. 126</span>; a. e.—Pl. <span dir=\"rtl\">פִּסְּחִים</span>, <a href=\"#\" data-headword=\"פְּגִימִין\">פִּי׳</a>. <span class=\"citation\">Pirké d’R. El. ch. XXXVI</span> (ref. to <span class=\"citation\">II Sam. V, 6</span>) <span dir=\"rtl\">העורים והפ׳ אלו הצלמים</span> ‘the blind and the lame’ means the idols; <span class=\"citation\">Yalk. Gen. 82</span> (with ref. to <span class=\"citation\">Ps. CXV, 5-7</span>).</div>","alt":["פִּי׳"]},"23016":{"h":"פֶּסַח","r":"Q01256","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"פִּסֵּחַ\">preced.</a> wds.) <i>Passover festival</i>; (sub. <span dir=\"rtl\">זבח</span>) <i>Passover sacrifice, Passover meal</i>. <span class=\"citation\">Pes. V, 1</span> (<span class=\"citation\">58ᵃ</span>) <span dir=\"rtl\">חל ערב פ׳ וכ׳</span> (Mish. ed. <span dir=\"rtl\">ערבי פסחים</span>; Y. ed. <span dir=\"rtl\">ערב פסחים</span>) if the eve of Passover occurred on a Friday. Ib. 2 <span dir=\"rtl\">הפ׳ ששחטו וכ׳</span> if they slaughtered a Passover lamb not as such. Ib. IX, 9 <span dir=\"rtl\">חבורה שאבדה פִסְחָהּ</span> a party that lost its dedicated Passover lamb. Ib. 5, a. fr. <span dir=\"rtl\">פ׳ מצרים</span>, <span dir=\"rtl\">פ׳ דורות</span>, v. <a href=\"#\" data-headword=\"דּוֹר\">דּוֹר</a>. Ib. 3, a. fr. <span dir=\"rtl\">פ׳ ראשון</span> the first Passover, i.e. that celebrated on the fifteenth of Nisan; <span dir=\"rtl\">פ׳ שני</span> the second (vicarious) Passover, on the eve of the fifteenth of Iyar (<span class=\"citation\">Num. IX, 10</span> sq.); a. v. fr.—Pl. <span dir=\"rtl\">פְּסָחִים</span>. Ib. 10 <span dir=\"rtl\">שתי … שנתערבו פִּסְחֵיהֶן</span> two parties whose Passover sacrifices were mixed up. Ib. X, 6 <span dir=\"rtl\">ונאכל שם … ומן הפ׳ וכ׳</span> that there we may partake of the offerings and the Passover sacrifices &amp;c.; a. fr.—<span dir=\"rtl\"><span dir=\"rtl\">ערבי</span> (<span dir=\"rtl\">ערב</span>) <a href=\"#\" data-headword=\"פ׳\">פ׳</a></span>, v. supra. Ib. 1; a. fr.—<i>P’saḥim</i>, name of a treatise, of the Order of Moëd, of the Mishnah, Tosefta, Talmud Babli and Y’rushalmi.</div>","alt":[]},"23017":{"h":"פִּסְחָא","r":"Q01257","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Ex. XII, 11</span>. <span class=\"citation\">Targ. II Chr. XXX, 18</span>; a. fr.—<span class=\"citation\">Y. Sabb. VIII, beg. 11ᵃ</span> <span dir=\"rtl\">שתי ארבעתי כסוי דלילי פ׳</span> drank the four cups of wine customary at the celebration of the Passover night. <span class=\"citation\">Ḥull. 129ᵇ</span> <span dir=\"rtl\">פ׳ זעירא</span> the minor Passover (= <span dir=\"rtl\">פסח שני</span>, v. <a href=\"#\" data-headword=\"פֶּסַח\">preced.</a>), the fifteenth of Iyar; <span dir=\"rtl\">פ׳ רבה</span> the great Passover, the fifteenth of Nisan. <span class=\"citation\">Pes. 69ᵇ</span> <span dir=\"rtl\">קום מהול ועביד פ׳</span> go and get circumcised, and partake of the Passover lamb; a. fr.—Pl. <span dir=\"rtl\">פִּסְחַיָּא</span>, <a href=\"#\" data-headword=\"פְּגִימִין\">פִּי׳</a>. <span class=\"citation\">Targ. I Sam. XV, 4</span> <span dir=\"rtl\">באמרי פ׳</span> by Passover lambs (h. text <span dir=\"rtl\">בטלאים</span>).</div>","alt":["פִּי׳"]},"23018":{"h":"פסטולים","r":"Q01258","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּסְטִילּוֹס\">פִּסְטִילּוֹס</a></div>","alt":[]},"23019":{"h":"פַּסְטוֹמוֹס","r":"Q01259","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַפֹּוסְטוֹמוֹס\">אַפּוֹסְטוֹמוֹס</a></div>","alt":[]},"23020":{"h":"פָּסָּטוֹן","r":"Q01260","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (fossatum, φοσσᾶτον) <i>ditch</i>. <span class=\"citation\">Gen. R. s. 46</span>; <span class=\"citation\">Yalk. ib. 82</span> [read with Ar.) <span dir=\"rtl\">עשו לו סיעה פ׳</span> a band made a ditch for him (as a trap).—Pl. <a href=\"#\" data-headword=\"פִּסְטִין\">פָּסָּטִין</a>. <span class=\"citation\">Yalk. Kings 230</span>, quot. fr. Tanḥ. Thazr. 9 <span dir=\"rtl\">שעשו פטשין … יפלו לתוך הפטשין</span> (corr. acc.) they dug ditches, saying, when the Israelites come to make war, they will fall into the ditches (Tanḥ. l. c. <a href=\"#\" data-headword=\"בּוֹרוּת\">בורות</a>, Var. <span dir=\"rtl\">פטשין</span>; ed. Bub. 12 <span dir=\"rtl\">פיטסים</span>, Mss. <span dir=\"rtl\">פוטיסין</span>, <span dir=\"rtl\">פוטסין</span>, read <span dir=\"rtl\">פוֹסָּטִין</span>).—Cmp. <a href=\"#\" data-headword=\"פּוֹסָא\">פּוֹסָא</a>.</div>","alt":[]},"23021":{"h":"פסטטא","r":"Q01261","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פסטמא\">פסטמא</a></div>","alt":[]},"23022":{"h":"פַּסְטִי","r":"Q01262","html":"<div class=\"sense\">(?) pr. n. m., v. <a href=\"#\" data-headword=\"*פַּנְטִי\">פַּנְטִי</a></div>","alt":[]},"23023":{"h":"פִּסְטִילּוֹס","r":"Q01263","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (pistillus) <i>pestle, pounder</i>. <span class=\"citation\">Yalk. Sam. 102</span> (ref. to <span dir=\"rtl\">הדקו</span> <span class=\"citation\">Dan. VI, 25</span>) <span dir=\"rtl\">כהדין פ׳</span> as with a pounder; Midr. Sam. ch. XI <span dir=\"rtl\">כאילין פסטילם</span> (corr. acc., or <span dir=\"rtl\">פִּסְטִילִּין</span>, pl.); Yalk. Dan. 1064 <a href=\"#\" data-headword=\"פסטולים\">פסטולים</a> (corr. acc.).</div>","alt":[]},"23024":{"h":"פִּסְטִין","r":"Q01264","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיסְטִין\">פִּיסְטִין</a></div>","alt":["פִּסְטִיס"]},"23025":{"h":"פסטירין","r":"Q01265","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסְטוֹר\">מִסְטוֹר</a></div>","alt":[]},"23026":{"h":"פַּסְטְלִין","r":"Q01266","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (adapt. of pastilli, as if from <span dir=\"rtl\">פסל</span> or <span dir=\"rtl\">פצל</span>) <i>lozenges, sugar pills</i>. <span class=\"citation\">Yalk. Cant. 981</span>; <span class=\"citation\">Ex. R. s. 41</span> <a href=\"#\" data-headword=\"פִּיצְטְלִין\">פִּיצְטְלִין</a>; cmp. <a href=\"#\" data-headword=\"אִיפַּסְטְלִין\">אִיפִּסְטְלִין</a>.</div>","alt":[]},"23027":{"h":"פסטמא","r":"Q01267","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 9</span>, some ed. <a href=\"#\" data-headword=\"פסטטא\">פסטטא</a>; <span class=\"citation\">Yalk. ib. 493</span> <span dir=\"rtl\">פשטמא</span>, a corrupt., read <a href=\"#\" data-headword=\"פְּרַגְמָטָא\">פְּרַגְמָטָא</a>.</div>","alt":[]},"23028":{"h":"פִּסְטְקָא","r":"Q01268","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיסְתְּקָא\">פִּיסְתְּקָא</a>, <a href=\"#\" data-headword=\"פִּיסְטְקִין\"><a href=\"#\" data-headword=\"פִּיסְטְקִין\">פִּיסְטְקִין</a>.</a></div>","alt":["פִּסְטְקִין"]},"23029":{"h":"פסי","r":"Q01269","html":"<div class=\"sense\"><i>to spread, be extended</i>. <span class=\"citation\">Y. Yoma III, beg. 40ᵇ</span> <span dir=\"rtl\">מאור החמה פּוֹסֶה וכ׳</span> the light of the sun (dawn) spreads over the whole eastern horizon, opp. <span dir=\"rtl\">מתמר ועולה</span>. Ib. 41ᵃ bot. <span dir=\"rtl\">של בית היתה מתמרת … ופוֹסָה ויורדת וכ׳ …</span> the frankincense of Beth Abtinas rose straight in a colunn and then spread and came down &amp;c.; <span class=\"citation\">Y. Shek. V, 49ᵃ</span> top; <span class=\"citation\">Cant. R. to I, 14</span>; <span class=\"citation\">III, 6</span>. <span class=\"citation\">Ib. to IV, 14</span> (ref. to <span dir=\"rtl\">ואהלות</span> ib.) [read:] <span dir=\"rtl\">(<a href=\"#\" data-headword=\"עֵץ\">עץ</a>) <span dir=\"rtl\">שהוא פוסה כאהל</span></span> a tree which spreads like a tent. <span class=\"citation\">Gen. R. s. 15</span> (ref. to <span dir=\"rtl\">עץ החיים</span>, <span class=\"citation\">Gen. II, 9</span>) <span dir=\"rtl\">עץ שהוא פוסה על פני וכ׳</span> a tree which spread over all living things. <span class=\"citation\">Neg. IV, 8</span>, a. fr. <span dir=\"rtl\">ופָשְׂתָה וכ׳</span> and the spot spread &amp;c.; <span class=\"citation\">Y. M. Kat. I, 80ᶜ</span> bot. <span dir=\"rtl\">ופָסְתָה</span>; a. fr.</div>","alt":["פָּסָה","פָּשָׂה"]},"23030":{"h":"פְּסֵי","r":"Q01270","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"פסי\">same</a>; denom. <a href=\"#\" data-headword=\"פִּסְיוֹנָא\">פִּסְיוֹנָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>to split, break; to desecrate</i>, v. <a href=\"#\" data-headword=\"פִּיס\">פִּיס</a> ch.</div>","alt":["פְּסָא I"]},"23031":{"h":"פְּסֵי ²","r":"Q01271","html":"<div class=\"sense\"> (= <span dir=\"rtl\">פסע</span>, <a href=\"#\" data-headword=\"פסח\">פסח</a>) <i>to step</i>. <span class=\"citation\">B. Mets. 86ᵇ</span> <span dir=\"rtl\">דלא מציא פַסְיָא קניא</span> (Ms. H. <span dir=\"rtl\">יכלה למיפסע</span>, v. Rabb. D. S. a. l. note 60) which cannot step over a reed (from fatness).—[<span dir=\"rtl\">פסי איית</span>, v. next w.]</div>","alt":["פְּסָא II"]},"23032":{"h":"פְּסִיָּאִית","r":"Q01272","html":"<div class=\"sense\"> adv. (פְּסֵי I, cmp. <a href=\"#\" data-headword=\"פִּיס\">פִּיס</a> <i>Pa.</i>) <i>in a persuasive manner</i>. <span class=\"citation\">Targ. Prov. XXV, 11</span> (some ed. <span dir=\"rtl\">פסי איית</span>, corr. acc.).</div>","alt":["פְּסִיאָיִית"]},"23033":{"h":"פִּסְיָאנִי","r":"Q01273","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּסְיוֹנִי\">פִּסְיוֹנִי</a></div>","alt":[]},"23034":{"h":"פְּסִיגָא","r":"Q01274","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַג\">פָּסַג</a>; v. <a href=\"#\" data-headword=\"פִּסְגָּה\">פִּסְגָּה</a>) <i>branch, sprig.</i> <span class=\"citation\">Ukts. I, 5</span> <span dir=\"rtl\">פ׳ של אשכול שריקנה</span> (Talm. ed. <a href=\"#\" data-headword=\"פְּסִיגָא\">פסיגא</a>) a sprig of a vine when stripped of its grapes.—Pl. <span dir=\"rtl\">פְּסִיגִין</span>. <span class=\"citation\">Tosef. Peah III, 11</span> (expl. <span dir=\"rtl\">כתף</span>) <span dir=\"rtl\">פ׳ המחוברות וכ׳</span> (ed. Zuck. <span dir=\"rtl\">בסיגין</span>, Var. <span dir=\"rtl\">סיגין</span>) sprigs which are joined to the trunk one above the other; Y. ib. VII, 20ᵃ bot. <span dir=\"rtl\">פ׳ זו על גבי זו</span>.</div>","alt":["פְּסִיגָה"]},"23035":{"h":"פָּסֵיד","r":"Q01275","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">פְּסֵידִין</span>, v. <a href=\"#\" data-headword=\"פָּסַד\">פָּסַד</a>.</div>","alt":[]},"23036":{"h":"פְּסִידָא","r":"Q01276","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּסַד\">פְּסַד</a>) <i>loss, disadvantage</i>. <span class=\"citation\">Targ. Y. Ex. XXII, 14</span>.—<span class=\"citation\">B. Mets. 3ᵃ</span> <span dir=\"rtl\">מאי פ׳ אית ליה דלודי</span> what loss can he suffer (through his false claim) that should induce him to confess the truth? (v. <a href=\"#\" data-headword=\"פָּסַד\">פָּסַד</a>). <span class=\"citation\">M. Kat. 2ᵃ</span>, sq. <span dir=\"rtl\">במקום פ׳</span> where there is a loss involved (by the delay); <span class=\"citation\">Keth. 60ᵃ</span>; a. fr.</div>","alt":["פְּסֵי׳","פְּסֵדָא"]},"23037":{"h":"פסידתו","r":"Q01277","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to IX, 1</span> ed. Bub.; Yalk. ib. 642, v. <a href=\"#\" data-headword=\"פַּחְדָּה\">פַּחְדָּה</a></div>","alt":[]},"23038":{"h":"פִּסָּיוֹן","r":"Q01278","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסָה\">פָּסָה</a>) <i>spreading, extension</i>, esp. <i>spreading of a leprous spot</i> (<span class=\"citation\">Lev. XIII, 7</span>, a. e.). <span class=\"citation\">Neg. I, 3</span>; <span class=\"citation\">5</span>; <span class=\"citation\">6</span> (<span dir=\"rtl\">פס׳</span> a. <span dir=\"rtl\">פש׳</span> interchanging). <span class=\"citation\">Ib. III, 4</span>; a. fr.</div>","alt":["פִּשָּׂ׳","פִּי׳"]},"23039":{"h":"פִּסְיוֹן","r":"Q01279","html":"<div class=\"sense\"><i>pheasant</i>, v. <a href=\"#\" data-headword=\"פִּסְיוֹנִי\">פִּסְיוֹנִי</a>.</div>","alt":["פִּסְיוֹנָא I"]},"23040":{"h":"פִּסְיוֹנָא","r":"Q01280","html":"<div class=\"sense\"> m. = h. <a href=\"#\" data-headword=\"פִּסָּיוֹן\">פִּסָּיוֹן</a>. <span class=\"citation\">Targ. Y. Lev. XIII, 5</span>, sq.; a. fr.—Fem. form: <a href=\"#\" data-headword=\"פִּסְיָינְתָּא\">פִּסְיָינְתָּא</a>. <span class=\"citation\">Ib. 28</span> (ed. Vien. <a href=\"#\" data-headword=\"פִּסְיָינְתָּא\">פִּסְיָינָתָא</a>).</div>","alt":["פִּיסְ׳ II"]},"23041":{"h":"פִּסְיוֹנִי","r":"Q01281","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (φασιανός, sub. ὀῤνις) [<i>bird from the river Phasis in Colchis</i>,] <i>pheasant</i> (Phasianus Colchicus). <span class=\"citation\">Num. R. s. 7</span> <span dir=\"rtl\">מי שהיה מתאוה תרנגול או פסיון וכ׳</span> whoever desired to eat chicken or pheasant, found the taste of it in the manna. <span class=\"citation\">Tosef. Kil. I, 8</span> <span dir=\"rtl\">תרנגול … ופ׳ וכ׳</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"פסאני\">פסאני</a>, <a href=\"#\" data-headword=\"פִּסְיָאנִי\">פַּסְיָאנִי</a>) chicken, peacock and pheasant, although resembling one another, are heterogeneous birds; Y. ib. I, 27ᵃ bot. <span dir=\"rtl\">הפוסיוני</span>; Y. B. Kam. V, end, 5ᵃ <span dir=\"rtl\">פי׳</span>; Bab. <span class=\"citation\">B. Kam. 55ᵃ</span> (Rashi: <i>partridge</i>). <span class=\"citation\">Yoma 75ᵇ</span> (as a species of quail, v. <a href=\"#\" data-headword=\"סְלָיו\">סְלָיו</a>). <span class=\"citation\">Kidd. 31ᵃ</span>. <span class=\"citation\">Midr. Till. to Ps. IV</span>; a. e.—Pl. <a href=\"#\" data-headword=\"פִּסְיוֹנִי\">פִּסְיוֹנִים</a>, <a href=\"#\" data-headword=\"פִּסְיוֹנִי\">פִּסְיוֹנִין</a>, <a href=\"#\" data-headword=\"פְּגִימִין\">פִּי׳</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פ׳ וראשי פטומות</span> pheasants and choice of fattened birds; a. e.</div>","alt":["פִּיסְ׳"]},"23042":{"h":"פִּסְיוֹנִי ²","r":"Q01282","html":"<div class=\"sense\"> <span class=\"citation\">Y. Ab. Zar. III, 42ᵈ</span> top, v. <a href=\"#\" data-headword=\"טַוָּוסָא\">טַוָּוסָא</a>.—Pl. <a href=\"#\" data-headword=\"פִּסְיוֹנִי\">פִּסְיוֹנִין</a>, <a href=\"#\" data-headword=\"פְּגִימִין\">פִּי׳</a>. <span class=\"citation\">Gen. R. s. 70</span> <span dir=\"rtl\">כמה טווסין … כמה פ׳ אית לי</span> (some ed. <a href=\"#\" data-headword=\"פּוּסְיָאנִי\">פּוּסְיָינֵי</a>) how many peacocks, how many pheasants have I!; <span class=\"citation\">Koh. R. to VII, 8</span>. <span class=\"citation\">Ib. to II, 8</span> <a href=\"#\" data-headword=\"פּוּסְיָאנִי\">פּוּסְיָאנִין</a>.</div>","alt":["פִּי׳"]},"23043":{"h":"פְּסִיחָה","r":"Q01283","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַח\">פָּסַח</a>) <i>stepping over, use of the root</i> <a href=\"#\" data-headword=\"פסח\">פסח</a>. Mekh. Bo, s. 11; Yalk. ib. 200, v. <a href=\"#\" data-headword=\"חָסִית II\"><span dir=\"rtl\">חָסִית</span> II</a>.</div>","alt":[]},"23044":{"h":"פִּסְיָינְתָּא","r":"Q01284","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּסְיוֹן\"><span dir=\"rtl\">פִּסְיוֹנָא</span> II</a></div>","alt":[]},"23045":{"h":"פְּסֵיכְתֵּרָא","r":"Q01285","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסַכְתֵּרָא\">פְּסַכְתֵּרָא</a></div>","alt":[]},"23046":{"h":"פָּסִיל","r":"Q01286","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>hewn image.</i> <i>—</i> Pl. <span dir=\"rtl\">פְּסִילִים</span>. <span class=\"citation\">Y. Ber. IV, 8ᵃ</span> <span dir=\"rtl\">ויחללוה עובדי פ׳</span> and which idolaters have desecrated. <span class=\"citation\">Pirké d’R. El. ch. XXX</span> <span dir=\"rtl\">הפ׳ של בית וכ׳</span> the images of the house of Pharaoh her father; a. e.</div><div class=\"sense\"><b>—2)</b> <i>chisel</i>, v. <a href=\"#\" data-headword=\"פְּסִילָה\">פְּסִילָה</a>.—[<span class=\"citation\">Y. Ned. I, 37ᵃ</span> top; <span class=\"citation\">Y. Naz. I, beg. 51ᵃ</span> <span dir=\"rtl\">נזיר פסילים</span>, v. <a href=\"#\" data-headword=\"פְּסִילּוֹס\">פְּסִילּוֹס</a>.]</div>","alt":[]},"23047":{"h":"פְּסִילָא","r":"Q01287","html":"<div class=\"sense\">1) as <a href=\"#\" data-headword=\"פָּסִיל\">preced.</a> 1. ch. </div><div class=\"sense\"><b>1)</b>  as <a href=\"#\" data-headword=\"פָּסִיל\">preced.</a> 1.—Pl. <a href=\"#\" data-headword=\"פְּסִילְיָא\">פְּסִילַיָּא</a>. <span class=\"citation\">Targ. Ps. LXXVIII, 58</span>, v. <a href=\"#\" data-headword=\"פִּסְלָא\">פִּסְלָא</a>.—<span class=\"citation\">Gen. R. s. 38</span>, end <span dir=\"rtl\">ותבריהון לכלהון פ׳</span> (not <a href=\"#\" data-headword=\"פְּסִילָא\">פסילא</a>) and broke all the idols.</div><div class=\"sense\"><b>—2)</b>  = <a href=\"#\" data-headword=\"פְּסוּלָא I\"><span dir=\"rtl\">פְּסוּלָא</span> I</a>. <span class=\"citation\">Targ. Ps. XVIII, 27</span> (Ms. <a href=\"#\" data-headword=\"פְּסִילָא\">פְּסִילָן</a> f. pl.); <span class=\"citation\">Targ. II Sam. XXII, 27</span> <a href=\"#\" data-headword=\"פְּסוּלָא I\">פְּסוּלָא</a>.—Pl. as ab. <span class=\"citation\">Lam. R. to III, 45</span> <span dir=\"rtl\">מאסייא פ׳</span> (some ed. <span dir=\"rtl\">פְּסִילָאַיָּיא</span>), v. <a href=\"#\" data-headword=\"מְאִיס\">מְאִיס</a>.—[V. <a href=\"#\" data-headword=\"פְּסִילְיָא\">פְּסִילְיָא</a>.]</div>","alt":[]},"23048":{"h":"פְּסִילָה","r":"Q01288","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַל\">פָּסַל</a>) <i>chisel</i> or <i>gimlet</i>. <span class=\"citation\">Y. Kidd. I, 59ᵈ</span> (expl. <a href=\"#\" data-headword=\"מַרְצֵעַ\">מרצע</a>, <span class=\"citation\">Ex. XXI, 6</span>) <span dir=\"rtl\">זה הפ׳</span> (some ed. <a href=\"#\" data-headword=\"פָּסַל\">הפָּסִיל</a>), contrad. to <a href=\"#\" data-headword=\"מַקְדֵּחַ\">מקדח</a>.—[<span class=\"citation\">Koh. R. to IX, 11</span>; <span class=\"citation\">X, 20</span> <span dir=\"rtl\">פסילתן</span>, some ed., v. <a href=\"#\" data-headword=\"פְּסוֹלֶת\">פְּסוֹלֶת</a>.]</div>","alt":[]},"23049":{"h":"פְּסִילּוֹס","r":"Q01289","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ψελλός) <i>one unable to pronounce certain letters, stammerer</i>. <span class=\"citation\">Lev. R. s. 10</span>, beg. <span dir=\"rtl\">והיו קורין אותו פ׳</span> and they called him (Amos) the stammerer; <span class=\"citation\">Yalk. Is. 307</span>, v. <a href=\"#\" data-headword=\"עָמַס\">עָמַס</a>. Pesik. Naḥămu, p. 125ᵇ his name was Amos <span dir=\"rtl\">שהיה פ׳ בלשונו</span> (not <span dir=\"rtl\">שהיו</span>) because he hesitated in his speech.—Pl. <span dir=\"rtl\">פְּסִילִּים</span>. <span class=\"citation\">Y. Ned. I, 37ᵃ</span> top <span dir=\"rtl\">במקום שקוראין לנזיר נזיק … נזיר פ׳ וכ׳</span> in a place where people say <i>naziḳ</i> for <i>nazir</i> (owing to a dialectical peculiarity), I say so: shall a Nazarite among stammerers not be a Nazarite?; Y. Naz. I, beg. 51ᵃ</div>","alt":[]},"23050":{"h":"פְּסִילּוֹסָא","r":"Q01290","html":"<div class=\"sense\"> Pesik. Naḥămu, p. 125ᵇ; <span class=\"citation\">Yalk. Is. 307</span> <span dir=\"rtl\">הניח … על הדין פ׳ על הדין קטיע לישנא</span> did the Lord pass the whole world and let his inspiration rest on this stammerer, this tongueless man?; Koh. R. beg. <span dir=\"rtl\">על הדין קטיע לישנא פ׳</span>; <span class=\"citation\">Lev. R. s. 10</span>, beg. Ar. (missing in ed.).</div>","alt":[]},"23051":{"h":"פְּסִילוּתָא","r":"Q01291","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסִילְתָּא\">פְּסִילְתָּא</a></div>","alt":[]},"23052":{"h":"פְּסִילְיָא","r":"Q01292","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"פסיליה\">next art.</a>) an inferior kind of <i>beans</i> (cmp. <a href=\"#\" data-headword=\"*פַּיְישׂוֹנָא\">פַּיְישׂוֹנָא</a>). <span class=\"citation\">Ab. Zar. 38ᵇ</span> היא המטליא היא פ׳ וכ׳ Ar. (Ms. M. <a href=\"#\" data-headword=\"פסליא\">פסליא</a>; ed. <a href=\"#\" data-headword=\"פְּשִׂלְיָא\">פשליא</a>) the same law applies to gentile preparations of <i>hemṭalia, psilia</i> and <i>sh’ʿitha</i>, v. <a href=\"#\" data-headword=\"הֵמְטַלְיָא\">הֵמְטַלְיָא</a> a. <a href=\"#\" data-headword=\"שְׁעִיתָא\">שְׁעִיתָא</a>. <span class=\"citation\">Y. Bets. I, 60ᵈ</span> bot. <span dir=\"rtl\">תורמוסין ופ׳</span> lupines and <i>psilia</i> (inferior beans); <span class=\"citation\">Y. Sabb. VII, 10ᵇ</span> <span dir=\"rtl\">ופְסִילְיָין</span> and the inferior beans among them (v. Bab. <span class=\"citation\">Sabb. 74ᵃ</span> bot.).</div>","alt":["פְּסִילְיָיה"]},"23053":{"h":"פסיליה","r":"Q01293","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Dem. I, 9</span> Var. ed. Zuck. (ed. Zuck. <a href=\"#\" data-headword=\"פסליא\">פסליא</a>, absent in oth. eds.), v. <a href=\"#\" data-headword=\"פַּסְלְקָאוֹת\">פַּסְלְקָאוֹת</a></div>","alt":[]},"23054":{"h":"פְּסִילְיָיה","r":"Q01294","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פסיליה\">preced. art.</a></div>","alt":[]},"23055":{"h":"פְּסִילְתָּא","r":"Q01295","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּסַל\">פְּסַל</a>) [<i>refuse</i>,] name of a <i>bean</i>(h. . <span class=\"citation\">Y. Kil. I, 27ᵃ</span> top Ar. s. v. <span dir=\"rtl\">פול</span> (R. S. to <span class=\"citation\">Kil. I, 1</span> <a href=\"#\" data-headword=\"פְּסִילוּתָא\">פְּסִילוּתָא</a>, <span dir=\"rtl\">פשיל׳</span>; ed. <span dir=\"rtl\">פתילת׳</span>, corr. acc.).</div>","alt":[]},"23056":{"h":"פַּסִּים","r":"Q01296","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּצִּים\">פַּצִּים</a></div>","alt":[]},"23057":{"h":"פַּסִּים ²","r":"Q01297","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּס\">פַּס</a>, a. <a href=\"#\" data-headword=\"פִּיסִּים\">פִּיסִּים</a>.—<span dir=\"rtl\">שטר פסים</span>, v. <a href=\"#\" data-headword=\"פָּסִיס\">פָּסִיס</a>.</div>","alt":["פִּסִּים","פִּסִּין"]},"23058":{"h":"פסינתטון","r":"Q01298","html":"<div class=\"sense\">, read:</div>","alt":["פסינתטיון"]},"23059":{"h":"פְּסִינְתְּיָטוֹן","r":"Q01299","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (absinthiatum, sub. vinum) <i>worm-wood-wine</i>. Tanḥ. Vayesheb 8, contrad. to <a href=\"#\" data-headword=\"קוֹנְדִּיטוֹן\">קונדיטון</a>. <span class=\"citation\">Y. Ab. Zar. II, 41ᵃ</span> top <span dir=\"rtl\">המר פ׳</span> ‘bitter wine’ is absinthiatum; Y. Ter. VIII, 45ᶜ <a href=\"#\" data-headword=\"פסתיגון\">פסתיגון</a> (corr. acc.).</div>","alt":[]},"23060":{"h":"פָּסִיס","r":"Q01300","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פִּיס\">פִּיס</a> or <a href=\"#\" data-headword=\"פָּסַס\">פָּסַס</a>) </div><div class=\"sense\"><b>1)</b> <i>persuasion, good-will, accommodation</i>; <span dir=\"rtl\">שטר פ׳</span> (not <span dir=\"rtl\">פסים</span>) <i>a deed of sale for accommodation, a feigned transfer</i> (a Hebrew adaptation of πίστις), v. <a href=\"#\" data-headword=\"פִּיסְטִין\">פִּיסְטִיס</a>.</div><div class=\"sense\"><b>—2)</b> <i>peg.</i> Pl. <a href=\"#\" data-headword=\"פְּסִיסִית\">פְּסִיסִין</a>. <span class=\"citation\">B. Bath. 2ᵇ</span> Ms. M., v. <a href=\"#\" data-headword=\"מְסִיפָס\">מְסִיפָס</a>; cmp. <a href=\"#\" data-headword=\"פְּסִיסִית\">פְּסִיסִית</a>.</div>","alt":[]},"23061":{"h":"פְּסִיסָא","r":"Q01301","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>P’sisa</i>. <span class=\"citation\">Snh. 91ᵃ</span>, v. <a href=\"#\" data-headword=\"גְּבִיעָא\">גְּבִיעָא</a>.</div>","alt":[]},"23062":{"h":"פְּסִיסִית","r":"Q01302","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַס\">פָּסַס</a>, cmp. <a href=\"#\" data-headword=\"פַּס\">פַּס</a> II a. <a href=\"#\" data-headword=\"פִּסְפֵּס I\"><span dir=\"rtl\">פִּסְפֵּס</span> I</a>) <i>a partition between courts marked off by pegs.</i> <i>—Ps.</i> <span dir=\"rtl\">פְּסִיסִיּוֹת</span>. <span class=\"citation\">Y. Erub. IX, beg. 25ᶜ</span> <span dir=\"rtl\">הרי שהיתה החצר חלוקה בפ׳</span> if the court (common to two parties) is marked off by pegs.</div>","alt":[]},"23063":{"h":"פְּסִיסְפָּס","r":"Q01303","html":"<div class=\"sense\"> m. <a href=\"#\" data-headword=\"פְּסִיסִית\">same</a>. <span class=\"citation\">Y. Ned. V, beg. 39ᵃ</span> [read:] <span dir=\"rtl\">אם היתה החצר חלוקה בפ׳</span> (<span class=\"citation\">Ab. Zar. 70ᵇ</span> <span dir=\"rtl\">במְסִיפָס</span>), v. <a href=\"#\" data-headword=\"פְּסִיסִית\">preced.</a></div>","alt":[]},"23064":{"h":"צִבָּאתָא","r":"R00022","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צִיבְּתָא\">צִיבְּתָא</a></div>","alt":[]},"23065":{"h":"צָבָה","r":"R00023","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צבי\">צבי</a></div>","alt":[]},"23066":{"h":"צְבוּ","r":"R00024","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צְבֵי\">צְבֵי</a>) <i>will, desire; willingness</i>. <span class=\"citation\">Targ. Y. Lev. VIII, 15</span> (ed. Vien. <a href=\"#\" data-headword=\"צְבוּ\">צְבוֹ</a>). <span class=\"citation\">Targ. Y. Gen. XXIV, 5</span>. <span class=\"citation\">Targ. Job XXXI, 16</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"צַבְאוּת\">צַבְאוּת</a>); a. e.—<span class=\"citation\">Yoma 86ᵇ</span> <span dir=\"rtl\">בצ׳ נפשיה לקטלא נפיק וצ׳ ביתיה וכ׳</span> of his own free will he (I, the judge) goes to meet death (divine punishment for wrong judgment), and the desire of his household he does not do (he must neglect his own affairs), and empty-handed he comes to his home again; <span class=\"citation\">Snh. 7ᵇ</span> <span dir=\"rtl\">ברעות נפשיה … וצבי ביתיה וכ׳</span>.</div>","alt":["צְבוּתָא"]},"23067":{"h":"צָבוּעַ","r":"R00025","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צָבַע I\">צָבַע</a>) </div><div class=\"sense\"><b>1)</b>  Part. pass. of <a href=\"#\" data-headword=\"צָבַע I\">צָבע</a>, q. v.</div><div class=\"sense\"><b>—2)</b>  [<i>the checkered</i>,] <i>tsabuʿa, leopard</i>, or <i>the striped hyœna</i>(?), v. <a href=\"#\" data-headword=\"אָפָא\">אָפָא</a>. <span class=\"citation\">B. Kam. 16ᵃ</span> צ׳ זכר לאחר … נעשה נקבה וכ׳ Ms. M. (v. Rabb. D. S. a. l. note) the male <i>tsabuʿa</i> after seven years is changed into a female, the female … into a bat; <span class=\"citation\">Y. Sabb. I, 3ᵇ</span> bot. <span class=\"citation\">Gen. R. s. 7</span>, end <span dir=\"rtl\">הצ׳ הזה מטפה של וכ׳</span> the <i>tsabuʿa</i> is formed from a white drop, and has 365 colors. <span class=\"citation\">Tosef. B. Kam. I, 4</span>; B. Kam. l. c.; Y. ib. I, end, 2ᶜ. Ib. <span dir=\"rtl\">בצ׳ זכר יש לו שעה וכ׳</span> it refers to the male <i>ts.</i> which at certain times is as fierce as a lion; a. e.</div>","alt":[]},"23068":{"h":"צְבוֹעִים","r":"R00026","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> , <a href=\"#\" data-headword=\"צ׳\">צ׳</a> (<a href=\"#\" data-headword=\"הַר\">הַר</a>) <i>the mountain of Zeboim</i>. <span class=\"citation\">Ḥall. IV, 10</span> (Ms. M. <a href=\"#\" data-headword=\"צביעין\">צביעין</a>, without <a href=\"#\" data-headword=\"הַר\">הר</a>); <span class=\"citation\">Bicc. I, 3</span> (Ms. M. <a href=\"#\" data-headword=\"צְבוֹעִים\">צְבוֹעִין</a>); [prob. identical with <span dir=\"rtl\">צבעים</span>, near Ono, <span class=\"citation\">Neh. XI, 34</span>).</div>","alt":[]},"23069":{"h":"צִבּוּר","r":"R00027","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"צִיבּוּר\">צִיבּ׳</a>.</div>","alt":["צִבּוּרָא"]},"23070":{"h":"צְבוֹרֶת","r":"R00028","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צְבִירָה\">צְבִירָה</a></div>","alt":[]},"23071":{"h":"צְבוּתָא","r":"R00029","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צְבוּ\">צְבוּ</a></div>","alt":[]},"23072":{"h":"צִבְחַד","r":"R00030","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (prob. fr. a root <span dir=\"rtl\">צבח</span>, with format. <a href=\"#\" data-headword=\"ד\">ד</a> or <a href=\"#\" data-headword=\"ר\">ר</a>; cmp. <a href=\"#\" data-headword=\"צָבַט\">next w.</a>, a. <a href=\"#\" data-headword=\"צָבַע I\"><span dir=\"rtl\">צָבַע</span> I</a>) [<i>a grab</i>,] <i>a little, few</i>. <span class=\"citation\">Targ. II Chr. XXIV, 24</span> (h. text <span dir=\"rtl\">מצער</span>). <span class=\"citation\">Targ. Job XXXVI, 2</span> (h. text <a href=\"#\" data-headword=\"זְעֵיר I\">זעיר</a>). <span class=\"citation\">Targ. Is. V, 18</span>; a. fr.—<span class=\"citation\">Y. Ber. I, 3ᵇ</span> top. <span dir=\"rtl\">מן גו דאינון צ׳</span> because they (the verses) are few; <span class=\"citation\">Y. Sabb. I, 3ᵃ</span> bot. <span class=\"citation\">Y. Yoma VI, 43ᵈ</span> <span dir=\"rtl\">אורכין צ׳</span> endure a little while yet. <span class=\"citation\">Gen. R. s. 49</span>; <span class=\"citation\">Lev. R. s. 10</span>, v. <a href=\"#\" data-headword=\"וְתַר\">וְתר</a>; a. fr.— Pesik. B’shall., p. 93ᵃ <a href=\"#\" data-headword=\"צצחר\">צצחר</a> (corr. acc.).—[Editions vary between <a href=\"#\" data-headword=\"צִבְחַד\">צבחד</a> a. <a href=\"#\" data-headword=\"צִבְחַד\">צבחר</a>.]</div>","alt":["(צִבְחַר)","צִי׳"]},"23073":{"h":"צָבַט","r":"R00031","html":"<div class=\"sense\"> (b. h.) <i>to seize, grab; to handle</i>. <span class=\"citation\">Ḥag. 22ᵇ</span> (expl. <span dir=\"rtl\">בית הצביטה</span>, <span class=\"citation\">ib. III, 1</span>) <span dir=\"rtl\">מקום שצוֹבְטוֹ</span> any part of a vessel by which you seize it. Ib. (<span dir=\"rtl\">שותין</span>) <span dir=\"rtl\">מקום שנקיי הרעת צוֹבְטִין</span> Ms. M. (ed. <span dir=\"rtl\">צובעין</span>; Ar. s. v. <span dir=\"rtl\">בית הצביעה</span>: <span dir=\"rtl\">שותין</span>; v. Rabb. D. S. a. l. note; Y. ib. III, 78ᵈ <span dir=\"rtl\">שהנקיים תופסין בו</span>) that part of the vessel by which the cleanly seize it when drinking (under the rim); v. <a href=\"#\" data-headword=\"צָבַע I\"><span dir=\"rtl\">צָבע</span> I</a>.</div>","alt":[]},"23074":{"h":"צְבָטָה","r":"R00032","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צְבִיטָה\">צְבִיטָה</a></div>","alt":[]},"23075":{"h":"צבי","r":"R00033","html":"<div class=\"sense\"><i>to swell</i>. Y. B. Kam. VIII, beg. 6ᵇ <span dir=\"rtl\">אם כוייו … וצָבַת</span> if one burnt a person with a heated spit on the palm of his hand, and it swelled; <span class=\"citation\">ib.</span> <span dir=\"rtl\">על ראשו וצבת</span>, (read <span dir=\"rtl\">וצבה</span>) a. e.—[<span class=\"citation\">Ber. 6ᵇ</span> לִצְבּוֹת Ar., v. <a href=\"#\" data-headword=\"צָבַת\">צָבַת</a>.]</div><div class=\"sense\"><b>Nif. נִצְבָּה</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"צְבָטָה\">same</a>. Y. Sot. V, beg. 20ᵃ (line 20) <span dir=\"rtl\">מים מגולין שתה ונ׳</span> (ed. Krot. <span dir=\"rtl\">שתת ונצבית</span>, corr. acc.) he drank uncovered water (poisoned by a serpent) and his belly was swollen. <span class=\"citation\">Ib.</span> (line 25) <span dir=\"rtl\">שתת ונִצְבֵּית</span></div></div><div class=\"sense\"><b>Pi. צִבֵּא  צִבָּה</b> <div class=\"sense\"><b>1)</b> <i>to cause to swell</i>. <span class=\"citation\">Lev. R. s. 17</span>; <span class=\"citation\">Yalk. Ps. 808</span> [read:] <span dir=\"rtl\">ולא צִבִּיתִים</span>, v. <a href=\"#\" data-headword=\"עוֹנָה II\"><span dir=\"rtl\">עוֹנָה</span> II</a>.</div><div class=\"sense\"><b>—2)</b> <i>to cause the appearance of being swollen</i>. <span class=\"citation\">Tosef. Peah IV, 14</span> <span dir=\"rtl\">המְצַבֶּה את כריסו</span> he that feigns a swollen belly; Y. ib. VIII, 21ᵇ top <span dir=\"rtl\">המְצַבֵּא</span>; <span class=\"citation\">Keth. 68ᵃ</span> <span dir=\"rtl\">המצב׳ את בטנו</span>.</div></div>","alt":["צָבָה"]},"23076":{"h":"צְבֵי","r":"R00034","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">צבת</span>) [<i>to seize; to bend</i>; cmp. <a href=\"#\" data-headword=\"חָפַץ\">חָפַץ</a>,] with <a href=\"#\" data-headword=\"ב\">ב</a>, <i>to find pleasure in, to choose, desire</i>. <span class=\"citation\">Targ. Y. Gen. XXXIV, 19</span> (h. text <span dir=\"rtl\">חפץ</span>). <span class=\"citation\">Targ. Prov. III, 31</span> (h. text <span dir=\"rtl\">בחר</span>). <span class=\"citation\">Targ. O. Ex. II, 21</span> (h. text <a href=\"#\" data-headword=\"יָאַל\">יאל</a>). <span class=\"citation\">Targ. Y. Deut. XXIII, 6</span> (h. text <span dir=\"rtl\">אבה</span>); a. fr.—[<span class=\"citation\">Targ. Prov. II, 4</span> <span dir=\"rtl\">תצביה</span>, ed. Wil., v. <a href=\"#\" data-headword=\"בְּצָא\">בְּצָא</a>.]—Part. <span dir=\"rtl\">צָכֵי</span>; f. <span dir=\"rtl\">צַבְיָא</span>; pl. <span dir=\"rtl\">צָבִין</span>; <a href=\"#\" data-headword=\"צַלְיָין\">צַבְיָין</a>. <span class=\"citation\">Targ. Prov. XI, 20</span>. Targ. II Esth. I, 16. <span class=\"citation\">Targ. Prov. XXI, 25</span> (ed. Lag. <span dir=\"rtl\">עפיין</span>, v. <a href=\"#\" data-headword=\"עֲפֵי\">עֲפֵי</a>); a. e.—<span class=\"citation\">Tosef. Yeb. XIII, 1</span> <span dir=\"rtl\">לית היא צביא וכ׳</span> she refuses to be married to him. <span class=\"citation\">Snh. 65ᵇ</span> <span dir=\"rtl\">דמרי צ׳</span> the master has found pleasure (in that man); <span dir=\"rtl\">שבת נמי מרי צ׳</span> the Sabbath likewise (is distinguished, because) the Lord has chosen it. <span class=\"citation\">Y. Keth. VII, 31ᶜ</span> <span dir=\"rtl\">ולא תִצְבֵּי</span>, v. <a href=\"#\" data-headword=\"פּוּתְיָא\">פּוּתְיָא</a>; a. e.</div>","alt":["צְבָא"]},"23077":{"h":"צְבִי","r":"R00035","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>desirable thing, beauty</i>. Tanḥ. <span class=\"citation\">Mishp. 17</span> (ref. to <span class=\"citation\">Jer. III, 19</span>) <span dir=\"rtl\">נחלת צבי … ארץ שנתאוו וכ׳</span> ‘an inheritance of choice’ …, a land which the kings of the world coveted. <span class=\"citation\">Num. R. s. 23</span> (ref. to <span class=\"citation\">Ez. XX, 6</span>, a. Jer. l. c.) <span dir=\"rtl\">חביבה עלי ארץ וכ׳</span> the land of Israel is more precious to me than &amp;c.—Pl. <span dir=\"rtl\">צְבִיּוֹת</span>. <span class=\"citation\">Yalk. Cant. 988</span> <span dir=\"rtl\">צְבִיּוֹתֵיהֶן</span>, v. infra.</div><div class=\"sense\"><b>—2)</b> <i>deer, gazelle</i>. <span class=\"citation\">Keth. 112ᵃ</span> (ref. to Jer. l. c.) <span dir=\"rtl\">א&quot;י נמשלה לצ׳ מה צ׳ וכ׳</span> the land of Israel is compared to a deer, as the skin of a deer (when once taken off) cannot again cover its body, so cannot Palestine contain its fruits; <span class=\"citation\">Gitt. 57ᵃ</span>, v. <a href=\"#\" data-headword=\"חָזַק\">חָזַק</a>; Tanḥ. l. c.; a. e.—<span class=\"citation\">Tosef. Sabb. VII</span> (<span class=\"citation\">VIII), 13</span> <span dir=\"rtl\">פסק צ׳ את הדרך וכ׳</span> a deer cut the way off before me (a superstitious omen); <span class=\"citation\">Snh. 65ᵇ</span> <span dir=\"rtl\">צ׳ הפסיקו בדרך</span> a deer cut him (me) off &amp;c.—<span class=\"citation\">Y. Gitt. II, 44ᵇ</span> bot.; <span class=\"citation\">Tosef. ib. II, 4</span> <span dir=\"rtl\">כתבו על קרן של צ׳ וכ׳</span> if he wrote a letter of divorce on the horn of a deer, and cut it off and gave it to her. <span class=\"citation\">Keth. XIII, 2</span> <span dir=\"rtl\">הניח מעותיו על קרן הצ׳</span> he has put his money on a deer’s horn, i.e. he cannot reclaim the unauthorized expense; a. fr.—Pl. <span dir=\"rtl\">צְבָאִים</span>, <span dir=\"rtl\">צְבָאִין</span>, <span dir=\"rtl\">צְבָיִים</span>. <span class=\"citation\">Sabb. 128ᵃ</span>; <span class=\"citation\">Tosef. ib. XIV</span> (<span class=\"citation\">XV), 8</span>; Y. ib. XVIII, 16ᶜ, v. <a href=\"#\" data-headword=\"חֲצָב II\"><span dir=\"rtl\">חֲצָב</span> II</a>. <span class=\"citation\">Gen. R. s. 31</span>; a. fr.—Fem. <a href=\"#\" data-headword=\"צְבִיָּה\">צְבִיָּה</a>, <a href=\"#\" data-headword=\"צְבִיָּיה\">צְבִיָּיה</a>. <span class=\"citation\">Ḥull. 79ᵇ</span>, sq. <span class=\"citation\">Yalk. Cant. 988</span> <span dir=\"rtl\">למה … כצ׳ שרבתה צביותיהן וכ׳</span> why is Jochebed likened to a hind? Because she reared the beauties of Israel (Moses and Aaron); a. e.</div>","alt":[]},"23078":{"h":"צְבִי ²","r":"R00036","html":"<div class=\"sense\"><i>desire</i>, v. <a href=\"#\" data-headword=\"צְבוּ\">צְבוּ</a>.</div>","alt":[]},"23079":{"h":"צִבְיָאתָא","r":"R00037","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צִיבְתָא II\"><span dir=\"rtl\">צִבְתָא</span> II</a></div>","alt":[]},"23080":{"h":"צְבִיָּה","r":"R00038","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צְבִי\">צְבִי</a> h.</div>","alt":[]},"23081":{"h":"צִבְיוֹן","r":"R00039","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צְבִיָּה\">preced. art.</a>) <i>desire, pleasure</i>. <span class=\"citation\">Keth. 111ᵃ</span> (ref. to <a href=\"#\" data-headword=\"צבי\">צבי</a>, <span class=\"citation\">Ez. XXVI, 20</span>) <span dir=\"rtl\">ארץ שצִבְיוֹנִי בה מתיה חיים וכ׳</span> the dead of the land in which I have my desire, shall be revived &amp;c. (v. <a href=\"#\" data-headword=\"צְבִי\">צְבִי</a> 1). <span class=\"citation\">Gen. R. s. 10</span> (ref. to <a href=\"#\" data-headword=\"צִיבָּא\">צבא</a> <span class=\"citation\">Job VII, 1</span>) <span dir=\"rtl\">וכל צִבְיוֹנוֹ של וכ׳</span> and all the desire of man refers to what is earthly. <span class=\"citation\">Ex. R. s. 1</span> (play on <span dir=\"rtl\">הצבבה</span>, <span class=\"citation\">I Chr. IV, 8</span>) <span dir=\"rtl\">שעשה צביונו וכ׳</span> he did the will of the Lord; a. fr.—<span class=\"citation\">Ḥull. 60ᵃ</span> <span dir=\"rtl\">כל … בקומתם … ברעתם … בצִבְיוֹנָם נבראו</span> all the works (animals) of creation were created in their full-grown stature, with their consent, with their pleasure (in their mission, with ref. to <span dir=\"rtl\">צבאם</span>, <span class=\"citation\">Gen. II, 1</span>); [Rashi: according to the shape of their own choice]; <span class=\"citation\">R. Hash. 11ᵃ</span> (v. Ms. M., Rabb. D. S. a. l.).</div>","alt":[]},"23082":{"h":"צִבְיוֹנָא","r":"R00040","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Prov. X, 32</span>. <span class=\"citation\">Ib. XI, 1</span> (ed. Lag. <span dir=\"rtl\">צביי׳</span>). <span class=\"citation\">Ib. 27</span>. Targ. II Esth. III, 3; a. e.</div>","alt":["צִבְיָינָא","צִבְיָנָא","צִי׳"]},"23083":{"h":"צְבִיטָה","r":"R00041","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צָבַט\">צָבַט</a>) <i>seizing, handling</i>; <span dir=\"rtl\">בית הצ׳</span> that part of a vessel by which it is seized, <i>handle, neck, cavity</i> for the fingers, &amp;c. <span class=\"citation\">Ḥag. III, 1</span> (<span class=\"citation\">20ᵇ</span>) <span dir=\"rtl\">אחוריים ותוך ובית הצ׳</span> (Y. ed. <span dir=\"rtl\">ובית צביעה</span>) (in vessels used for T’rumah) the back (outside), the inside, and the handle are considered as independent of one another (one becoming unclean does not affect the others). Ib. 22ᵇ בית הצ׳ Ms. M. (ed. <span dir=\"rtl\">הצְבָטָה</span>), v. <a href=\"#\" data-headword=\"צָבַט\">צָבַט</a>. <span class=\"citation\">Kel. XXV, 7</span>, sq. R. S. (ed. <span dir=\"rtl\">צביע׳</span>). V. <a href=\"#\" data-headword=\"צְבִיעָה I\">צְבִיעָה</a>.</div>","alt":[]},"23084":{"h":"צְבִיָּיה","r":"R00042","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צְבִי\">צְבִי</a> h.</div>","alt":[]},"23085":{"h":"צִבְיָינָא","r":"R00043","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צִבְיוֹנָא\">צִבְיוֹנָא</a></div>","alt":["צִבְיָנָא"]},"23086":{"h":"צִבְיָיתָא","r":"R00044","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צִיבְּתָא\">צִיבְּתָא</a></div>","alt":[]},"23087":{"h":"צְבִיעָה I","r":"R00045","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (צָבַע I) <i>handling</i>; <span dir=\"rtl\">בית הצ׳</span> that part of a vessel by which it is handled, v. <a href=\"#\" data-headword=\"צְבִיטָה\">צְבִיטָה</a>. <span class=\"citation\">Kel. XXV, 7</span> <span dir=\"rtl\">כל הכלים … ובית הצ׳</span> all vessels have backs, insides and handling places (independent of one another, v. <a href=\"#\" data-headword=\"צְבִיטָה\">צְבִיטָה</a>); <span class=\"citation\">ib. 8</span> <span dir=\"rtl\">כיצד … אחזו בבית צְבִיעָתוֹ וכ׳</span> how is this? If one’s hands are clean, and the back of a cup is unclean, and he seizes it by its handling place. Ib. <span dir=\"rtl\">נטילתו באחת צביעתו באחת</span> that which is taken up with one hand (at one special place) has one handling place (for the purposes of levitical cleanness); <span dir=\"rtl\">מקום אחיזתו שם צביעתו</span> at whatever place a vessel is taken hold of, there is its handle. <span class=\"citation\">Y. Ḥag. III, 78ᵈ</span> bot.; a. fr.</div>","alt":[]},"23088":{"h":"צְבִיעָה II","r":"R00046","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (צָבַע II) <i>dyeing</i>. <span class=\"citation\">Men. 42ᵇ</span> <span dir=\"rtl\">בעינן צ׳ לשמה</span> the show-fringe must be dyed for that purpose (to be used for <i>tsitsith</i>). <span class=\"citation\">Y. Shebi. VII, beg. 37ᵇ</span>. <span class=\"citation\">Y. Sabb. VII, 10ᶜ</span> top <span dir=\"rtl\">מה צ׳ היתה במשכן</span> what dyeing was there at the preparation of the Tabernacle (to serve as a standard for forbidden Sabbath labors)?; a. e.</div>","alt":[]},"23089":{"h":"צביעין","r":"R00047","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צְבוֹעִים\">צְבוֹעִים</a></div>","alt":[]},"23090":{"h":"צְבֵיר","r":"R00048","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צְבַר\">צְבַר</a></div>","alt":[]},"23091":{"h":"צְבִירָה","r":"R00049","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צָבַר\">צָבַר</a>) <i>piling up, pile</i>. Ohol. XVII, 3 <span dir=\"rtl\">צְבִירַת העצמות</span> (Var. <a href=\"#\" data-headword=\"צְבוֹרֶת\">צְבוֹרֶת</a>), v. <a href=\"#\" data-headword=\"לָטוֹמְיָא\">לָטוֹמְיָא</a>.—[<span class=\"citation\">Tosef. Kel. B. Mets. V, 13</span> <a href=\"#\" data-headword=\"צְבִירָה\">צבירה</a>, <span dir=\"rtl\">צבירות</span>, v. <a href=\"#\" data-headword=\"צְפִירָה II\"><span dir=\"rtl\">צְפִירָה</span> II</a>.]</div>","alt":[]},"23092":{"h":"צְבִיתָה","r":"R00050","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"צְבָת\">צְבָת</a>) <i>handling tongs.</i> <i>—</i> Pl. <span dir=\"rtl\">צְבִיתוֹת</span>. <span class=\"citation\">Y. Erub. X, end, 26ᵈ</span>, v. <a href=\"#\" data-headword=\"צַבְתָּא\">צַבְתָּא</a>.</div>","alt":[]},"23093":{"h":"צִבְיְתָהָא","r":"R00051","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צַבְתָּא\">צַבְתָּא</a></div>","alt":[]},"23094":{"h":"צביתים","r":"R00052","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Ps. 808</span> <span dir=\"rtl\">אלו לצ׳</span>, v. <a href=\"#\" data-headword=\"צִיב\">צִיב</a></div>","alt":[]},"23095":{"h":"צָבַע I","r":"R00053","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"צָבַט\">צָבַט</a>) <i>to seize, handle</i>. <span class=\"citation\">Ḥag. 22ᵇ</span> <span dir=\"rtl\">שנקיי … צוֹבְעִין</span> ed., v. <a href=\"#\" data-headword=\"צָבַט\">צָבַט</a>.</div><div class=\"sense\"><b>Hif. הִצְבִּיעַ</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"אֶצְבַּע\">אֶצְבַּע</a>) <i>to raise one or more fingers</i> for the casting of lots. <span class=\"citation\">Yoma II, 1</span> <span dir=\"rtl\">הממונה … הַצְבִּיעוּ</span> the superintending priest said to them, raise your fingers; <span class=\"citation\">Tam. 28ᵃ</span>; Y. Yoma II, 39ᵈ top, expl. <span dir=\"rtl\">הוציאו אצבע</span>.</div></div>","alt":[]},"23096":{"h":"צְבַע","r":"R00054","html":"<div class=\"sense\">; <i>Pa.</i> <a href=\"#\" data-headword=\"צְבַע ²\">צַבַּע</a>, with <a href=\"#\" data-headword=\"פְּיָיסָא\">פייסא</a> (v. <a href=\"#\" data-headword=\"צָבַע I\">preced.</a><i>Hif.</i>) <i>to cast lots</i>. Targ. II Esth. III, 7; IX, 24.</div>","alt":[]},"23097":{"h":"צָבַע II","r":"R00055","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"טָבַע I\"><span dir=\"rtl\">טָבַע</span> I</a>) <i>to dip; to dye</i>. <span class=\"citation\">Orl. III, 1</span> <span dir=\"rtl\">בגד שצְבָעוֹ וכ׳</span> a garment which one dyed with shells of fruits forbidden as ‘<i>Orlah</i> (v. <a href=\"#\" data-headword=\"עָרְלָה\">עָרְלָה</a>). <span class=\"citation\">Sabb. VII, 2</span> <span dir=\"rtl\">והצוֹבְעוֹ</span> and he who dyes it (the wool). <span class=\"citation\">Ib. 75ᵃ</span>, sq., a. fr. <span dir=\"rtl\">(<span dir=\"rtl\">חייב</span>) <span dir=\"rtl\">משום צוֹבֵעַ</span></span> he is guilty because it is an act coming under the category of dyeing; a. fr.—[<span class=\"citation\">Y. Sabb. VI, 7ᵈ</span> <span dir=\"rtl\">צובעין תותבן</span>, read: <span dir=\"rtl\">צבעונין או זהובין</span>, v. <a href=\"#\" data-headword=\"צִבְעוֹן I\">צִבְעוֹן</a>.]—V. <a href=\"#\" data-headword=\"צוֹבַע\">צוֹבַע</a>.—Part. pass. <a href=\"#\" data-headword=\"צָבוּעַ\">צָבוּעַ</a>; f. <span dir=\"rtl\">צְבוּעָה</span>; pl. <a href=\"#\" data-headword=\"צְבוֹעִים\">צְבוּעִים</a>, <span dir=\"rtl\">צְבוּעִין</span>; <span dir=\"rtl\">צְבוּעוֹת</span>. <span class=\"citation\">Gen. R. s. 96</span>, v. <a href=\"#\" data-headword=\"*בּוּרדִּיקָא\">בּוּרְדִּיקָא</a>. <span class=\"citation\">Num. R. s. 2</span> <span dir=\"rtl\">מפה שלו צ׳ אדום</span> his flag was red-colored. <span class=\"citation\">Meg. IV, 7</span> <span dir=\"rtl\">מי שהיו ידיו צ׳ וכ׳</span> he whose hands are spotted from handling woad; a. fr.—<span class=\"citation\">Sot. 22ᵇ</span> <a href=\"#\" data-headword=\"צוֹפִים\">הצ׳</a> the painted (hypocrites), v. <a href=\"#\" data-headword=\"פָּרוּשׁ\">פָּרוּשׁ</a>.—V. <a href=\"#\" data-headword=\"צָבוּעַ\">צָבוּעַ</a>.</div>","alt":[]},"23098":{"h":"צְבַע ²","r":"R00056","html":"<div class=\"sense\">, <i>to dip; to dye</i>. <span class=\"citation\">Targ. Y. Ex. XII, 22</span> Ar. (ed. <a href=\"#\" data-headword=\"טְמַשׁ\">טמש</a>; h. text <span dir=\"rtl\">טבל</span>). <span class=\"citation\">Targ. Y. II, Lev. IV, 6</span> <span dir=\"rtl\">יִצְבּוֹעַ</span>.—Y. Sabb. II, 4ᵈ top, v. <a href=\"#\" data-headword=\"פְּתִילְתָּא\">פְּתִילְתָּא</a>.—<span class=\"citation\">Y. Taan. IV, end, 69ᶜ</span> <span dir=\"rtl\">הוה צ׳ פיסתיה וכ׳</span> dipped his bread in ashes. <span class=\"citation\">Koh. R. to VII, 11</span> <span dir=\"rtl\">הוה צ׳ חדא וכ׳</span> dipped one of his fingers in blood of a swine. <span class=\"citation\">Y. B. Kam. IX, 6ᵈ</span> bot. <span dir=\"rtl\">א&quot;ל צִיבְעֵיה סומק וצַבְעֵיה אוכם</span> if he told the dyer, dye it red, and he dyed it black; <span dir=\"rtl\">אילו צְבַעְתֵּיה סומק וכ׳</span> if thou hadst dyed it red, it would have been worth &amp;c. <span class=\"citation\">Men. 42ᵇ</span> <span dir=\"rtl\">הא … היכי צַבְעִיתוּ לה</span> how do you dye the purple-blue?; a. e.</div><div class=\"sense\"><b>Pa. צַבַּע</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"צָבַע II\">same</a>, <i>to dip, immerse</i>. <span class=\"citation\">Targ. O. Lev. XIII, 6</span> (Y. <span dir=\"rtl\">יִצְכַּע</span> <i>Pe.</i>; h. text <span dir=\"rtl\">כבס</span>). Ib. XIV, 9; a. fr.</div></div><div class=\"sense\"><b>Ithpa. אִצְטַבַּע</b> <div class=\"sense\"><i>to be dipped, immersed; to be soaked</i>. Ib. XIII, 58. <span class=\"citation\">Targ. Cant. V, 2</span>.</div></div>","alt":[]},"23099":{"h":"צֶבַע","r":"R00057","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"צְבַע ²\">preced.</a>) <i>dye, color; dyed material</i>. Sifra B’har, ch. I <span dir=\"rtl\">לצבוע בה צ׳</span> to use it for dyeing. <span class=\"citation\">Arakh. VI, 5</span> (<span class=\"citation\">24ᵃ</span>) <span dir=\"rtl\">צ׳ שצבעו לשמן</span> (not <span dir=\"rtl\">שצבען</span>) dyed cloth which he had dyed for them (his wife and children). <span class=\"citation\">Mikv. VII, 3</span> <span dir=\"rtl\">מי הצ׳</span> dye-water. <span class=\"citation\">Num. R. s. 2</span>; a. fr.—Pl. <span dir=\"rtl\">צְבָעִים</span>, <a href=\"#\" data-headword=\"צַבָּעַיָּא\">צְבָעִין</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">וצבע מפה שלו דומה לי&quot;ב צ׳</span> and the color of his (Benjamin’s) flag was like the twelve colors (combined); a. e.—V. <a href=\"#\" data-headword=\"צוֹבַע\">צוֹבַע</a>.</div>","alt":[]},"23100":{"h":"צֶבַע ²","r":"R00058","html":"<div class=\"sense\"> constr. <a href=\"#\" data-headword=\"צְבַע\">צְבַע</a>. <span class=\"citation\">Targ. Ex. XXV, 4</span> <span dir=\"rtl\">צְ׳ זהורי</span> (h. text <span dir=\"rtl\">תולעת שני</span>). <span class=\"citation\">Targ. Lev. XIV, 4</span>; a. fr.—<span class=\"citation\">Sabb. 75ᵃ</span> <span dir=\"rtl\">דליציל צִיבְעֵיה</span> that its color may be so much brighter. <span class=\"citation\">Y. Pes. III, beg. 29ᵈ</span> <span dir=\"rtl\">בגין דיקלוט צ׳</span> in order that it may take the dye; a. e.</div>","alt":["צִבְעָא","צִי׳ I"]},"23101":{"h":"צַבָּע","r":"R00059","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צֶבַע ²\">preced.</a>) <i>dyer</i>. <span class=\"citation\">Sabb. 11ᵇ</span>, v. <a href=\"#\" data-headword=\"דּוּגְמָא\">דּוּגְמָא</a>. <span class=\"citation\">B. Kam. IX, 4</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"צַבָּעַיָּא\">צַבָּעִים</a>, <a href=\"#\" data-headword=\"צַבָּעַיָּא\">צַבָּעִין</a>. <span class=\"citation\">Pes. III, 1</span>, v. <a href=\"#\" data-headword=\"זוֹמָא I\"><span dir=\"rtl\">זוֹמָא</span> I</a>. <span class=\"citation\">Tosef. Shebi. V, 8</span>. <span class=\"citation\">Y. Sabb. VII, 10ᶜ</span> top <span dir=\"rtl\">הצ׳ שבירושלים וכ׳</span> the dyers in Jerusalem considered wringing (the dyed clothes) a special art; <span class=\"citation\">Tosef. Sabb. IX</span> (<span class=\"citation\">X), 18</span>; a. fr.</div>","alt":[]},"23102":{"h":"צַבָּעָא","r":"R00060","html":"<div class=\"sense\"> <span class=\"citation\">Gitt. 52ᵇ</span> עמרם צ׳ Amram, the dyer.—Pl. <a href=\"#\" data-headword=\"צַבָּעַיָּא\">צַבָּעַיָּא</a>, <a href=\"#\" data-headword=\"צַבָּעַיָּא\">צַבָּעִין</a>, q. v.</div>","alt":[]},"23103":{"h":"צִבְעָא","r":"R00061","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צֶבַע\">צֶבַע</a> ch.</div>","alt":["צִי׳ I"]},"23104":{"h":"צִבְעָא ²","r":"R00062","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (צְבַע I) <i>finger, toe, fang</i>. <span class=\"citation\">Targ. Y. Lev. XI, 13</span> <span dir=\"rtl\">צ׳ יתירא</span> (v. <a href=\"#\" data-headword=\"אֶצְבַּע\">אֶצְבַּע</a>); <span class=\"citation\">Deut. XIV, 11</span>.—Pl. <span dir=\"rtl\">צִבְעָתָא</span>, <a href=\"#\" data-headword=\"צִבְחַד\">צִי׳</a>. <span class=\"citation\">Targ. Ps. CXLIV, 1</span> Ms. (ed. <span dir=\"rtl\">אצבעת׳</span>, <span dir=\"rtl\">אצבעות׳</span>). <span class=\"citation\">Targ. Prov. VII, 3</span> Ms. (ed. <span dir=\"rtl\">אצב׳</span>).</div>","alt":["צִי׳ II"]},"23105":{"h":"צִבְעוֹן I","r":"R00063","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Zibeon</i>, father of Anah. <span class=\"citation\">Pes. 54ᵃ</span>; <span class=\"citation\">Gen. R. s. 82</span>; a. e.</div>","alt":[]},"23106":{"h":"צִבְעוֹן II","r":"R00064","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (צָבַע II) <i>color, dyed stuff.</i> <i>—</i> Pl. <span dir=\"rtl\">צִבְעוֹנִים</span>, <span dir=\"rtl\">צִי׳ וצִבְעוֹנִין</span>. <span class=\"citation\">Pesik. R. s. 20</span> <span dir=\"rtl\">הראהו ארבע צ׳ וכ׳</span> he showed him the four colors in the Tabernacle (<span class=\"citation\">Ex. XXVI, 1</span>). <span class=\"citation\">Y. Keth. VII, 31ᶜ</span> <span dir=\"rtl\">נדרה … בגדי צ׳</span> if a woman vows … not to wear dyed (expensive) clothes; <span dir=\"rtl\">כלי פשתן … ככלי צ׳ הן</span> the fine linen garments from Beth Shean are like dyed clothes (included in the vow). <span class=\"citation\">Sabb. 57ᵇ</span> <span dir=\"rtl\">עניות עושין אותן של מיני צ׳ עשירות וכ׳</span> poor women make them (those garlands) of dyed wool, the rich of silver or gold; Y. ib. VI, 7ᵈ <span dir=\"rtl\">צובעין תותבן</span>, read: <span dir=\"rtl\">צבעונין או זהובין</span>.</div>","alt":["צִי׳"]},"23107":{"h":"צִבְעוֹנָא","r":"R00065","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">צִבְעוֹנִין</span>, <a href=\"#\" data-headword=\"צִבְחַד\">צִי׳</a>. <span class=\"citation\">Targ. Jud. V, 30</span> (h. text <span dir=\"rtl\">צְבָעִים</span>). <span class=\"citation\">Targ. II Sam. I, 24</span> (h. text <a href=\"#\" data-headword=\"שני\">שני</a>). <span class=\"citation\">Targ. Esth. VIII, 15</span>; a. fr.—<span class=\"citation\">Sabb. 65ᵃ</span> <span dir=\"rtl\">בנתיה … דצ׳ הוו</span> the cords which the daughters of Samuel’s father wore, were of fine colored material.</div>","alt":["צִי׳"]},"23108":{"h":"צַבָּעַיָּא","r":"R00066","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"צַבָּעָא\">צַבָּעָא</a>) <i>Magdala of the Dyers</i>, near Tiberias. <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> bot.; <span class=\"citation\">Lam. R. to II, 2</span>. <span class=\"citation\">Y. Pes. IV, 30ᵈ</span> top <span dir=\"rtl\">מגדל צַבָּעַיָּיה</span>; <span class=\"citation\">Cant. R. to I, 12</span> <span dir=\"rtl\">מגדלא דצבעין</span> (also <a href=\"#\" data-headword=\"מִגְדַּל\">מגדלא</a> only); <span class=\"citation\">Gen. R. s. 94</span>. <span class=\"citation\">Lev. R. s. 17</span>.</div>","alt":["צַבָּעַיָּיא","צַבָּעִין","מַגְדַּל צַ׳","מַגְדְּלָא דצַ׳"]},"23109":{"h":"צבצין","r":"R00067","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צֶבֶת\">צֶבֶת</a></div>","alt":[]},"23110":{"h":"צָבַר","r":"R00068","html":"<div class=\"sense\"> (b. h.) <i>to join; to pile up</i> (cmp. <a href=\"#\" data-headword=\"חָמַר I\"><span dir=\"rtl\">חָמַר</span> I</a>); <i>to collect</i>. <span class=\"citation\">Yoma V, 1</span> <span dir=\"rtl\">צ׳ את הקטורת וכ׳</span> he heaped the frankincense upon the coals. <span class=\"citation\">Tam. I, 4</span>. Y. B. Bath. III, beg. 13ᵈ <span dir=\"rtl\">כיון שצ׳ לתוכו וכ׳</span> as soon as he has put into it a pile of fruit, he has taken possession (of the building). <span class=\"citation\">Pirké d’R. El. ch. XI</span> צ׳ את עפרו וכ׳ God collected the dust out of which to create Adam (v. infra); a. fr.—Part. pass. <a href=\"#\" data-headword=\"צִבּוּר\">צָבוּר</a>; f. <span dir=\"rtl\">צְבוּרָה</span>; pl. <span dir=\"rtl\">צְבוּרִים</span>, <span dir=\"rtl\">צְבוּרִין</span>; <span dir=\"rtl\">צְבוּרוֹת</span>. <span class=\"citation\">Y. Taan. II, beg. 65ᵃ</span> <span dir=\"rtl\">רואין … כאילו צ׳ וכ׳</span> we look upon it as if the ashes of Isaac were heaped upon the altar. <span class=\"citation\">Sabb. 127ᵃ</span> <span dir=\"rtl\">תבואה צ׳</span> fruits piled for storage. <span class=\"citation\">B. Bath. 69ᵃ</span> <span dir=\"rtl\">אבנים צ׳ לגדר</span> stones piled up (but not yet arranged and assorted) to build a fence with, contrad. to <span dir=\"rtl\">סדורות</span> (cmp. <span class=\"citation\">Tosef. ib. III, 6</span>, quot. s. v. <a href=\"#\" data-headword=\"*סָוַר\">סָוַר</a>).</div><div class=\"sense\"><b>Nif. נִצְבָּר</b> <div class=\"sense\"><i>to be piled, stored</i>. Y. B. Bath. l. c. <span dir=\"rtl\">פירות ראויין לִיצָּבֵר</span> fruits fit for storage (not only temporarily deposited).</div></div><div class=\"sense\"><b>Hof. הוּצְבָּר</b> <div class=\"sense\"><i>to be brought together, collected</i>. <span class=\"citation\">Snh. 38ᵃ</span> <span dir=\"rtl\">אדם … ה׳ עפרו</span> the dust of which Adam was made, was collected from all parts of the world; <span class=\"citation\">ib.ᵇ</span>; <span class=\"citation\">Ab. d’R. N. ch. I</span>.</div></div>","alt":[]},"23111":{"h":"צְבַר","r":"R00069","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ruth II, 7</span>; <span class=\"citation\">8</span>; <span class=\"citation\">15</span>, sq. (h. text <span dir=\"rtl\">לקט</span>). <span class=\"citation\">Targ. Ez. IV, 2</span> (h. text <span dir=\"rtl\">שפך</span>); a. fr.</div>","alt":["צְבֵיר"]},"23112":{"h":"צֶבֶר","r":"R00070","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צְבַר\">preced.</a>) <i>heap, pile</i>. Ruth R. end, v. <a href=\"#\" data-headword=\"כָּבַר\">כָּבַר</a>. <span class=\"citation\">Y. Sabb. IV, 7ᵃ</span> top <span dir=\"rtl\">צ׳ של קורות</span>; Ohol. III, 7 Var., v. <a href=\"#\" data-headword=\"סַוָּאר\">סַוָּאר</a>.—Pl., v. <a href=\"#\" data-headword=\"צִיבּוּר\">צִיבּוּר</a></div>","alt":[]},"23113":{"h":"צָבַת","r":"R00071","html":"<div class=\"sense\"><i>to join; to attend</i>. <span class=\"citation\">Ber. 6ᵇ</span>; <span class=\"citation\">Sabb. 30ᵇ</span> כל העולם … אלא כל העולם … אלא לִצְבּוֹת לזה Ar. (ed. <span dir=\"rtl\">לִצְווֹת</span>) the entire world has been created for naught but to attend (be subservient) to him (the God-fearing man), [perh. fr. <a href=\"#\" data-headword=\"צָבָה\">צָבָה</a>, cmp. <a href=\"#\" data-headword=\"צָבָא\">צָבָא</a>].—<i>Part. pass.</i> <span dir=\"rtl\">צָבוּת</span>; pl. <span dir=\"rtl\">צְבוּתִים</span>, <span dir=\"rtl\">צְבוּתִין</span> <i>coupled</i>. <span class=\"citation\">Men. X, 9</span> (<span class=\"citation\">71ᵃ</span>), v. <a href=\"#\" data-headword=\"צֶבֶת\">צֶבֶת</a>. [<span class=\"citation\">Lev. R. s. 17</span> <span dir=\"rtl\">צבותים</span>, read: <a href=\"#\" data-headword=\"צביתים\">צביתים</a>, v. <a href=\"#\" data-headword=\"צָבָה\">צָבָה</a>.]</div>","alt":[]},"23114":{"h":"צְבַת","r":"R00072","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"צָבַת\">same</a>, <i>to join, associate</i>. [<span class=\"citation\">Targ. Prov. XXIII, 32</span> some ed., read <span dir=\"rtl\">נכת</span>.]—<span class=\"citation\">Y. Keth. V, 30ᵃ</span> bot. <span dir=\"rtl\">חכים אנא לנשייא דצַבְתָן עם וכ׳</span> (not <span dir=\"rtl\">דצבתין</span>) I knew the women that kept my mother company (during her confinement), v. <a href=\"#\" data-headword=\"חֲכַם\">חֲכַם</a>.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"זְוַד\">זְוַד</a>) <i>to present, outfit</i>. <span class=\"citation\">Ḥull. 60ᵃ</span> בעינא דאִיצְבֵּית ליה נהמא וכ׳ I desire to offer bread (to sacrifice) to your God; <span dir=\"rtl\">פוק צְבִית לגידא וכ׳</span> go out and offer up at the banks (or landing) of the Rabitha where there is a wide plain. <span class=\"citation\">M. Kat. 27ᵇ</span> <span dir=\"rtl\">צבית זוודתא לאודך</span> ed. (read: <span dir=\"rtl\">צְבִיתִי</span>; Ms. M. <span dir=\"rtl\">תימוש האי וכ׳</span>) prepare a shroud for thy other son.</div><div class=\"sense\"><b>Ithpe. אִיצְטְבַת</b> <div class=\"sense\"><i>to be attached</i>. <span class=\"citation\">B. Bath. 80ᵃ</span> Ar., v. <a href=\"#\" data-headword=\"צְוַות\">צְוַות</a>.</div></div>","alt":[]},"23115":{"h":"צֶבֶת","r":"R00073","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"צְבַת\">preced.</a>) <i>couple, pair, set</i>. <span class=\"citation\">Tosef. Ab. Zar. III</span> (<span class=\"citation\">IV), 8</span> <span dir=\"rtl\">בצ׳ הראשון</span> of the first pair (of T’fillin); <span class=\"citation\">Erub. 97ᵃ</span>; a. e.—Pl. <span dir=\"rtl\">צְבָתִים</span>. <span class=\"citation\">Ib. X, 1</span> <span dir=\"rtl\">מצאן צ׳</span> if he found the T’fillin arranged in sets; expl. <span class=\"citation\">ib. 97ᵃ</span>, v. <a href=\"#\" data-headword=\"זָוָוא I\"><span dir=\"rtl\">זָוָוא</span> I</a>. <span class=\"citation\">Men. X, 9</span> (<span class=\"citation\">71ᵃ</span>) <span dir=\"rtl\">מניחן צ׳</span> (Talm. ed. <span dir=\"rtl\">צְבוּתִים</span>, v. Rabb. D. S. a. l. note 3; Ms. M. <a href=\"#\" data-headword=\"צבצין\">צבצין</a>, corr. acc.) he puts the sheaves down in sets (without tying them). Tosef. Ab. Zar. l. c.</div>","alt":[]},"23116":{"h":"צְבָת","r":"R00074","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צֶבֶת\">preced.</a>) <i>a pair of tongs</i> (cmp. <a href=\"#\" data-headword=\"זוּג\">זוּג</a>). <span class=\"citation\">Ab. V, 6</span> (among the things created in the last moment before the Sabbath) <span dir=\"rtl\">אף צ׳ בצ׳ עשויה</span> also tongs which (by human hands) can be made only by means of tongs; <span class=\"citation\">Pes. 54ᵃ</span> <span dir=\"rtl\">אף הצ׳</span> also the (first) tongs; v. next w.—<span class=\"citation\">Snh. VII, 2</span> <span dir=\"rtl\">פותחין את פיו בצ׳ וכ׳</span> they force his mouth open with tongs; <span class=\"citation\">Tosef. Sot. II, 3</span> (v. <a href=\"#\" data-headword=\"כַּלְבּוּס\">כַּלְבּוּס</a>). <span class=\"citation\">Erub. X, 15</span> <span dir=\"rtl\">צ׳ של עץ</span> wooden tongs; a. e.</div>","alt":[]},"23117":{"h":"צַבְתָּא","r":"R00075","html":"<div class=\"sense\"> c. ch. l) <a href=\"#\" data-headword=\"צְבָת\">same</a>. <span class=\"citation\">Gitt. 56ᵇ</span> <span dir=\"rtl\">שקלינן צ׳ וכ׳</span> we get a pair of tongs and take the serpent away … and save the cask. <span class=\"citation\">Pes. 54ᵃ</span> צַבְתָּנָא בצ׳ מתעבדא צ׳ … עבדה Ms. M. (ed. <span dir=\"rtl\">צ׳ בצ׳ מתעביד וכ׳</span>) our tongs are made with the help of tongs: who made the first tongs? Therefore the first tongs must have been a natural object; Tosef. Erub. XI (VIII), 23 (v. <a href=\"#\" data-headword=\"לַאי\">לַאי</a>); <span class=\"citation\">Tosef. Ḥag. I, 9</span> (applied to the numerous laws derived from a meagre text); expl. <span class=\"citation\">Y. Erub. X, end, 26ᵈ</span> <span dir=\"rtl\">מצ׳ אחת למדו צביתות הרבה וכ׳</span> from handling one pair of tongs (found as a natural object) they learned many manipulations with the tongs: so they derived numerous forbidden Sabbath labors by analogy from one intimated in the text.—Trnsf. <i>instrumentality</i>. <span class=\"citation\">B. Kam. 9ᵇ</span> <span dir=\"rtl\">צ׳ דחרש קגרים</span> (Rashi Var. <a href=\"#\" data-headword=\"צַוְותָּא\">צַוְותָּא</a>) the deaf and dumb (who was given charge of the fire) was the instrument that caused the damage; <span class=\"citation\">ib. 59ᵇ</span> (Ms. R. <a href=\"#\" data-headword=\"צַוְותָּא\">צַוְתָּא</a>, v. Rabb. D. S. a. l. note 40).—Pl. <span dir=\"rtl\">צִבְתַּיָּא</span>, <a href=\"#\" data-headword=\"צַבְתָּא\">צִיבְתַ׳</a>, <span dir=\"rtl\">צֵי׳</span>. <span class=\"citation\">Targ. I Kings VII, 49</span>. <span class=\"citation\">Targ. O. Num. IV, 9</span> (ed. Berl. <span dir=\"rtl\">צֵיבְתָ׳</span>). <span class=\"citation\">Targ. O. Ex. XXV, 38</span>; <span class=\"citation\">XXXVII, 23</span> <a href=\"#\" data-headword=\"צַבְתָּא\">צִיבְתָ׳</a> ed. Berl. (ed. Vien. a. oth. <span dir=\"rtl\">צִיבְיְתָ׳</span>, corr. acc.). <span class=\"citation\">Targ. II Chr. IV, 21</span>.—2) <i>company</i>, v. <a href=\"#\" data-headword=\"צַוְותָּא\">צַוְותָּא</a>.</div>","alt":["צִיבְתָא","צִבְ׳ I"]},"23118":{"h":"צִבְתָא","r":"R00076","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צְבַת\">צְבַת</a>) <i>outfit</i>, esp. <i>cosmetic preparations</i>. Targ. II Esth. II, 12 (h. text <span dir=\"rtl\">מרוק׳</span>).—Denom. <a href=\"#\" data-headword=\"צִבְיָאתָא\">צִבְיָאתָא</a>, <a href=\"#\" data-headword=\"צִבְחַד\">צִי׳</a> f. pl. <i>cosmetics</i>. Ib. 9 (ed. Amst. <span dir=\"rtl\">צָבֵיאָ׳</span>).</div>","alt":["צִי׳ II"]},"23119":{"h":"צִבְּתָא","r":"R00077","html":"<div class=\"sense\"><i>chips</i>, v. <a href=\"#\" data-headword=\"צִיבְּתָא\">צִיבְּתָא</a>.</div>","alt":[]},"23120":{"h":"צַד","r":"R00078","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> צדד <i>to join</i>; cmp. <a href=\"#\" data-headword=\"סַד\">סַד</a>) <i>side, border</i>. <span class=\"citation\">B. Mets. 11ᵃ</span> <span dir=\"rtl\">עומד בצד שדהו</span> he was standing at the border of his field. <span class=\"citation\">Snh. IV, 2</span> in capital cases <span dir=\"rtl\">מתחילין מן הצד</span> they begin to take the votes from the side bench (the junior judges), opp. <span dir=\"rtl\">הגדול</span>. <span class=\"citation\">Ib. 36ᵃ</span> (in Chald. dict.) <span dir=\"rtl\">כולהו … מן הצד הוו מתחלי</span> they began all their voting with the youngest; <span class=\"citation\">Gitt. 59ᵃ</span>. <span class=\"citation\">Snh. 38ᵇ</span> <span dir=\"rtl\">תשובתן בצִידָּן</span>, v. <a href=\"#\" data-headword=\"פָּקַר\">פָּקַר</a>. <span class=\"citation\">Gen. R. s. 8</span> <span dir=\"rtl\">בצִדָּהּ</span>, v. <a href=\"#\" data-headword=\"פִּתְחוֹן\">פִּתְחוֹן</a>. <span class=\"citation\">Nidd. 22ᵇ</span> <span dir=\"rtl\">מצד אחד</span>, v. <a href=\"#\" data-headword=\"פָּנָה\">פָּנָה</a>. <span class=\"citation\">Kidd. 74ᵇ</span> <span dir=\"rtl\">מצידה</span> (Var. in Ar. s. v. <a href=\"#\" data-headword=\"צַד\">צד</a>: <span dir=\"rtl\">מצמדה</span>), v. <a href=\"#\" data-headword=\"תְּבַר ²\">תַּבְרָא</a>.—<span class=\"citation\">B. Mets. 63ᵃ</span>, a. fr. <span dir=\"rtl\">צד אחד בריבית</span>, v. <a href=\"#\" data-headword=\"רִבִּית\">רִבִּית</a>. <span class=\"citation\">B. Kam. I, 1</span>, a. fr. <span dir=\"rtl\">הצד השוה שבהן</span> the points common to both, v. <a href=\"#\" data-headword=\"הֲרֵי I\"><span dir=\"rtl\">הֲרֵי</span> I</a>. <span class=\"citation\">Kidd. 78ᵃ</span>, a. e. <span dir=\"rtl\">מה להצד השוה וכ׳</span> what is the common point? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ומייתי לה במה הצד</span> and proves it by analogy from the common point. <span class=\"citation\">Ber. 35ᵃ</span> <span dir=\"rtl\">מה להצד … שכן יש בו צד מזבח</span> what is the common point? that it may eventually be used for the altar?; <span dir=\"rtl\">ואתי נמי זית … צד מזבח</span> and so is ‘olive’ included, which is eventually used on the altar (as oil). <span class=\"citation\">B. Mets. 115ᵃ</span> <span dir=\"rtl\">לצד שני</span> another interpretation.—<span dir=\"rtl\">מן הצד</span> sideways, <i>in an unusual manner, indirectly</i>. <span class=\"citation\">Sabb. 43ᵇ</span>, v. <a href=\"#\" data-headword=\"טִלְטוּל\">טִלְטוּל</a> h. <span class=\"citation\">Ib. 47ᵇ</span> <span dir=\"rtl\">בנין מן הצד</span> an indirect way of building (putting up a folding bed); a. fr.—<span dir=\"rtl\">כאיזה צד</span>, <span dir=\"rtl\">כאי זה צד</span>, <span dir=\"rtl\">כיזה צד</span>, v. <a href=\"#\" data-headword=\"כֵּיצַד\">כֵּיצַד</a>.—Pl. v. <a href=\"#\" data-headword=\"צְדָד\">צְדָד</a></div>","alt":[]},"23121":{"h":"צַד ²","r":"R00079","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"צֵיד\">צֵיד</a></div>","alt":[]},"23122":{"h":"צֵדָא","r":"R00080","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צֵידָא\">צֵידָא</a></div>","alt":[]},"23123":{"h":"צְדָא","r":"R00081","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צְדֵי\">צְדֵי</a></div>","alt":[]},"23124":{"h":"צַדְאוּתָא","r":"R00082","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צַדְיוּתָא\">צַדְיוּתָא</a></div>","alt":[]},"23125":{"h":"צָדַד","r":"R00083","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">צִידֵּד</span> (denom. of <a href=\"#\" data-headword=\"צַד\">צַד</a>) <i>to turn sideways, move aside; to arrange</i>. <span class=\"citation\">Gen. R. s. 8</span> <span dir=\"rtl\">מְצַדֵּד</span> man can look sideways (which other animals cannot); ib. s. 14. <span class=\"citation\">Yoma 55ᵃ</span> <span dir=\"rtl\">כשהוא מזה למעלה מצדד ידו וכ׳</span> when he is to sprinkle upwards, he turns first his hand down &amp;c. <span class=\"citation\">Sabb. 102ᵇ</span> <span dir=\"rtl\">המצדד את האבן</span> he who turns a building stone (makes room for it and sets it in its place). <span class=\"citation\">Bets. 32ᵇ</span> <span dir=\"rtl\">מותר לצַדְּדָן</span> you are permitted to arrange them for a seat; a. e.—Part. pass. <span dir=\"rtl\">מְצוּדָּד</span>, pl. <span dir=\"rtl\">מְצוּדָּדִין</span>. <span class=\"citation\">B. Bath. 99ᵃ</span> <span dir=\"rtl\">ומצ׳ פניהם וכ׳</span> their faces were turned sideways, like a disciple taking leave of his teacher.</div><div class=\"sense\"><b>Nif. נוֹצַד</b> <div class=\"sense\"> (for <span dir=\"rtl\">נָצַד</span>) <i>to be removed</i> (cmp. <a href=\"#\" data-headword=\"צדי ²\"><span dir=\"rtl\">צָדָה</span> II</a>). <span class=\"citation\">Ruth R. to II, 14</span> (play on <a href=\"#\" data-headword=\"מְצָד\">מִצּד</a> ib.) <span dir=\"rtl\">שנוֹצַדָּה לו … לשעה</span> his government was taken away from him for a time. Ib. <span dir=\"rtl\">שעתידה מלכותו לִיצַּד ממנו וכ׳</span> his government was destined to be taken away &amp;c. <span class=\"citation\">Gen. R. s. 26</span> <span dir=\"rtl\">שיִּצּוֹד</span>, v. <a href=\"#\" data-headword=\"צדי ²\"><span dir=\"rtl\">צָדָה</span> II</a>.</div></div>","alt":[]},"23126":{"h":"צְדַד","r":"R00084","html":"<div class=\"sense\"><i>Pa.</i> <span dir=\"rtl\">צַדֵּד</span> <a href=\"#\" data-headword=\"צָדַד\">same</a>. <span class=\"citation\">Targ. Prov. XXIII, 5</span> <span dir=\"rtl\">אין תְּצַד וכ׳</span> ed. Lag. (oth. ed. <span dir=\"rtl\">תצר</span>) if thou turnest thy eye (h. text <span dir=\"rtl\">התעיף</span>, v. Pesh. a. l.).—<span class=\"citation\">Targ. Y. Lev. XVI, 24</span> (cmp. <span class=\"citation\">B. Bath. 99ᵃ</span>, quot. in <a href=\"#\" data-headword=\"צָדַד\">preced.</a>).—<span class=\"citation\">Sabb. 102ᵇ</span> תתאה בעי צַדּוּדֵי וכ׳ Ms. M. (ed. <span dir=\"rtl\">תתא</span>) to place the lowest stone it is necessary to make room for it in the ground and surround it with earth (v. <a href=\"#\" data-headword=\"צָדַד\">preced.</a>). <span class=\"citation\">Yoma 37ᵃ</span> <span dir=\"rtl\">דמְצַדֵּד אַצְדּוּדֵי</span> (Rashi <span dir=\"rtl\">דמִיצֵּדּד</span>, <i>Ithpa.</i>) he turns sideways. <span class=\"citation\">B. Bath. 99ᵃ</span> <span dir=\"rtl\">דמְצַדְּדֵי אצדודי</span> they (the Cherubim) were turned sideways (so as to face both the house and each other). <span class=\"citation\">Sabb. 141ᵃ</span> <span dir=\"rtl\">לא לִיצַדֵּד וכ׳</span> (or <span dir=\"rtl\">לִיצַּדֵּד</span>, <i>Ithpa.</i>), v. <a href=\"#\" data-headword=\"כּוּבָּא II\"><span dir=\"rtl\">כּוּבָּא</span> II</a>.</div><div class=\"sense\"><b>Af. אַצְדַד</b> <div class=\"sense\">, inf. <span dir=\"rtl\">אצְדּוּדֵי</span>, v. supra.</div></div>","alt":[]},"23127":{"h":"צְדָד","r":"R00085","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"צַד\">צַד</a>; pl. <span dir=\"rtl\">צְדָדִים</span>, <span dir=\"rtl\">צְדָדִין</span>. <span class=\"citation\">Ḥull. 8ᵃ</span> <span dir=\"rtl\">והאיכא צ׳</span> but are there not the sides (of the heated knife which burn instead of cutting)? <span class=\"citation\">Y. Sabb. XIII, end, 14ᵇ</span> <span dir=\"rtl\">צִידְדֵי בהמה</span> the sides of a beast. Bab. <span class=\"citation\">Sabb. 154ᵇ</span> <span dir=\"rtl\">צ׳ הן וצ׳ לא וכ׳</span> this is making use of the sides of a beast, and this the Rabbis have not forbidden. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">צִדְדֵי צ׳</span> the sides of sides, indirect use of the sides of an object (v. <a href=\"#\" data-headword=\"צַד\">צַד</a>). <span class=\"citation\">Sifré Num. 126</span> <span dir=\"rtl\">בכל צְדָדָיו</span> on any of its sides, opp. entrance of the tent. <span class=\"citation\">Nidd. 22ᵇ</span>, v. <a href=\"#\" data-headword=\"פָּנָה\">פָּנָה</a>. <span class=\"citation\">Sabb. 6ᵃ</span> <span dir=\"rtl\">צִדֵּי רשות הרבים</span> the sides (the walls &amp;c.) along the public road. <span class=\"citation\">Ib. 99ᵃ</span> <span dir=\"rtl\">צידי עגלה</span> the sides of a wagon; <span dir=\"rtl\">עגלות תחתיהן וביניהן וצִידֵּיהֶן</span> the spaces under wagons and between them, and their outsides. <span class=\"citation\">Y. Peah VI, 19ᶜ</span> top <span dir=\"rtl\">דבר שהוא חומר משני צ׳</span> where a rule works as a restriction both ways; a. fr.—<span class=\"citation\">B. Kam. 16ᵇ</span>, a. e. <span dir=\"rtl\">לצ׳ קתני</span> it is meant in either way, i.e. disjunctively, the one or the other. Y. Yeb. IV, 5ᵈ <span dir=\"rtl\">לצ׳ … או וכ׳</span></div>","alt":[]},"23128":{"h":"פְּסִיעַ","r":"Q01304","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּסַע\">פְּסַע</a>) <i>bandy-legged, waddling</i>. <span class=\"citation\">Targ. Y. Lev. XXI, 18</span> Ar. (ed. <span dir=\"rtl\">מישתמיט יריכיה</span>; h. text <span dir=\"rtl\">שרוע</span>).</div>","alt":[]},"23129":{"h":"פְּסִיעָא","r":"Q01305","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסִיעֲתָא\">פְּסִיעֲתָא</a></div>","alt":[]},"23130":{"h":"פְּסִיעָה","r":"Q01306","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַע\">פָּסַע</a>) <i>step, walk</i>. <span class=\"citation\">Ber. 6ᵇ</span>, a. fr. <span dir=\"rtl\">פ׳ גסה</span>, v. <a href=\"#\" data-headword=\"גַּס III\"><span dir=\"rtl\">גַּס</span> III</a>. <span class=\"citation\">Gen. R. s. 39</span> <span dir=\"rtl\">ליתן שכר על כל פ׳ ופ׳</span> to reward him for every step. <span class=\"citation\">Koh. R. to VII, 2</span> ‘and the living shall take it to heart’ (ib.) <span dir=\"rtl\">זה חי העולמים … על כל פ׳ ופ׳ וכ׳</span> that means the Everliving who rewards man for every step he takes for deeds of charity. <span class=\"citation\">Pesik. R. s. 33</span> (ref. to <span class=\"citation\">Is. LI, 14</span>) <span dir=\"rtl\">מן אדם שהוא ממהר בפְסִיעָתוֹ בשביל להיפתח וכ׳</span> art thou afraid of man who hastens his step to have an opening … and runs with hasty step, that he may not miss his bread?; <span class=\"citation\">Yalk. Is. 336</span>; a. fr.—Pl. <span dir=\"rtl\">פְּסִיעוֹת</span>. <span class=\"citation\">Yoma 53ᵇ</span> <span dir=\"rtl\">המתפלל צריך שיפסיע שלש פ׳ לאחוריו וכ׳</span> he who is in prayer (when a person enters), must pass three steps backward (when he ends his prayer), and then turn around to salute. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דפסעי להו שלש פ׳ בכריעה אחת</span> they made the three steps back ward with one bow. <span class=\"citation\">Snh. 22ᵃ</span> (he who loses his wife) <span dir=\"rtl\">פְּסִיעוֹתָיו מתקצרות</span> has his steps shortened (his energies broken, with ref. to <span class=\"citation\">Job XVIII, 7</span>). <span class=\"citation\">Sabb. 63ᵇ</span> <span dir=\"rtl\">שהיו פְסִיעוֹתֵיהֶם גסות</span> who used to make wide steps. <span class=\"citation\">Num. R. s. 4</span>; a. fr.</div>","alt":[]},"23131":{"h":"פְּסִיעֲתָא","r":"Q01307","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ps. XVIII, 37</span>; <span class=\"citation\">II Sam. XXII, 37</span>; a. e.—Pl. <a href=\"#\" data-headword=\"פְּסִיעֲתָא\">פְּסִיעָתָא</a>, <a href=\"#\" data-headword=\"פְּסִיעָא\">פְּסִיעָן</a>. <span class=\"citation\">Targ. Job XIV, 16</span> (not <span dir=\"rtl\">פְּסִיעוֹתַי</span>). <span class=\"citation\">Ib. XXXI, 4</span>; a. fr.—<span class=\"citation\">Y. Snh. VIII, 26ᵇ</span> bot. <span dir=\"rtl\">בגין דהליך תרתין פ׳ הוא מפסיד</span> shall he be at a disadvantage, because he walked two steps (into the court room)?; <span class=\"citation\">Y. Shebu. VII, 38ᵃ</span> (corr. acc.); <span class=\"citation\">Y. Keth. IX, 33ᵇ</span> bot.</div>","alt":["פְּסִיעָא"]},"23132":{"h":"פסיפון","r":"Q01308","html":"<div class=\"sense\">, Pesik. Vattom., p. 131ᵃ Ar., v. <a href=\"#\" data-headword=\"*פיספיסאי\">פיספיסאי</a>.—<span class=\"citation\">Lam. R. to II, 1</span> Mus., v. <a href=\"#\" data-headword=\"פְּסִיפָּס\">next w.</a></div>","alt":["פסיפין"]},"23133":{"h":"פְּסִיפָּס","r":"Q01309","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַס\">פָּסַס</a>, cmp. <a href=\"#\" data-headword=\"פְּסִיסִית\">פְּסִיסִית</a>) </div><div class=\"sense\"><b>1)</b> <i>cut and polished stone block</i>, used for paving floors, <i>stone pavement, mosaic</i>. <span class=\"citation\">Ab. d’R. N. ch. XXVIII</span> <span dir=\"rtl\">אבן פסי׳ שיש וכ׳</span> ed. Schechter (ed. <span dir=\"rtl\">פיספס</span>) a paving block which has four polished sides (a metaphor for a many-sided scholar). <span class=\"citation\">Y. Sabb. VII, 10ᵇ</span> top <span dir=\"rtl\">בשאין שם פ׳</span> where there is no stone pavement. Ib. XII, beg. 13ᶜ (Chald. dict.) <span dir=\"rtl\">מקטע פ׳</span> he who trims a paving stone (or die, v. infra). <span class=\"citation\">Ex. R. s. 10</span> <span dir=\"rtl\">בתיהם של גדולים … בשיש בפ׳</span> the houses of the nobles which were paved with marble or blocks; <span class=\"citation\">Yalk. Sam. 102</span> <span dir=\"rtl\">בתי השיש והפִּסְפְּסִים</span> (pl.); <span class=\"citation\">Yalk. Ps. 820</span> <span dir=\"rtl\">בתי השיש ובתי הפ׳</span> (<span class=\"citation\">Midr. Till. to Ps. CV</span> <span dir=\"rtl\">בתי הסיפים</span>, v. <a href=\"#\" data-headword=\"סַף\">סַף</a>). <span class=\"citation\">Deut. R. s. 1</span> <span dir=\"rtl\">ואם בפ׳ הפ׳ וכ׳</span> and if (she wipes her hands) on the pavement, the pavement will be blackened, but her hands will not be clean; a. e.—Pl. <span dir=\"rtl\">פְּסִיפְסִים</span>, <span dir=\"rtl\">פְּסִיפְסִין</span>, <span dir=\"rtl\">פִּסְפְּ׳</span>, <a href=\"#\" data-headword=\"פַּסְגָּא\">פִּיסְ׳</a>. Yalk. Sam. l. c.; Yalk. Ps. l. c., v. supra. <span class=\"citation\">Midd. I, 6</span> ראשי פסי׳ וכ׳ Var. in Ar. s. v. <a href=\"#\" data-headword=\"פַּשְׁפֵּשׁ I\">פשפש</a> (Mish. ed. <span dir=\"rtl\">פספ׳</span>; Talm. ed. <span dir=\"rtl\">פישפשין</span>) the ends of the flag-stones in the pavement indicated the mark between the sacred and the secular grounds; [comment.: blocks on the ceiling]; ib. II, 6; a. e.—[<span class=\"citation\">Tosef. Zeb. VII, 1</span> <span dir=\"rtl\">פסיפסין</span>, Var. <span dir=\"rtl\">פסיפיסין</span>, v. <a href=\"#\" data-headword=\"פַּשְׁפֵּשׁ I\"><span dir=\"rtl\">פִּשְׁפָשׁ</span> I</a>.]</div><div class=\"sense\"><b>—2)</b> <i>cube, die</i>.—<i>Pl.</i> as ab. <span class=\"citation\">Y. R. Hash. I, 57ᶜ</span> top (expl. <span dir=\"rtl\">המשחק בקוביא</span>) <span dir=\"rtl\">המשחק בפסי׳</span> he who plays with dice; <span class=\"citation\">Snh. 25ᵇ</span>, a. e. <span dir=\"rtl\">בפיספ׳</span> (Rashi: blocks of wood); Y. l. c. <span dir=\"rtl\">משישבור את פְּסִיפְסָיו</span> (he is not reinstated from his civil disabilities,) until he breaks his dice; Snh. l. c. <span dir=\"rtl\">משישברו את פִּיסְפְּסֵיהֶן</span>; Y. Shebu. VII, 37ᵈ bot. <span dir=\"rtl\">פִּיסְפְּסָיו</span>; <span class=\"citation\">Y. Snh. III, beg., 21ᵃ</span> (also <a href=\"#\" data-headword=\"פְּשִׁיפְשִׁין\">פְּשִׂיפְשִׂין</a>). <span class=\"citation\">Midr. Till. to Ps. XXVI, 10</span> <span dir=\"rtl\">אלי המשחקין בפספ׳ וכ׳</span> that means those who play with dice, who calculate (throw) with the left hand and press with the right hand, and rob and wrong one another; a. e.</div><div class=\"sense\"><b>—3)</b> <i>check</i> (in garments), <i>square</i>, or <i>stripe</i> (cmp. <a href=\"#\" data-headword=\"פַּס\">פַּס</a>). <span class=\"citation\">Neg. XI, 7</span> <span dir=\"rtl\">והרי הוא פסי׳ יחידי</span> ed. Dehr. (ed. <a href=\"#\" data-headword=\"פִּסְפֵּס I\">פספס</a>) suppose there is only one (white) stripe in the whole garment?—Pl. as ab. Ib. <span dir=\"rtl\">קייטא שיש בה פ׳ צבועים וכ׳</span> a pieced sheet in which there are checkers colored and white; Tosef. ib. V, 10. <span class=\"citation\">Yalk. Job 927</span> <span dir=\"rtl\">פספסין הדֵּיהוֹת שלו מכחות וכ׳</span> (or <span dir=\"rtl\">הדּוּחוֹת</span>, not <span dir=\"rtl\">פספסי הרוחות</span>) the faintest checkers (or stripes) of the Leviathan’s skin outshine the sun (v. <span class=\"citation\">Yalk. Lev. 653</span>).</div><div class=\"sense\"><b>—4)</b> <i>voting tablet, verdict</i>. <span class=\"citation\">Lam. R. to II, 1</span>, v. <a href=\"#\" data-headword=\"חִיתּוּךְ\">חִיתּוּךְ</a>.—[The contact between the Hebrew and Greek languages influenced the form <span dir=\"rtl\">פסיפס</span> and the coincidence of some meanings of our word with ψῆφος <i>pebble</i>.]</div>","alt":["פִּסְפָּס","פִּיסְ׳"]},"23134":{"h":"*פְּסִיפַּס","r":"Q01310","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Kings V, 31</span> אבן פ׳ Ar. (ed. <span dir=\"rtl\">אבנין פסילן</span>; h. text <a href=\"#\" data-headword=\"גָּזִית\">גזית</a>).—<span class=\"citation\">Y. Sabb. XII, beg. 13ᶜ</span> <span dir=\"rtl\">מקטע פספס</span>, v. <a href=\"#\" data-headword=\"פְּסִיפָּס\">preced.</a></div>","alt":[]},"23135":{"h":"פְּסֵיק","r":"Q01311","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסַק\">פְּסַק</a></div>","alt":["פְּסִיק"]},"23136":{"h":"פְּסִיקָא I","r":"Q01312","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּסַק\">פְּסַק</a>) </div><div class=\"sense\"><b>1)</b> <i>part, fraction</i>. <span class=\"citation\">B. Bath. 62ᵇ</span>, sq., contrad. to <span dir=\"rtl\">פלגא</span>.</div><div class=\"sense\"><b>—2)</b> <i>subscription for charity, collection</i>. <span class=\"citation\">Lev. R. s. 32</span>, end <span dir=\"rtl\">ואנן עבדין לך פ׳ בציבורא</span> and we shall arrange a collection for you in the assembly; <span dir=\"rtl\">עבדון ליה פ׳</span> they made up a purse for him. <span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">עביד פְּסִיקָה למתן וכ׳</span> (not <span dir=\"rtl\">למיתן</span>) arranged a subscription for a charity in the college of Tiberias.</div><div class=\"sense\"><b>—3)</b>  = <a href=\"#\" data-headword=\"פְּסוּקָא\">פְּסוּקָא</a>, <i>verse</i>.—Pl. <a href=\"#\" data-headword=\"פְּסִיקָה\">פְּסִיקָן</a>, v. <a href=\"#\" data-headword=\"פְּסוּקָא\">פְּסוּקָא</a>.</div>","alt":[]},"23137":{"h":"פְּסִיקָא II","r":"Q01313","html":"<div class=\"sense\"><i>fillet</i>, v. <a href=\"#\" data-headword=\"פְּסִיקְיָא\">פְּסִיקְיָא</a>.</div>","alt":[]},"23138":{"h":"פְּסִיקָה","r":"Q01314","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>) </div><div class=\"sense\"><b>1)</b> <i>cutting apart</i>. <span class=\"citation\">Succ. 11ᵃ</span> <span dir=\"rtl\">פְּסִיקָתָן זו היא עשייתן</span> cutting the threads apart is the making of them (the show fringes).</div><div class=\"sense\"><b>—2)</b> <i>separated thread.</i> <span class=\"citation\">Neg. XI, 8</span> <span dir=\"rtl\">אפי׳ פ׳ אחת וכ׳</span> even if only one separate thread was on the coil, and he knotted it.—Pl. <span dir=\"rtl\">פְּסִיקוֹת</span>. Ib. <span dir=\"rtl\">היתה פ׳</span> if the coil consisted of separate threads.</div>","alt":[]},"23139":{"h":"פְּסִיקָה ²","r":"Q01315","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"פְּסִיקָא I\">פְּסִיקָא</a></div>","alt":[]},"23140":{"h":"פְּסֵיקָה","r":"Q01316","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>, v. <i>Hif.</i> 4) <i>water collected behind a dam, reservoir, pool.</i> <i>—</i> Pl. <span dir=\"rtl\">פְּסֵיקוֹת</span>. <span class=\"citation\">M. Kat. 4ᵃ</span> <span dir=\"rtl\">הפ׳ והבריכות וכ׳</span> pools and ponds which were filled with water on the eve of a Holy Day.</div>","alt":[]},"23141":{"h":"פסיקוליה","r":"Q01317","html":"<div class=\"sense\">, Y. Peah I, 15ᵈ <span dir=\"rtl\">בפ׳ אחרייא</span>, read: <span dir=\"rtl\">כדפסיקו ליה לאחרייא</span>, v. <a href=\"#\" data-headword=\"פְּסַק\">פְּסַק</a></div>","alt":[]},"23142":{"h":"פְּסִיקְיָא","r":"Q01318","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (an adapt. of fascia, as if from <span dir=\"rtl\">פסק</span>) <i>band</i> or <i>fillet</i> worn by women over the breast; <i>girdle; bandage round the legs and feet</i>. <span class=\"citation\">Targ. Is. III, 24</span> <a href=\"#\" data-headword=\"פְּסִיקְיָא\">פְּסִיקַיָּא</a> (<i>pl.</i> form).—<span class=\"citation\">Y. Snh. X, 28ᵈ</span> bot. <span dir=\"rtl\">נתן את הברזל תחת פ׳ שלו</span> he put the iron point of his spear under his <i>fascia</i>. <span class=\"citation\">Sabb. XV, 2</span> (<span class=\"citation\">111ᵇ</span>) <span dir=\"rtl\">ושל פסי׳</span> (Bab. ed. <a href=\"#\" data-headword=\"פְּסִקְיָא\">פסקיא</a>) and the cords of the breast bandage. Ib. (113ᵃ) <span dir=\"rtl\">קושרין דלי בפ׳ וכ׳</span> (Bab. ed. <span dir=\"rtl\">בפסק׳</span> you may (on the Sabbath) tie up (the broken rope of) a bucket with a <i>fascia</i>, but not with a rope. Ib. 113ᵃ <span dir=\"rtl\">כורך עליו פונדא או פ׳</span> (Ms. M. <a href=\"#\" data-headword=\"פְּסִיקָא I\">פסיקא</a>) he may wind a <i>funda</i> or a <i>fascia</i> around it; <span class=\"citation\">Pes. 11ᵃ</span> <a href=\"#\" data-headword=\"פִּיסְקְיָא\">פיסקיא</a> (Ms. M. <a href=\"#\" data-headword=\"פְּסִיקְיָא\">פסיקיא</a>; early ed. <span dir=\"rtl\">פסקי</span>, v. Rabb. D. S. a. l. note). <span class=\"citation\">Y. Kil. IX, end, 32ᵈ</span> <span dir=\"rtl\">פיסקי</span> (corr. acc.), v. <a href=\"#\" data-headword=\"עֲגַל I\"><span dir=\"rtl\">עֲגַל</span> I</a>; a. e.—<i>Pl.</i> form <span dir=\"rtl\">פְּסִיקִין</span>. <span class=\"citation\">Sifré Num. 131</span> <span dir=\"rtl\">והיא מוציאה … מתחת פ׳ שלה</span> (not <span dir=\"rtl\">פסוקין</span>) she took an impression of Peor from under her breast band (<span class=\"citation\">Snh. 106ᵃ</span> <span dir=\"rtl\">חיקה</span>).</div>","alt":["פְּסִיקְיָה","פִּסְקְ׳"]},"23143":{"h":"פְּסִיקְתָּא","r":"Q01319","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּסַק\">פְּסַק</a>) </div><div class=\"sense\"><b>1)</b> <i>apportionment, agreement to pay</i>, esp. <i>dowry</i>. <span class=\"citation\">M. Kat. 18ᵇ</span> <span dir=\"rtl\">שטרי פ׳</span> agreements stating the amounts which the parents promise to their respective son or daughter; <span class=\"citation\">Kidd. 9ᵇ</span>; <span class=\"citation\">Keth. 102ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>section</i>, esp. <i>P’siḳta</i>, name of several Midrashim, <i>a</i>) <i>P.</i> <i> d’R. Kahăna</i> (or only <i>P’siḳta</i>) (edited by S. Buber).—<i>b</i>) <i>P. Rabbathi</i> (<i>Large P</i>.).—<i>c</i>) (of late origin) P. <i>Zuṭarta</i> or <i>Zuṭrathi</i> (Small P.) (edited by S. Buber).—[</div><div class=\"sense\"><b>3)</b> <i>a small share</i>, v. <a href=\"#\" data-headword=\"פִּיסְקְתָא\">פִּיסְקְתָא</a>.]</div>","alt":["פְּסִקְ׳ I"]},"23144":{"h":"פְּסִיקְתָּא II","r":"Q01320","html":"<div class=\"sense\"> pr. n. m., v. <a href=\"#\" data-headword=\"פְּסָאקָא\">פְּסָאקָא</a></div>","alt":[]},"23145":{"h":"*פְּסַךְ","r":"Q01321","html":"<div class=\"sense\">, <i>Pa.</i> פַּסֵּךְ <i>to cut, clear</i> (of thorns).—Part. pass. <span dir=\"rtl\">מְפַסַּךְ</span>; pl. <span dir=\"rtl\">מְפַסְּ֫כִּין</span>. <span class=\"citation\">Targ. Is. XXXIII, 12</span> (ed. Wil. <span dir=\"rtl\">מפסחין</span>, corr. acc.). [Prob. to be read: <span dir=\"rtl\">מְכַסְּחִין</span>.]</div>","alt":[]},"23146":{"h":"פְּסַכְתֵּיר","r":"Q01322","html":"<div class=\"sense\">, v. next wds.</div>","alt":["פְּסַכְתֵּירָא"]},"23147":{"h":"פְּסַכְתֵּר","r":"Q01323","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (corresp. to ψυχθηρ = ψυκτήρ) [<i>wine-cooler</i>,] <i>a large pot</i>. <span class=\"citation\">Y. Ḥag. III, 79ᵃ</span>; <span class=\"citation\">Tam. V, 5</span> <span dir=\"rtl\">כופה … פ׳</span> (,Ar. everywhere <a href=\"#\" data-headword=\"פְּסִיקְיָא\">פסק׳</a>), v. <a href=\"#\" data-headword=\"כפי\">כָּפָה</a>; ib. <span dir=\"rtl\">ופ׳ היה כלי וכ׳</span> the <i>psykter</i> was a large vessel, holding &amp;c. Sifré Tsav, Par. 1, ch. II; <span class=\"citation\">Y. Yoma IV, end, 42ᵃ</span>; <span class=\"citation\">Num. R. s. 4</span>. <span class=\"citation\">Erub. X, 15</span>; a. e.</div>","alt":[]},"23148":{"h":"פְּסַכְתֵּרָא","r":"Q01324","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">פְּסַכְתֵּרָוָותָא</span>. <span class=\"citation\">Targ. O. Ex. XXXVIII, 3</span> (ed. Berl. <a href=\"#\" data-headword=\"פְּסַכְתֵּיר\">פְּסַכְתֵּירָ׳</a>, some ed. <a href=\"#\" data-headword=\"פְּסֵיכְתֵּרָא\">פְּסֵיכְתֵּירָ׳</a>; h. text <span dir=\"rtl\">סירות</span>). Ib. XXVII, 3.</div>","alt":[]},"23149":{"h":"פָּסַל","r":"Q01325","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to cut, chip, hew, trim</i>. Tanḥ. ʿEḳeb 9 (ref. to <span class=\"citation\">Koh. III, 5</span>) <span dir=\"rtl\">עת היה לִפְסוֹל שני וכ׳</span> the time came to hew other two tablets (in place of the broken). Ib. <span dir=\"rtl\">מתחת כסא הכבוד פְּסָלָּן</span> he hewed them from under the throne of glory. <span class=\"citation\">Ab. Zar. 52ᵃ</span> (ref. to <span class=\"citation\">Deut. VII, 25</span>) <span dir=\"rtl\">משפְּסָלוֹ נעשה אלוה</span> as soon as a gentile has done chiselling on it, it becomes a deity (an idol forbidden to Jews for any use); ib. <span dir=\"rtl\">פסלו לאלוה לא וכ׳</span> when the gentile has hewed it for a god, thou shalt not covet it; <span dir=\"rtl\">פסלו מאלוה ולקחת לך</span> when he chips it so as to unfit it as an idol (v. infra), thou mayest take it unto thyself; a. e.—<i>Part. pass.</i> <a href=\"#\" data-headword=\"פָּסוּל\">פָּסוּל</a>; f. <a href=\"#\" data-headword=\"פְּסוּלָה\">פְּסוּלָה</a>; pl. <span dir=\"rtl\">פְּסוּלִים</span>, <span dir=\"rtl\">פְּסוּלִין</span>; <span dir=\"rtl\">פְּסוּלוֹת</span> <i>a</i>) <i>chiselled, chipped</i>. <span class=\"citation\">Lev. R. s. 22</span> <span dir=\"rtl\">אבנים פ׳</span> chipped stones (unfit for the altar); a. e.—<i>b</i>) (cmp. <a href=\"#\" data-headword=\"פָּגַם\">פָּגַם</a>) <i>defective, unfit, disqualified</i>, v. <a href=\"#\" data-headword=\"פָּסוּל\">פָּסוּל</a>.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"פָּסוּל\">פָּסוּל</a>) <i>to disqualify, to be the cause of disqualification of; to declare unfit</i>. <span class=\"citation\">Ḥull. III, 12</span> <a href=\"#\" data-headword=\"פוסלין\">פּוֹסְלִין</a>, v. <a href=\"#\" data-headword=\"כָּשֵׁר I\"><span dir=\"rtl\">כָּשֵׁר</span> I</a>. Ab. Zar. l. c. <span dir=\"rtl\">מניין לנכרי שפּוֹסֵל אלוהו</span> how will you prove that a gentile can cancel his deity (by disfiguring it)? <span class=\"citation\">Kidd. 70ᵃ</span> <span dir=\"rtl\">אוי לו לפוסל את זרעו ולפוגם וכ׳</span> woe to him who causes his descendants to be disqualified and his family to be tarnished. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כל הפוסל פסול</span> he who tarnishes (casts suspicion on the purity of a family) is himself tarnished (of spurious descent); <span dir=\"rtl\">במומו פוסל</span> he charges others with his own defect. <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">החזירתו … ופ׳ את כלן</span> she (Pharaoh’s daughter) took him (the infant Moses) around to all Egyptian women to give him suck, but he rejected all of them (refused to take their breasts); <span dir=\"rtl\">ולמה פְסָלָן</span> and why did he reject them? <span class=\"citation\">Snh. III, 1</span> <span dir=\"rtl\">זה פוֹסֵל דיינו של זה וכ׳</span> each has a right to reject the judge chosen by the other; <span dir=\"rtl\">אם היו כשרים … אינו יכול לפוֹסְלָן</span> if they are fit (not legally disqualified) or authorized, he cannot reject them. Ib. <span dir=\"rtl\">זה פוסל עדיו וכ׳</span> every witness in a case may help by his testimony to disqualify the opposing party’s witnesses. <span class=\"citation\">R. Hash. I, 7</span> <span dir=\"rtl\">קבלו … ופָסְלוּ וכ׳</span> they accepted as witnesses himself and his son, and rejected his slave. <span class=\"citation\">Mikv. II, 4</span> <span dir=\"rtl\">פּוֹסְלִין את המקוה</span> are sufficient to make the pond unfit for ritual immersion. <span class=\"citation\">Ib. VII, 5</span> <span dir=\"rtl\">לא פְסָלוּהוּ</span> they do not make the blood unfit. <span class=\"citation\">Zeb. I, 4</span> <span dir=\"rtl\">המחשבה פוֹסֶלֶת</span> the improper intention makes the sacrifice unfit. <span class=\"citation\">Succ. II, 7</span>, a. e. <span dir=\"rtl\">בית שמאי פוסלין</span> the school of Sh. declares such a Succah to be ritually unfit; a. v. fr.—Trnsf. <i>to cancel, abrogate</i>. <span class=\"citation\">B. Kam. 97ᵃ</span> <span dir=\"rtl\">פְּסָלַתּוּ מלכות</span> the government cancelled the coin; <span dir=\"rtl\">פסלתו מדינה</span> the inhabitants of the district refused to pass it.—<span class=\"citation\">Gen. R. s. 30</span>, beg. <span dir=\"rtl\">כל מקום שנאמר אלה פ׳ את הראשונים וכ׳</span> wherever the Biblical text has ‘these’, it is meant to cancel (exclude) the preceding; wherever it has ‘and these’, it is to add to the preceding; <span class=\"citation\">Ex. R. s. 1</span> אלה תולדות … פ׳ וכ׳ ‘these are the origins of heaven and earth’ (<span class=\"citation\">Gen. II, 4</span>), this excludes the time of chaos; a. fr.</div><div class=\"sense\"><b>Nif. נִפסַל</b> <div class=\"sense\"><b>1)</b> <i>to be hewn, sculptured</i>. Sifra K’dosh. beg. <span dir=\"rtl\">פסל על שהם נִפְסָלִין</span> idols are named <i>pesel</i>, because they are sculptured; (<span class=\"citation\">Yalk. Lev. 604</span> <span dir=\"rtl\">פסולין</span>).</div><div class=\"sense\"><b>—2)</b> <i>to be disqualified, made unfit, declared unfit</i>. <span class=\"citation\">Zeb. I, 4</span> <span dir=\"rtl\">הזבח נ׳ ארבעה וכ׳</span> a sacrifice may become unfit by improper actions in four stages, at the slaughtering &amp;c. <span class=\"citation\">Pes. 15ᵇ</span>; <span class=\"citation\">45ᵇ</span> <span dir=\"rtl\">הפת … ונִפְסְלָה מלאכול</span> if bread becomes mouldy and unfit for man to eat. <span class=\"citation\">Toh. VIII, 6</span> <span dir=\"rtl\">עד שיִפָּסֵל מאוכל הכלב</span> until it becomes unfit for a dog to eat; Y. Ḥall. IV, 60ᵃ top <span dir=\"rtl\">עד שתִּפְסוֹל</span>. [<span class=\"citation\">Men. 100ᵃ</span>, v. <a href=\"#\" data-headword=\"פְּסוֹל\">פְּסוֹל</a>.] <span class=\"citation\">Num. R. s. 6</span> end <span dir=\"rtl\">לא היו נִפְסָלִים אלא בקול</span> they (the Levites) became unfit for service only when they lost their voice for song. <span class=\"citation\">B. Kam. IX, 2</span> <span dir=\"rtl\">נִפְסְלָה מעל גבי המזבח</span> became unfit for the altar; a. fr.—Trnsf. <i>to be cancelled, abrogated</i>. B. Kam. l. c. <span dir=\"rtl\">מטבע ונ׳</span> (<a href=\"#\" data-headword=\"גְּזַל I\">גזל</a>) if one stole a coin, and it was invalidated (before he made the restitution). <span class=\"citation\">Snh. 104ᵇ</span> (expl. <span dir=\"rtl\">סִלָּה</span>, <span class=\"citation\">Lam. I, 15</span>) <span dir=\"rtl\">כאדם שאומר לחברו נפסלה מטבע זו</span> as one says to his neighbor, this coin is worthless; v. <a href=\"#\" data-headword=\"סָלָא\">סָלָא</a>; a. e.</div></div><div class=\"sense\"><b>Pi. פִּיסֵּל</b> <div class=\"sense\"><i>to cut off dry twigs, to trim.</i> <span class=\"citation\">Shebi. II, 3</span> <span dir=\"rtl\">מְפַסְּלִין עד וכ׳</span> (in the ante-Sabbatical year) you may trim trees up to New Year, v. <a href=\"#\" data-headword=\"פִּיסּוּל\">פִּיסּוּל</a>. <span class=\"citation\">Mikv. IX, 7</span> <span dir=\"rtl\">מְפַסְּלי אילנות</span> trimmers of trees. Y. Sabb. VII, 10ᵃ top; a. e.—<span class=\"citation\">Yalk. Deut. 942</span> <span dir=\"rtl\">מְפַסְּלוֹ במעצד</span> he chips it (the crooked staff) with the adze; Sifré <span class=\"citation\">ib. 308</span> <span dir=\"rtl\">מפתלו</span> (corr. acc.).</div></div><div class=\"sense\"><b>Hif. הִפְסִיל</b> <div class=\"sense\"><i>to find fault, to speak contemptuously</i>. <span class=\"citation\">Koh. R. to XI, 9</span> <span dir=\"rtl\">שהיה מַפְסִיל בנשים וכ׳</span> who used to find fault with women (considering none good enough for him as wife), and was a profligate.—[Part. pass. <span dir=\"rtl\">מוּפְסָל</span>, v. next w.]</div></div>","alt":[]},"23150":{"h":"פְּסַל","r":"Q01326","html":"<div class=\"sense\"><b>1)</b> <i>to cut, hew, dig</i>. <span class=\"citation\">Targ. Ex. XXXIV, 1</span>. <span class=\"citation\">Targ. Deut. VI, 11</span>; a. fr.—Part. pass. <a href=\"#\" data-headword=\"פָּסִיל\">פְּסִיל</a>; f. <a href=\"#\" data-headword=\"פְּסִילָא\">פְּסִילָא</a>; pl. <span dir=\"rtl\">פְּסִילִין</span>; <a href=\"#\" data-headword=\"פְּסִילָא\">פְּסִילָן</a>, <span dir=\"rtl\">פְּסִל׳</span>. Ib.; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to make</i> or <i>declare unfit; to reject</i>. <span class=\"citation\">Snh. 23ᵃ</span> <span dir=\"rtl\">בתר דפַסְלֵי להו וכ׳</span> after they (the parties) rejected them, shall they (the rejected judges) go and select another court? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">רחמנא פַסְלֵיה</span> it is the Law that declared him unfit. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כל כמיניה דפָסֵיל דייני</span> is it in his power to reject judges?; a. fr.—Part. pass. as ab. <span class=\"citation\">Targ. Y. II, Gen. XXII, 10</span>. <span class=\"citation\">Targ. Y. I Lev. VII, 18</span> (Y. II <a href=\"#\" data-headword=\"פָּסוּל\">פָּסוּל</a> h. form; h. text <span dir=\"rtl\">פגול</span>); a. e.—[<span class=\"citation\">Targ. Ps. XVIII, 27</span>, v. <a href=\"#\" data-headword=\"פְּסִילָא\">פְּסִילָא</a>.]—<span class=\"citation\">Keth. 61ᵇ</span> <span dir=\"rtl\">מאן דעביד הכי פ׳ למאכל וכ׳</span> he who does a thing like this is unfit to prepare food for the king. <span class=\"citation\">Ib. 105ᵇ</span> <span dir=\"rtl\">האי דיינא … פ׳ למידן דינא</span> (some ed. <span dir=\"rtl\">פסול</span>) a judge that is in the habit of borrowing (things from his neighbors) is unfit to judge cases. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פְּסִילְנָא לך לדינא</span> I am unfit to be a judge in thy case (because I have been offered a gift); a. fr.—V. <a href=\"#\" data-headword=\"פְּסוֹל\">פְּסוֹל</a>.</div><div class=\"sense\"><b>Ithpe. אִתְפְּסַל  אִתְפְּסֵיל</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"פְּסַק\">אִיפְּסִיל</a> </div><div class=\"sense\"><b>1)</b> <i>to be engraven</i>. <span class=\"citation\">Targ. Job XIX, 24</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be hewn out</i>. <span class=\"citation\">Targ. Is. LI, 1</span>.</div><div class=\"sense\"><b>—3)</b> <i>to be disqualified, unfit, rejected</i>. <span class=\"citation\">Targ. Ps. LXVIII, 16</span>. [<span class=\"citation\">Targ. Y. Num. VIII, 24</span> <span dir=\"rtl\">מוּפְסָלִין</span> h. <i>Hof.</i>]—Y. Kil. VII, 31ᵃ top [read:] <span dir=\"rtl\">א&quot;ל טבא היא ואִיפְסְלַת</span> he said to him, it is a good coin, whereas it had been cancelled. <span class=\"citation\">Men. 102ᵇ</span> <span dir=\"rtl\">לאִיפְּסוּלֵי דגופיה</span> (Ms. M. <span dir=\"rtl\">לפסולא</span>) to become unfit for itself (but not for making unclean); <span class=\"citation\">Pes. 20ᵃ</span> <span dir=\"rtl\">לאיפסולי גופיה</span>; a. fr.</div></div><div class=\"sense\"><b>Af. אַפְסֵל</b> <div class=\"sense\"><i>to make unfit</i>. <span class=\"citation\">Ḥull. 36ᵃ</span> <span dir=\"rtl\">לאַפְסוּלֵי גופיה</span> to cause the object itself to be forbidden (<span class=\"citation\">ib. 37ᵃ</span> <span dir=\"rtl\">לפסולא דגופיה</span>), v. supra.</div></div><div class=\"sense\"><b>Pa. פַּסֵּל</b> <div class=\"sense\"><i>to cut</i> (<i>stones</i>). <span class=\"citation\">Targ. II Chr. XXIV, 12</span> <span dir=\"rtl\">מְפַסְּלִין</span> stone-cutters.</div></div>","alt":[]},"23151":{"h":"פַּסָּל","r":"Q01327","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּסַל\">preced.</a>) <i>mattock</i>. <span class=\"citation\">Sifré Deut. 38</span>; <span class=\"citation\">Yalk. ib. 857</span> <span dir=\"rtl\">ארץ … אם אינו עמל בה בפ׳ וקורדום</span> the soil of Egypt cannot be planted, unless one first works it with mattock and axe. <span class=\"citation\">Ber. 57ᵇ</span>; <span class=\"citation\">B. Mets. 82ᵇ</span>, v. <a href=\"#\" data-headword=\"מָר\"><span dir=\"rtl\">מָרָא</span> II</a>.</div>","alt":[]},"23152":{"h":"פֶּסֶל","r":"Q01328","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"פַּסָּל\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>sculptured</i> or <i>carved image</i>. <span class=\"citation\">Midr. Till. to Ps. XVIII, 41</span> <span dir=\"rtl\">שהיה דגון פִּסְלוֹ וכ׳</span> ed. Bub. (oth. ed. <span dir=\"rtl\">אלוהו</span>) his idol Dagon was engraven on his heart. Sifra K’dosh. beg.; <span class=\"citation\">Yalk. Lev. 604</span>, v. <a href=\"#\" data-headword=\"פָּסַל\">פָּסַל</a>; Mekh. Mishp. s. 20. <span class=\"citation\">Snh. 103ᵇ</span> v. <a href=\"#\" data-headword=\"מִיכָה I\"><span dir=\"rtl\">מִיכָה</span> I</a>; a. e.—Pl. <span dir=\"rtl\">פְּסִילִים</span>, v. <a href=\"#\" data-headword=\"פָּסִיל\">פָּסִיל</a>.</div><div class=\"sense\"><b>—2)</b> <i>chip, lath</i>, contrad. to <span dir=\"rtl\">נסר</span>. <span class=\"citation\">Succ. 18ᵃ</span> <span dir=\"rtl\">נסר ופ׳ וכ׳</span> a board alternating with a lath (as the covering of a Succah). Tosef. ib. II, 3; <span class=\"citation\">Succ. 19ᵃ</span> <span dir=\"rtl\">פ׳ היוצא מן הסוכה</span> a lath roof prolonged beyond the walls of the Succah; expl. ib. <span dir=\"rtl\">קנים היוצאים וכ׳</span> reeds or staves which &amp;c.—Pl. <span dir=\"rtl\">פְּסָלִים</span>. Ib. 18ᵃ</div>","alt":[]},"23153":{"h":"פִּסְלָא","r":"Q01329","html":"<div class=\"sense\"><b>1)</b> <i>image</i>. <span class=\"citation\">Targ. Ps. XCVII, 7</span>. <span class=\"citation\">Targ. Cant. II, 15</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>lath, lintel</i>, esp. <i>a lintel placed across a street</i> or <i>a court</i>. <span class=\"citation\">Sabb. 80ᵃ</span>; <span class=\"citation\">B. Bath. 56ᵃ</span>. <span class=\"citation\">Gitt. 77ᵇ</span> <span dir=\"rtl\">נפל בפ׳</span> (the letter of divorce) fell on a cross-board (in the court).</div>","alt":["פִּי׳"]},"23154":{"h":"פַּסְלוּת","r":"Q01330","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"פָּסוּל\">פָּסוּל</a>) <i>condition of unfitness, disqualification</i>, opp. <a href=\"#\" data-headword=\"כַּשְׁרוּת\">כשרות</a>. <span class=\"citation\">B. Bath. 128ᵃ</span> <span dir=\"rtl\">כל שתחילתו או סופו בפ׳ וכ׳</span> testimony for which the witness was disqualified at the beginning (when the fact to be attested occurred), or is disqualified at the end (when the evidence is taken) is illegal. <span class=\"citation\">Koh. R. to IX, 7</span> <span dir=\"rtl\">שמא פ׳ היה בבני</span> there was perhaps a defect in my son which made him rejectable as an offering.</div>","alt":[]},"23155":{"h":"פְּסִלְיָא","r":"Q01331","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסִילְיָא\">פְּסִילְיָא</a></div>","alt":[]},"23156":{"h":"פסליא","r":"Q01332","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Dem. I, 9</span> ed. Zuck., v. <a href=\"#\" data-headword=\"פַּסְלְקָאוֹת\">פַּסְלְקָאוֹת</a></div>","alt":[]},"23157":{"h":"פסליון","r":"Q01333","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Ps. 650</span>, v. <a href=\"#\" data-headword=\"פָּפִילְיוֹן\">פָּפִילְיוֹן</a></div>","alt":[]},"23158":{"h":"פסלין","r":"Q01334","html":"<div class=\"sense\">, prob. to be read: <a href=\"#\" data-headword=\"פִּסְיוֹן\">פִּסְלוֹן</a> m. (<a href=\"#\" data-headword=\"פָּסַל\">פָּסַל</a>) <i>a rough stone</i>. <span class=\"citation\">Tosef. Kel. B. Mets. I, 12</span> <span dir=\"rtl\">פ׳ שהוא כותב עליו וכ׳</span> ed. Zuck. (oth. ed. <a href=\"#\" data-headword=\"פוסלין\">פוסלין</a>, read <span dir=\"rtl\">פיסלון</span>) a rough stone on which a charm is written (v. Sm. Ant. s. v. Amuletum).</div>","alt":[]},"23159":{"h":"*פַּסְלָן","r":"Q01335","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Valley of Paslan</i>, near the valley of Jezreel. <span class=\"citation\">Gen. R. s. 98</span>.</div>","alt":["בִּקְעַת פַּ׳"]},"23160":{"h":"פַּסְלְקָאוֹת","r":"Q01336","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (βασίλικα, sub. κάρυα, basilicæ, sub. nuces) <i>basilicæ</i>, the best kind of <i>nuts</i>. <span class=\"citation\">Tosef. Dem. I, 9</span> [read:] <span dir=\"rtl\">האגוזין ודורמסקיות ופ׳</span> (Var. <span dir=\"rtl\">והפסדקאות</span>; <span dir=\"rtl\">ופסליא</span> ed. Zuck., Var. <span dir=\"rtl\">ופסיליה</span>, standing for βασιλεια, a dittography of our w.) nuts, plums, and walnuts.</div>","alt":[]},"23161":{"h":"*פְּסַנְטוֹר","r":"Q01337","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (corrupt. of obsonator, οψωνάτωρ) <i>caterer, purveyor</i>. <span class=\"citation\">Koh. R. to I, 3</span> פְּסַנְטוֹרָךְ אנא ולית את מטעים וכ׳ I am thy caterer, and thou wilt not let me taste thy dish, that I may know what it may need?; <span class=\"citation\">Lev. R. s. 28</span> Ar. (ed., a. <span class=\"citation\">Yalk. Jer. 276</span>, a. e. <span dir=\"rtl\">מגרסך</span>, v. <a href=\"#\" data-headword=\"מגִירוֹס\">מָגֵירוֹס</a>).</div>","alt":[]},"23162":{"h":"*פַּסְנִין","r":"Q01338","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (?) <i>Pasnin</i>. <span class=\"citation\">Tosef. Ohol. XVIII, 2</span>.</div>","alt":[]},"23163":{"h":"פָּסַס","r":"Q01339","html":"<div class=\"sense\"><b>1)</b>  (b. h.) (b. h.) <i>to be cut off, be gone</i>. Tanḥ. Haăz. 7 (play on <span dir=\"rtl\">נח̇ב̇י בן ופ̇ס̇י</span>, <span class=\"citation\">Num. XIII, 14</span>) <span dir=\"rtl\">החב̇יא האמת ופַ֗סָּ֗ה האמונה מפיו</span> he hid the truth, and faith was gone from his mouth.</div><div class=\"sense\"><b>—2)</b> <i>to cut into stripes, divide</i>, v. <a href=\"#\" data-headword=\"פַּס\">פַּס</a>.</div><div class=\"sense\"><b>—3)</b> <i>to distribute</i> (<i>with the shovel</i>, v. <a href=\"#\" data-headword=\"פַּס\">פַּס</a> ch. 4). <span class=\"citation\">Tosef. Ukts. I, 5</span> <span dir=\"rtl\">תבואה שפְּסָסָהּ בגורן</span> (Var. ed. Zuck. <span dir=\"rtl\">שנִפְסְסָה</span>) grain which one distributed in the barn (forming separate piles). <span class=\"citation\">Ukts. I, 5</span> שפְּסָסָן Ar. s. v. <a href=\"#\" data-headword=\"פִּסְפֵּס I\">פספס</a> (v. <a href=\"#\" data-headword=\"בָּסַס\">בָּסַס</a>).—<span class=\"citation\">Gen. R. s. 31</span> [read:] <span dir=\"rtl\">והיה פוֹסְסָן מן הצד</span> and he shovelled them (the excrements) sideways (out into the water); <span class=\"citation\">Yalk. ib. 54</span> <span dir=\"rtl\">והיה פותחין</span> (corr. acc.), v. <a href=\"#\" data-headword=\"קָטָרַקְטִין\">קָטָרַקְטִין</a>.</div><div class=\"sense\"><b>Nif. נִפְסַס</b> <div class=\"sense\"><i>to be spread, shovelled</i>, v. supra.</div></div><div class=\"sense\"><b>Hif. הֵפֵיס  הֵיפֵס</b> <div class=\"sense\"><b>1)</b> <i>to distribute, spread</i>; <span dir=\"rtl\">ה׳ מורסא</span> <i>to distribute an ulcer by manipulation, to pass over with the hand</i> <a href=\"#\" data-headword=\"פַּס\">(פַּס</a>). <span class=\"citation\">Eduy. II, 5</span>; <span class=\"citation\">Tosef. ib. I, 8</span> <span dir=\"rtl\">המֵיפֵיס מורסא וכ׳</span> he who manipulates an abscess on the Sabbath, if for the purpose (of peeling or) of making a head to it as the physicians do &amp;c.; <span class=\"citation\">Sabb. 107ᵇ</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"פִּיס\">פִּיס</a>) <i>to break, weaken</i>. <span class=\"citation\">Pes. 107ᵃ</span>, v. <a href=\"#\" data-headword=\"פִּיס\">פִּיס</a>.</div></div>","alt":[]},"23164":{"h":"פְּסַס","r":"Q01340","html":"<div class=\"sense\">, <i>to distribute</i>. <span class=\"citation\">Targ. Hos. IV, 8</span> <span dir=\"rtl\">כהניא פַסּוּ וכ׳</span> the priests distribute (the sacrifices among themselves) &amp;c.—<span class=\"citation\">Gen. R. s. 17</span> אנן פַּסִּין לה פירקא וכ׳ Ar. (read <a href=\"#\" data-headword=\"פּוּרַן\">פורנא</a>) we shall apportion (among ourselves, pay each his share towards) her dowry, and you divorce her (ed. <span dir=\"rtl\">יהבינן לה פורנא</span>); <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">אנן פסקינן</span>, v. <a href=\"#\" data-headword=\"פְּסַק\">פְּסַק</a>).</div><div class=\"sense\"><b>Af. אַפֵּיס</b> <div class=\"sense\"><i>to break, weaken; to desecrate</i>, v. <a href=\"#\" data-headword=\"פִּיס\">פִּיס</a>.</div></div><div class=\"sense\"><b>Ithpa. אִתַּפֵּס</b> <div class=\"sense\"><i>to be weakened, be degraded</i>. <span class=\"citation\">Targ. Job XV, 20</span>, v. <a href=\"#\" data-headword=\"פִּיס\">פִּיס</a>, a. <a href=\"#\" data-headword=\"תְּפַס II\"><span dir=\"rtl\">תְּפַס</span> II</a>.</div></div>","alt":[]},"23165":{"h":"פָּסַע","r":"Q01341","html":"<div class=\"sense\"> [<i>to spread the feet</i>,] <i>to step out, walk</i>. <span class=\"citation\">Meg. 27ᵇ</span> לא פָסַעְתִּי על ראשי וכ׳ I never strode over the heads of the holy people (never forced my way through the students seated on the floor to reach my chair); <span class=\"citation\">Snh. 7ᵇ</span> <span dir=\"rtl\">מניין לדיין שלא יִפְסַע וכ׳</span> where is it intimated that a judge must not force his way &amp;c. (Answ. by ref. to <span class=\"citation\">Ex. XX, 26</span>, sq.); <span class=\"citation\">Yeb. 105ᵇ</span> <span dir=\"rtl\">מי שצריך … יִפְסַע וכ׳</span> he of whom the holy people are in need, may step over the heads &amp;c. <span class=\"citation\">Sot. 13ᵇ</span> <span dir=\"rtl\">שתים … ופְסָעָן משה בפסיעה אחת</span> twelve steps were there, and Moses passed over them with one step. <span class=\"citation\">Gen. R. s. 99</span> (play on <span dir=\"rtl\">פ̇ח̇ז</span>, <span class=\"citation\">Gen. XLIX, 4</span>) <span dir=\"rtl\">פָּסַעְתָּ על דת ח̇ללת … ז̇ר</span> thou didst overstep (transgress) the law, desecrate thy birthright (priesthood), and hast become a commoner. Mekh. Bo 7 (ref. to <span class=\"citation\">Ex. XII, 13</span>) <span dir=\"rtl\">א&quot;ת ופסחתי אלא וּפָסַעְתִּי וכ׳</span> read not, and I will pass, but I will step over (leap, skip), the Lord skipped over &amp;c.; a. e.</div><div class=\"sense\"><b>Pi. פִּסֵּעַ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"פְּסַס\">same</a>. Y. Kil. VI, 30ᶜ <span dir=\"rtl\">לפַסֵּעַ</span>, v. <a href=\"#\" data-headword=\"פֵּיפוּר\">פֵּיפוּר</a>. Yeb. l. c. <span dir=\"rtl\">מי הוא זה שמְפַסֵּעַ על ראשי וכ׳</span> who is he that forces his way over the heads &amp;c.?, v. supra; a. e.</div></div><div class=\"sense\"><b>Hif. הִפְסִיעַ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"פְּסַס\">same</a>. <span class=\"citation\">Hor. 13ᵇ</span> <span dir=\"rtl\">בזמן שרבים … מַפְסִיעִין על וכ׳</span> when the public need their services, they may force their way &amp;c. <span class=\"citation\">Taan. 10ᵇ</span> <span dir=\"rtl\">אל תַּפְסִיעוּ פסיעה גסה וכ׳</span> never march with hasty steps, and bring the sun into town (enter before sunset); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to make cross-stitches</i>. <span class=\"citation\">M. Kat. 10ᵃ</span>; Y. ib. I, 80ᵈ bot., v. <a href=\"#\" data-headword=\"כָּלַב\">כָּלַב</a>.</div></div>","alt":[]},"23166":{"h":"פְּסַע","r":"Q01342","html":"<div class=\"sense\">, <i>to walk with legs wide apart, waddle</i>. <span class=\"citation\">Targ. II Sam. XX, 8</span> (h. text <span dir=\"rtl\">ותפל</span>!), v. <a href=\"#\" data-headword=\"פְּסִיעַ\">פְּסִיעַ</a>.—<span class=\"citation\">Pes. 111ᵇ</span> <span dir=\"rtl\">האי מאן דפ׳ אדיקלא</span> (Ms. M. <span dir=\"rtl\">דמִיפְּסַע</span> <i>Ithpe.</i>) he who steps over a (young) date palm.—V. <a href=\"#\" data-headword=\"פְּצֵי\">פְּצֵי</a>.</div><div class=\"sense\"><b>Pa. פַּסַּע</b> <div class=\"sense\"><i>to step heavily, pompously</i>. <span class=\"citation\">Yeb. 105ᵇ</span> <span dir=\"rtl\">אגב יוקריה הוה מְפַסַּע ואזיל</span> on account of his heavy build he stepped in and walked (through the assembled students, making the impression of haughtiness), v. preced.—Y. Ber. II, 4ᶜ bot. <span dir=\"rtl\">והוה … מְפַסַּע וכ׳</span> and R. J. stepped upon the graves.</div></div>","alt":[]},"23167":{"h":"פִּסְעָא","r":"Q01343","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיסְעָא\">פִּיסְעָא</a></div>","alt":[]},"23168":{"h":"פְּסַף","r":"Q01344","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"פְּסַף\">פַּסֵּף</a>, v. <a href=\"#\" data-headword=\"פִּסְפֵּס II\"><span dir=\"rtl\">פַּסְפֵּס</span> II</a>.</div>","alt":[]},"23169":{"h":"פִּסְפֵּס I","r":"Q01345","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"פָּסַס\">פָּסַס</a>) <i>to separate, part, tear</i> (<i>into stripes, shreds</i>). <span class=\"citation\">Midr. Till. to Ps. VII, 3</span> <span dir=\"rtl\">מה האריה … ומְפַסְפְּסוֹ כך … לפַסְפְּסֵנִי</span> (Var. in Ms. <span dir=\"rtl\">מפצפצ׳</span>, v. ed. Bub. note) as the lion sits over his prey and tears it, so Doeg and Ahithophel sit over me to tear me; <span class=\"citation\">Yalk. Ps. 637</span>; <span class=\"citation\">Midr. Till. to Ps. XXII, 17</span>. <span class=\"citation\">Sabb. XXIV, 2</span> <span dir=\"rtl\">מְפַסְפְּסִים את הכיפים</span> you may (untie and) spread the bundles (of fodder), v. <a href=\"#\" data-headword=\"כִּיפָּה\">כִּיפָּה</a>. <span class=\"citation\">Ib. 155ᵃ</span> <span dir=\"rtl\">לא לפַסְפֵּס ולא להתיר</span> neither to spread nor even to untie. <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">IV), 18</span> <span dir=\"rtl\">מפספסין את הכפין ובלבד וכ׳</span> (Var. <span dir=\"rtl\">ומפרכסין</span>, incorr.) you may part the bundles, provided you do not pluck them apart. <span class=\"citation\">Naz. VI, 3</span> <span dir=\"rtl\">נזיר חופף ומְפַסְפֵּס</span> the Nazarite may wash his hair (v. <a href=\"#\" data-headword=\"חָפַף I\">חָפַף</a>) and part it (with his fingers), but must not use a comb. Y. ib. IV, 55ᵇ top <span dir=\"rtl\">מפספסין בקליקין</span> you may part the tangles in the Nazarite’s hair; <span class=\"citation\">Y. Bets. IV, 62ᶜ</span>. <span class=\"citation\">Y. Shek. III, 47ᶜ</span> <span dir=\"rtl\">הגיזברין היו מפספסין בקילקין</span> the Temple treasurers had the entangled hair (of those engaged in counting) straightened (to avoid the suspicion that they had coins concealed); a. e.</div>","alt":[]},"23170":{"h":"פַּסְפֵּס","r":"Q01346","html":"<div class=\"sense\"> <span class=\"citation\">Sabb. 155ᵃ</span> <span dir=\"rtl\">מתירין … פַּסְפּוּסֵי לא</span> you may untie …, but not spread; <span dir=\"rtl\">פספוסי נמי מְפַסְפְּסִינָן</span> we may also spread.</div>","alt":[]},"23171":{"h":"פִּסְפֵּס II","r":"Q01347","html":"<div class=\"sense\"> (transpos. of <a href=\"#\" data-headword=\"סִפְסֵף\">סִפְסֵף</a>; cmp. <a href=\"#\" data-headword=\"גִּעְגֵּעַ\">גִּעְגֵּעַ</a>) <i>to cut the ends, trim by singeing</i>. <span class=\"citation\">Tosef. Pes. V, 10</span> <span dir=\"rtl\">אין … אבל מְפַסְפְּסִין אותן באור</span> you dare not scald the head and feet (of the Passover lamb) …, but you may trim them by holding them over the fire; <span class=\"citation\">Tosef. Bets. III, 19</span> (Var. <span dir=\"rtl\">מספסין</span>; <span class=\"citation\">Bets. 34ᵃ</span> <span dir=\"rtl\">מהבהבין</span>). Y. ib. IV, 62ᶜ bot. <span dir=\"rtl\">אין מפספסין</span> quot. in Levy (ed. Krot. <span dir=\"rtl\">מספספ׳</span>), v. <a href=\"#\" data-headword=\"סִפְסֵף\">סִפְסֵף</a>.</div>","alt":[]},"23172":{"h":"פַּסְפֵּס ²","r":"Q01348","html":"<div class=\"sense\"> ch. (apocop. <a href=\"#\" data-headword=\"פְּסַף\">פַּסֵּף</a>; cmp. <a href=\"#\" data-headword=\"כֶּסֶךְ\">כֶּסֶךְ</a> a. <a href=\"#\" data-headword=\"כַּסְכַּס\">כַּסְכַּס</a>) same. Y. Sabb. II, 5ᵃ (expl. <span dir=\"rtl\">מחרכין</span>) <span dir=\"rtl\">מְפַסְפְּסִין לין</span> (ed. Krot. <span dir=\"rtl\">מְפַסְּפִין</span>) they trim them (the wicks, by burning).</div>","alt":[]},"23173":{"h":"פִּסְפָּס","r":"Q01349","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסִיפָּס\">פְּסִיפָּס</a></div>","alt":[]},"23174":{"h":"פָּסַק","r":"Q01350","html":"<div class=\"sense\"> [<i>to separate, part, distribute</i>,] </div><div class=\"sense\"><b>1)</b> <i>to divide, split, interrupt</i>. <span class=\"citation\">Taan. 27ᵇ</span>; <span class=\"citation\">Meg. 22ᵃ</span> <span dir=\"rtl\">פּוֹסֵק</span> the reader divides (one verse), i.e. the first reads two verses and a half, leaving the other half to be read by his successor. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא התיר לי לִפְסוֹק וכ׳</span> he permitted me to cut a verse in two only in teaching the school children. <span class=\"citation\">Ib. 31ᵇ</span> <span dir=\"rtl\">במשנה תורה פוסק</span> the chapter in Deuteronomy containing the curses (<span class=\"citation\">Deut. XXVIII, 15—69</span>) may be divided (to be read by two or more); a. fr.—[<span class=\"citation\">Gen. R. s. 10</span> <span dir=\"rtl\">כיון שפסקה</span>; <span class=\"citation\">Yalk. ib. 16</span> <span dir=\"rtl\">שפוסקה</span>, v. <a href=\"#\" data-headword=\"פָּתַק\">פָּתַק</a>.]—Part. pass. <a href=\"#\" data-headword=\"פָּסוּק\">פָּסוּק</a>; f. <a href=\"#\" data-headword=\"פְּסוּקָה\">פְּסוּקָה</a>. <span class=\"citation\">Ḥull. III, 3</span> <span dir=\"rtl\">פְּסוּקַת הגרגרת</span>, v. <a href=\"#\" data-headword=\"גַּרְגֶּרֶת\">גַּרְגֶּרֶת</a>.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"פָּסוּק\">פָּסוּק</a>) <i>to recite a verse</i>. <span class=\"citation\">Ḥag. 15ᵃ</span>, sq. <span dir=\"rtl\">פְּסוֹק לי פְּסוּקְךָ</span> (interch. with Chald. <span dir=\"rtl\">פסוק לי פסוקיך</span>) recite to me thy Bible verse (recently learned).</div><div class=\"sense\"><b>—3)</b>  (cmp. <a href=\"#\" data-headword=\"חָתַךְ\">חָתַךְ</a>, <a href=\"#\" data-headword=\"גָּזַר\">גָּזַר</a>) <i>to apportion, assign; to provide; to promise, agree</i>. <span class=\"citation\">Keth. 65ᵃ</span> <span dir=\"rtl\">אין פּוֹסְקִין יינות לאשה</span> in decreeing alimentation for a woman we do not provide for wine. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כך תִּפְסְקוּ לבנותיכם</span> so much (and no more) may ye grant to your daughters. <span class=\"citation\">Ib. 107ᵃ</span> <span dir=\"rtl\">פוסקין מזונות לאשת איש</span> the court assigns alimentation (from the estate) to a deserted wife. <span class=\"citation\">Ib. V, 8</span> <span dir=\"rtl\">לא פ׳ … אלא וכ׳</span> only R. Y. decreed barley as a part of alimentation, because he lived near Edom. Ib. <span dir=\"rtl\">פוסק לעומתן וכ׳</span> he must give her &amp;c., v. <a href=\"#\" data-headword=\"עוּמָּה\">עוּמָּה</a>. Ib. VI, 2 <span dir=\"rtl\">הפוסק מעות לחתנו</span> if a man agrees to pay a certain amount to his intended son-in-law (on the date of marriage). Ib. 3 <span dir=\"rtl\">פָּסְקָה להכניס … הוא פוסק וכ׳</span> if she promises to bring to him one thousand Denars, he must assign to her (as settlement in the K’thubah) fifteen Manehs. Tosef. ib. XIII (XII), 1 <span dir=\"rtl\">אם פָּסְקוּ לה … מה שפסקו פסקו</span> if the court has granted her (alimentation), what they have granted, is granted. Ib. <span dir=\"rtl\">פסקה היא לעצמה</span> (not <span dir=\"rtl\">על עצמה</span>) if she herself has promised (to bring her husband a certain sum, and now her father refuses to give it). Ib. <span dir=\"rtl\">אבה פ׳ עלי וכ׳</span> my father has promised for me; what can I do (if he retracts)?; <span class=\"citation\">Keth. XIII, 5</span>. Y. Kidd. IV, 65ᶜ top <span dir=\"rtl\">פּוֹסְקֵי צדקה ברבים וכ׳</span> those who subscribe to a charity in public and refuse to pay; <span class=\"citation\">Taan. 8ᵇ</span>; a. v. fr.</div><div class=\"sense\"><b>—4)</b> <i>to fix a price; to buy on time</i>. <span class=\"citation\">Gitt. 58ᵃ</span> אפדנו בכל ממון שפוסקין עליו I will redeem him for any price that they may set on him. <span class=\"citation\">B. Mets. V, 7</span> <span dir=\"rtl\">אין פוסקין … עד שיצא השער</span> you dare not fix a price on crops (buy on time), until the market price has been published. Ib. <span dir=\"rtl\">יצא השער פוסקין ואע&quot;פ שאין לזה יש לזה</span> (missing in Y. ed.) when the market price is out, you may buy, for although he (the seller) has no goods as yet, others have. Ib. <span dir=\"rtl\">פוסק עמו על הגדיש</span>, v. <a href=\"#\" data-headword=\"גָּדִישׁ\">גָּדִישׁ</a>; a. v. fr.</div><div class=\"sense\"><b>—5)</b>  <span dir=\"rtl\">פ׳ דברים</span> [<i>to split words</i>,] <i>to argue</i>. <span class=\"citation\">Snh. 44ᵇ</span> פיסקון שפוסק דברים כלפי מעלה Gabriel is surnamed Pisḳon, because he argues with the Lord.</div><div class=\"sense\"><b>—6)</b>  (neut. verb) <i>to be cut off; to cease, be stopped</i>. <span class=\"citation\">Sot. IX, 9</span> <span dir=\"rtl\">משרבו … פסקו המים המרים … הפסיקן</span> when the faithless men became frequent, the application of the waters of jealousy ceased, and it was R. J. ben Z. that abolished them. <span class=\"citation\">Ib. 12</span> <span dir=\"rtl\">פסקו אנשי אמונה</span> the men of faith ceased to exist. Tanḥ. Sh’moth 16 <span dir=\"rtl\">אין אותה מצוה פוֹסֶקֶת מביתו</span> that good deed shall never cease from (being practiced in) his house. <span class=\"citation\">Gen. R. s. 52</span> <span dir=\"rtl\">פסקו העוברים והשבים</span> travellers ceased to pass by; a. v. fr.</div><div class=\"sense\"><b>Nif. נִפְסַק</b> <div class=\"sense\"><i>to be split, cut in two, broken</i>. <span class=\"citation\">Tosef. B. Kam. XI, 15</span>; <span class=\"citation\">B. Kam. 119ᵇ</span> <span dir=\"rtl\">הנ׳ במגירה</span> chips at planing, v. <a href=\"#\" data-headword=\"גָּרַר I\"><span dir=\"rtl\">גָּרַר</span> I</a>. <span class=\"citation\">Ḥull. III, 1</span> <span dir=\"rtl\">נשברה השדרה ונ׳ החוט שלה</span> if the spinal column is broken and the spinal cord severed. <span class=\"citation\">Sabb. 112ᵃ</span> <span dir=\"rtl\">סנדל שנִפְסְקוּ שתי אזניו</span> a sandal, both ears (loops) of which are torn off; <span class=\"citation\">Tosef. Kel. B. Bath. IV, 5</span> <span dir=\"rtl\">שנִתְפַּסְּקוּ</span>; <span class=\"citation\">Kel. XXVI, 4</span>; a. fr.—[<span class=\"citation\">Tosef. Mikv. III, 5</span>, sq. <span dir=\"rtl\">ונפסקו</span>, v. <a href=\"#\" data-headword=\"פָּתַק\">פָּתַק</a>.]</div></div><div class=\"sense\"><b>Hif. הִפְסִיק</b> <div class=\"sense\"><b>1)</b> <i>to separate, sever connection; to form a partition</i>. <span class=\"citation\">Sot. 38ᵇ</span> <span dir=\"rtl\">אפי׳ מחיצה … אינה מַפְסֶקֶת בין וכ׳</span> not even an iron wall forms a partition between Israel and his father in heaven (worshippers form a congregation even if separated by a partition); <span class=\"citation\">Pes. 85ᵇ</span>. <span class=\"citation\">Peah. I, 2</span> <span dir=\"rtl\">ואלו מַפְסִיקִין לפאה</span> the following things form a division of fields with regard to Peah: a brook &amp;c. <span class=\"citation\">Ab. Zar. 52ᵃ</span> <span dir=\"rtl\">את ה׳ הענין</span> the word <i>eth</i> (before <i>ĕlohehem</i> <span class=\"citation\">Deut. XII, 2</span>) divides the subject (so as not to allow an analogy between idolatrous utensils and the idols themselves), v. <a href=\"#\" data-headword=\"פְּסַק\">next w.</a>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to interrupt; to cause to cease; to leave off; to pause</i>. <span class=\"citation\">Ber. II, 2</span> <span dir=\"rtl\">בין ויאמר לאמת ויציב לא יַפְסִיק</span> between the last portion of the Sh’mʿa (<span class=\"citation\">Num. XV, 37-41</span>) and ‘Ĕmeth V’yatsib’ one must not pause (interrupt the prayer to greet a person &amp;c.). Ib. 14ᵃ <span dir=\"rtl\">במגילה מהו שיפסיק</span> may one interrupt one’s self during the reading of the M’gillah? [Ib. also <span dir=\"rtl\">פּוֹסֵק</span> <i>Kal</i>.] Ib. V, 1. <span class=\"citation\">Ex. R. s. 2</span> <span dir=\"rtl\">עם כל הנביאים ה׳ מלדבר … לא ה׳ מימיו</span> with all other prophets the Lord ceased from speaking at times, but with Moses he never ceased. <span class=\"citation\">Taan. 30ᵃ</span> <span dir=\"rtl\">סעודה המַפְסִיק בה</span> the meal with which one ceases (the last meal before beginning to fast, called <span dir=\"rtl\">סעודה המַפְסֶקֶת</span>). Y. Nidd. I, 49ᶜ <span dir=\"rtl\">והִפְסִיקָה שלש עונות</span> and ceased (to have menstruation) for three periods. <span class=\"citation\">Meg. III, 6</span> <span dir=\"rtl\">אין מַפְסִיקִין בקללות וכ׳</span> in reading the curses (<span class=\"citation\">Lev. XXVI, 14-44</span>; <span class=\"citation\">Deut. XXVIII, 15-69</span>) you must not break off, but one person must read the whole &amp;c. Ib. 31ᵇ <span dir=\"rtl\">מקום שמפסיקין בשבת וכ׳</span> where they leave off reading on Sabbath morning, there they continue in the afternoon &amp;c. <span class=\"citation\">Sot. IX, 9</span>, v. supra. <span class=\"citation\">Gen. R. s. 52</span>, beg. <span dir=\"rtl\">מה אני מפסיק צדקה מביתי</span> shall I allow charity to cease in my house (to fall into desuetude from want of opportunity)?; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to cut sprays off, trim</i>, v. <a href=\"#\" data-headword=\"פָּסַג\">פָּסַג</a>.</div><div class=\"sense\"><b>—4)</b> <i>to dam</i>. <span class=\"citation\">Tosef. Par. V</span> (<span class=\"citation\">IV), 9</span> <span dir=\"rtl\">מפסיק ומנגב</span> he makes a dam (cuts off the influx) and lays the cavity dry.</div></div><div class=\"sense\"><b>Pi. פִּיסֵּק</b> <div class=\"sense\"><b>1)</b> <i>to trim</i>. <span class=\"citation\">Tosef. B. Kam. XI, 18</span>, v. <a href=\"#\" data-headword=\"פָּסַג\">פָּסַג</a>.</div><div class=\"sense\"><b>—2)</b> <i>to interrupt</i>.—Part. pass. <span dir=\"rtl\">מְפוּסָּק</span>; pl. <span dir=\"rtl\">מְפוּסָּקִין</span>. Y. Pes. X, 37ᶜ; Y. Sabb. VIII, beg. 11ᵃ <span dir=\"rtl\">מהו לשתותן מפ׳</span> how about drinking them (the four cups of the Passover evening) in pauses (sipping)?, v. <a href=\"#\" data-headword=\"פִּיסָּק\">פִּיסָּק</a>.</div><div class=\"sense\"><b>—3)</b> <i>to cut down, ruin; to cut to pieces</i>. Pesik. Naḥ., p. 128ᵃ <span dir=\"rtl\">קיצצוהו ופִיסְּקוּהוּ</span> they cut it down and ruined it (the vineyard). <span class=\"citation\">Lam. R. to IV, 15</span> <span dir=\"rtl\">והיתה … עליהן ומְפַסַּקְתָּן</span> the carriage passed over them and dismembered them; Pesik. Vattom., p. 133ᵇ <span dir=\"rtl\">ומפסקתה</span> (corr. acc.); <span class=\"citation\">Yalk. Is. 266</span> <span dir=\"rtl\">והיתה … עליה ומְפַסַּקְתָּהּ</span>; a. e.</div></div><div class=\"sense\"><b>Hithpa. הִתְפַּסֵּק</b> </div><div class=\"sense\"><b>Nithpa. נִתְפַּסֵּק</b> <div class=\"sense\"><b>1)</b> <i>to be severed</i>. <span class=\"citation\">Tosef. Kel. B. Bath. IV, 5</span>, v. supra.—</div><div class=\"sense\"><b>*2)</b>  (sub. <span dir=\"rtl\">בעינים</span>, cmp. <a href=\"#\" data-headword=\"קְרַץ I\">קרץ</a>, <span class=\"citation\">Prov. X, 10</span>; <span class=\"citation\">VI, 13</span>) <i>to blink</i>. <span class=\"citation\">Deut. R. s. 5</span> <span dir=\"rtl\">עשה עצמו מִתְפַּסֵּק</span> he pretended to be blinking (Y. Sot. I, 16ᵈ bot., a. e. <span dir=\"rtl\">עבד גרמיה חשש בעייניה</span>).</div></div>","alt":[]},"23175":{"h":"פְּסַק","r":"Q01351","html":"<div class=\"sense\"><b>1)</b> <i>to cut, split, sever</i>. <span class=\"citation\">Targ. Jud. XVI, 9</span>. <span class=\"citation\">Targ. II Sam. X, 4</span>; <span class=\"citation\">I Chr. XIX, 4</span>; a. fr.—Part. pass. <a href=\"#\" data-headword=\"פְּסֵיק\">פָּסִיק</a>, <a href=\"#\" data-headword=\"פְּסֵיק\">פְּסִיק</a>. <span class=\"citation\">Targ. O. Deut. XXIII, 2</span> (h. text <span dir=\"rtl\">פצוע דכה</span>); Y. ib. <span dir=\"rtl\">פ׳ גידא</span> (h. text. <span dir=\"rtl\">כרות שפכה</span>). <span class=\"citation\">Targ. O. Lev. XXII, 22</span> (h. text <a href=\"#\" data-headword=\"חָרוּץ\">חרוץ</a>).—<span class=\"citation\">Ḥull. 8ᵇ</span>, v. <a href=\"#\" data-headword=\"גַּוָּוזָא I\"><span dir=\"rtl\">גַּוָּוזָא</span> I</a>. <span class=\"citation\">B. Bath. 21ᵇ</span> <span dir=\"rtl\">קא פַסְקַת וכ׳</span> thou cuttest off (interferest with), v. <a href=\"#\" data-headword=\"חַיּוּתָא\">חַיּוּתָא</a>. <span class=\"citation\">Lev. R. s. 32</span>, end <span dir=\"rtl\">פסקת חייוי דהאי גברא</span> thou cuttest off (shortenest) this man’s (my) life (by divulging my spurious descent); a. fr.—פסיק רישיה ולא ימות ‘let his head be cut off, but let him not die’, a dialectic term for <i>an unavoidable result of an act</i>. <span class=\"citation\">Sabb. 75ᵃ</span> מודה ר&quot;ש בפ׳ ר׳ וכ׳ R. S. (who ordinarily permits, on the Sabbath, an act which may have as a result a violation of the Sabbath law, if the latter is not intended) admits that such an act is forbidden, if the result is inevitable.</div><div class=\"sense\"><b>—2)</b> <i>to separate, divide</i>. <span class=\"citation\">Targ. Hos. II, 8</span> (ed. Lag. <i>Af.</i>).—<span class=\"citation\">Pes. 111ᵃ</span> <span dir=\"rtl\">פַּסְקִינְהוּ רשות הרבים</span> (Rashb. <span dir=\"rtl\">פְּסַקְתִּינְהוּ</span>) the public road divides them (the two palms); a. e.—<span class=\"citation\">Meg. 2ᵇ</span>; <span class=\"citation\">B. Kam. 65ᵇ</span>, v. infra <i>Af.</i></div><div class=\"sense\"><b>—3)</b> <i>to be interrupted; to cease</i>. <span class=\"citation\">Targ. Y. Gen. XLIV, 12</span> (h. text <a href=\"#\" data-headword=\"כלי\">כִּלָּה</a>). Targ. II Esth. III, 7. <span class=\"citation\">Targ. Deut. V, 19</span>; a. fr.—<span class=\"citation\">Lev. R. s. 31</span>; <span class=\"citation\">Midr. Till. to Ps. XIX</span>; <span class=\"citation\">Yalk. ib. 673</span> (expl. <span dir=\"rtl\">לא נעדר</span>, <span class=\"citation\">Zeph. III, 5</span>) <span dir=\"rtl\">לא פַסְקִין</span> they never fail. <span class=\"citation\">M. Kat. 4ᵃ</span> <span dir=\"rtl\">מיא דלא פּסְקֵי</span> water which never fails. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">עבידא דפַסְקָא</span> it often fails. <span class=\"citation\">Ib. 18ᵇ</span> <span dir=\"rtl\">קלא דלא פָסֵיק</span> a continuous rumor; <span dir=\"rtl\">וכמה קלא דלא פ׳</span> how long must a rumor last to be called a continuous rumor? Ib. <span dir=\"rtl\">דלא פ׳ ביני ביני</span> if it has not ceased at intervals. <span class=\"citation\">Gitt. 69ᵃ</span> <span dir=\"rtl\">כי היכי דפסקי … לִיפְסוֹק וכ׳</span> as this water ceases to run, so may the blood of—stop flowing. <span class=\"citation\">Sabb. 30ᵇ</span> <span dir=\"rtl\">לא פ׳ פומיה</span>, v. <a href=\"#\" data-headword=\"גִּירְסָא I\"><span dir=\"rtl\">גִּירְסָא</span> I</a>; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to apportion, assign, bargain, agree, subscribe</i>. <span class=\"citation\">Y. Hor. III, 48ᵃ</span> bot. <span dir=\"rtl\">הוה חמי … פ׳ והוא פסיק לקיבליה</span> he waited to see how much the whole assembly subscribed, and he subscribed an amount equal to the entire subscription; <span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">כד הוון פַּסְקִין וכ׳</span> when all people had subscribed, he &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פ׳ חד ליטרא וכ׳</span> subscribed one pound of gold. <span class=\"citation\">Keth. 65ᵃ</span> <span dir=\"rtl\">פְּסוֹק לי מזוני</span> give me an order for my food; <span dir=\"rtl\">פ׳ לה</span> he did so. Ib. 63ᵃ <span dir=\"rtl\">פסקו ליה וכ׳</span> they made arrangements for him for six years (to remain at college). <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">אנן פּסְקִינָן פרנה</span> we shall make up the dowry by subscription (v. <a href=\"#\" data-headword=\"פְּסַס\">פְּסַס</a>); <span class=\"citation\">Yalk. ib. 665</span>; a. fr.</div><div class=\"sense\"><b>—5)</b> <i>to decide, adjudge</i>. <span class=\"citation\">Targ. I Kings XX, 40</span>. <span class=\"citation\">Targ. Job XXXVIII, 10</span>; a. e.—<span class=\"citation\">Succ. 29ᵇ</span>, a. e. <span dir=\"rtl\">קא פסיק ותני לא שנא וכ׳</span> the editor of the Mishnah decides and teaches; i.e. speaks absolutely, drawing no distinction whether &amp;c. <span class=\"citation\">Gitt. 86ᵇ</span> <span dir=\"rtl\">לא פְסִיקָא ליה</span> it was not decided with him, i.e. he could not state it absolutely; a. fr.</div><div class=\"sense\"><b>—6)</b> <i>to close</i>; <span dir=\"rtl\">פ׳ סידרא</span> <i>to close the reading from the Pentateuch, read the Hafṭarah</i>. <span class=\"citation\">Yoma 87ᵃ</span>; a. e., v. <a href=\"#\" data-headword=\"סִדְרָא\">סִדְרָא</a>.</div><div class=\"sense\"><b>—7)</b>  (denom. of <a href=\"#\" data-headword=\"פְּסוּקָא\">פְּסוּקָא</a>) <i>to recite a verse</i>, v. <a href=\"#\" data-headword=\"פָּסַק\">preced.</a> a. <a href=\"#\" data-headword=\"פְּסוּקָא\">פְּסוּקָא</a>.</div><div class=\"sense\"><b>Af. אַפְסֵיק</b> <div class=\"sense\"><b>1)</b> <i>to sever, break, burst</i>. <span class=\"citation\">Targ. Nah. I, 13</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to separate, interpose, divide off</i>. <span class=\"citation\">Targ. Hos. II, 8</span>; a. e.—<span class=\"citation\">Meg. 2ᵇ</span> אתא את ואַפְסְקיה וכ׳ Ms. M. (ed. <span dir=\"rtl\">ופסק</span>, <span dir=\"rtl\">ופסיק</span>) the <i>eth</i> (<span dir=\"rtl\">וְאֵת</span>, <span class=\"citation\">Esth. IX, 21</span>) comes to divide the sentence (giving it the meaning) that some celebrate the fourteenth and others the fifteenth of Adar. <span class=\"citation\">B. Kam. 65ᵇ</span> <span dir=\"rtl\">את פַּסְקֵיה קרא</span> with <i>eth</i> (<span dir=\"rtl\">ואת</span>, <span class=\"citation\">Lev. V, 25</span>) the text separates the clause from the preceding, opp. <span dir=\"rtl\">ערביה</span> combines it; <span class=\"citation\">Yalk. Lev. 479</span> את אַפְסְקֵיה <i>eth</i> separates it; <span class=\"citation\">ib.</span> <span dir=\"rtl\">לאַפְסוּקֵי בין ממון וכ׳</span> (not <span dir=\"rtl\">לאפסוקיה</span>) to draw the line between sacred property and &amp;c. <span class=\"citation\">Sot. 38ᵇ</span> <span dir=\"rtl\">אריכי … לא מַפְסְקֵי</span> tall persons in front of short ones do not form a partition (to intercept the priestly benediction pronounced upon the congregation); <span dir=\"rtl\">תיבה לא מַפְסְקָא</span> nor does the Tebah (v. <a href=\"#\" data-headword=\"תֵּבָה\">תֵּבָה</a>) between the priests and the people form a partition. <span class=\"citation\">Pes. 111ᵃ</span> <span dir=\"rtl\">אַפְסְקִינְהוּ בעפרא</span> he dammed it (the waste water poured out in the street) with dust (spread dust over it); a. fr.—<span class=\"citation\">Keth. 77ᵇ</span>; <span class=\"citation\">17ᵃ</span>, v. infra.]</div><div class=\"sense\"><b>—3)</b> <i>to cut off, cause to cease</i>. <span class=\"citation\">Targ. I Sam. II, 33</span>; a. e.</div><div class=\"sense\"><b>—4)</b> <i>to take the last meal before beginning the fast</i>. <span class=\"citation\">Keth. 63ᵃ</span> לא מר א׳ ולא מר א׳ Ar. (ed. <a href=\"#\" data-headword=\"פְּסַק\">אִיפְּסִיק</a> <i>Ithpe.</i>) neither father nor son partook of the last meal (before the Day of Atonement).</div></div><div class=\"sense\"><b>Ithpe. אִתְפְּסַק  אִיפְּסִיק</b> <div class=\"sense\"><b>1)</b> <i>to be cut, severed, broken off</i>. <span class=\"citation\">Targ. Jud. XVI, 9</span>. <span class=\"citation\">Targ. Is. LII, 2</span>; a. fr.—<span class=\"citation\">Sabb. 112ᵃ</span> <span dir=\"rtl\">איפסיק ליה רצועה</span> (read: <a href=\"#\" data-headword=\"פְּסַק\">אִיפְּסִיקָא</a>) a strap of his shoe broke. Y. ib. VI, 8ᵃ bot. <span dir=\"rtl\">אי׳ סנדליה וכ׳</span> R. Aḥa’s sandal fell off (the strap was broken). <span class=\"citation\">Ḥull. 51ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be interposed, to divide off</i>. <span class=\"citation\">Keth. 17ᵃ</span> <span dir=\"rtl\">א׳ עמודא דנורא וכ׳</span> a column of fire was interposed between the bier of &amp;c.; <span dir=\"rtl\">וגמירי דלא אפסיק וכ׳</span> (read: <span dir=\"rtl\">מִפְּסִיק</span>) and there is a tradition that such a phenomenon occurs only for one person in a generation &amp;c.; ib. 77ᵇ <a href=\"#\" data-headword=\"פְּסַק\">אִפְּסִיק</a>, <span dir=\"rtl\">מִפְּסִיק</span>.</div><div class=\"sense\"><b>—3)</b> <i>to take the last meal</i>, v. supra.</div></div>","alt":["פְּסֵיק"]},"23176":{"h":"פֶּסֶק","r":"Q01352","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּסַק\">preced.</a>) <i>detached piece, remainder.</i> <i>—</i> Pl. <span dir=\"rtl\">פְּסָקִים</span>, constr. <span dir=\"rtl\">פִּסְקֵי</span>, <a href=\"#\" data-headword=\"פְּגִימִין\">פִּי׳</a>. <span class=\"citation\">Kil. VI, 6</span> <span dir=\"rtl\">פ׳ עריס</span>, v. <a href=\"#\" data-headword=\"עָרִיס I\"><span dir=\"rtl\">עָרִיס</span> I</a>; <span class=\"citation\">Tosef. ib. IV, 8</span>; Y. ib. VI, end, 30ᶜ; a. e.—2) <i>disjunction</i>, esp. <i>peseḳ</i> (Chald. <i>p’siḳ</i>), a disjunctive sign (|) between two words. <span class=\"citation\">Ex. R. s. 2</span> <span dir=\"rtl\">אתה מוצא באברהם אברהם יש בו פ׳</span> you will find in ‘Abraham Abraham’ (<span class=\"citation\">Gen. XXII, 11</span>) there is a <i>peseḳ</i>; in ‘Jacob Jacob’ (ib. XLVI, 2) there is a <i>peseḳ</i>; in ‘Samuel Samuel’ (<span class=\"citation\">I Sam. III, 10</span>) &amp;c.; <span dir=\"rtl\">משה משה אין בו פ׳</span> but in ‘Moses Moses’ (<span class=\"citation\">Ex. III, 4</span>) there is no <i>peseḳ.—</i> Pl. as ab. <span dir=\"rtl\">פסקי טעמים</span> <i>the division of words into clauses in accordance with the sense, punctuation</i>. <span class=\"citation\">Meg. 3ᵃ</span> (ref. to <span class=\"citation\">Neh. VIII, 8</span>) <span dir=\"rtl\">ויבינו במקרא אלו פ׳ ט׳</span> ‘and they taught how to understand the Scripture’, this refers to the division of clauses &amp;c.; <span class=\"citation\">Ned. 37ᵇ</span> <a href=\"#\" data-headword=\"פִּיסּוּק\">פִּיסּוּק</a>.—V. <a href=\"#\" data-headword=\"פִּיסָּק\">פִּיסָּק</a>.</div>","alt":[]},"23177":{"h":"פִּסְקָא","r":"Q01353","html":"<div class=\"sense\"><b>1)</b> <i>cut</i>. <span class=\"citation\">Ḥull. 112ᵃ</span> <span dir=\"rtl\">גריר לבי פִסְקֵיה וכ׳</span> he may scrape off the place where it was cut, and eat it. <span class=\"citation\">B. Mets. 23ᵇ</span> אית ליה סימנא בפִסְקֵיה Ms. F. (ed. <span dir=\"rtl\">דאיכא … בפסקא</span>, v. Rabb. D. S. a. l. note 5) when he can identify it by his way of chopping.—[<span class=\"citation\">Ḥull. 51ᵃ</span> <span dir=\"rtl\">מחיי אפסקיה</span>, v. <a href=\"#\" data-headword=\"פַּסְקִית\">פַּסְקִית</a>.]—Pl. <span dir=\"rtl\">פִּסְקֵי</span>, <a href=\"#\" data-headword=\"פְּגִימִין\">פִּי׳</a>. <span class=\"citation\">Erub. 3ᵃ</span> <span dir=\"rtl\">פ׳ דארזא</span> (cmp. <a href=\"#\" data-headword=\"בְּקַעַת\">בְּקַעַת</a>) cedar <i>logs</i>.—[<span class=\"citation\">Y. Kil. IX, end, 32ᵈ</span> <span dir=\"rtl\">פיסקי דעמר</span>, v. <a href=\"#\" data-headword=\"פְּסִיקְיָא\">פְּסִיקְיָא</a>.]</div><div class=\"sense\"><b>—2)</b> <i>interruption, broken line; space indicating a new section, paragraph.</i> <i>—</i> Pl. <span dir=\"rtl\">פִּסְקִין</span>, <span dir=\"rtl\">פִּסְקֵי</span>, <a href=\"#\" data-headword=\"פְּגִימִין\">פִּי׳</a>. <span class=\"citation\">R. Hash. 26ᵇ</span>; <span class=\"citation\">Meg. 18ᵃ</span> <span dir=\"rtl\">והוו עיילי פ׳ פ׳</span> they came to Rabbi’s house in broken lines (Y. ib. II, beg. 73ᵃ <span dir=\"rtl\">קטעין קטעין</span>), v. <a href=\"#\" data-headword=\"סֵירוּג\">סֵירוּג</a>.—<span class=\"citation\">Y. Sabb. I, 3ᵇ</span> bot. (expl. <span dir=\"rtl\">ראשי פרקים</span>) <a href=\"#\" data-headword=\"פ׳\">פ׳</a> the places in the scroll where the portions, into which the Sabbath reading is divided, begin.</div><div class=\"sense\"><b>—3)</b> <i>detached part.—Pl.</i> as ab. <span class=\"citation\">B. Bath. 68ᵇ</span> <span dir=\"rtl\">פיסקי בגי</span>, v. <a href=\"#\" data-headword=\"בִּיזְלֵי\">בִּיזְלֵי</a>.</div><div class=\"sense\"><b>—4)</b> <i>decision, decree</i>. Ib. 130ᵇ <span dir=\"rtl\">פ׳ דדינא</span> (Ms. R. <span dir=\"rtl\">פְּסַק דינא</span>, v. Rabb. D. S. a. l. note 40) legal decision, v. <a href=\"#\" data-headword=\"פִּירְכָא\">פִּירְכָא</a>. <span class=\"citation\">Kidd. 70ᵃ</span>, v. <a href=\"#\" data-headword=\"הַזְמָנָא\">הַזְמָנָא</a>; a. e.; v. <a href=\"#\" data-headword=\"פִּיתַק\">פִּיתְקָא</a>.</div><div class=\"sense\"><b>—5)</b> <i>an absolute, unqualified opinion</i> or <i>statement</i>. <span class=\"citation\">Keth. 76ᵇ</span>, a. fr. <span dir=\"rtl\">ומאי פ׳</span> how can you say this without any qualification?</div><div class=\"sense\"><b>—6)</b> <i>last meal before beginning to fast</i>. <span class=\"citation\">Y. Ḥall. I, 57ᶜ</span> top; <span class=\"citation\">Y. R. Hash. I, 57ᵇ</span> bot. <span dir=\"rtl\">אַפְּסַק כרובא</span>, v. <a href=\"#\" data-headword=\"כְּרוּבָּא\">כְּרוּבָּא</a>.</div><div class=\"sense\"><b>—7)</b> <i>donation, collection</i>, v. <a href=\"#\" data-headword=\"פִּסְקָה\">פִּסְקָה</a>.—[<a href=\"#\" data-headword=\"פִּסְקָא\">פסקא</a>, <span dir=\"rtl\">פי׳</span> (abbrev. <span dir=\"rtl\">פיס׳</span>) <i>section, a</i>) heading in Talm. Y., subordinate to <span dir=\"rtl\">מתני׳</span>.—<i>b</i>) headings of sections in P’siḳta.]</div>","alt":["פִּי׳"]},"23178":{"h":"פִּסְקָאוֹת","r":"Q01354","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּסְקָיוֹת\">פִּסְקָיוֹת</a>.—[פסקאות <span class=\"citation\">Num. R. s. 12</span>; Sifré ib. 45, v. <a href=\"#\" data-headword=\"אִסְקְפַסְטִי\">אִסְקְפַסְטִי</a>.]</div>","alt":[]},"23179":{"h":"פִּסְקָה","r":"Q01355","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>) </div><div class=\"sense\"><b>1)</b> <i>subscription, collection</i>. <span class=\"citation\">Deut. R. s. 4</span> <span dir=\"rtl\">עשה שם ר&quot;ל פ׳ וכ׳</span> (some ed. <a href=\"#\" data-headword=\"פִּסְקָא\">פסקא</a>) Resh Laḳish arranged there a subscription, and he (Abin) gave as much as the entire assembly.</div><div class=\"sense\"><b>—2)</b> <i>division</i>, esp. <i>hemistich, half-verse</i>. <span class=\"citation\">Num. R. s. 13</span> (ref. to <span class=\"citation\">Ps. XIX, 8-10</span>) [read:] <span dir=\"rtl\">שלשה פסוקים … והן מן שתים שתים פִּסְקוֹת וכל פ׳ ופ׳ מן וכ׳</span> three verses … each consisting of two hemistichs, and each hemistich containing five words.—Pl. <a href=\"#\" data-headword=\"פִּסְקוֹן\">פִּסְקוֹת</a>. Ib.</div>","alt":[]},"23180":{"h":"פסקה","r":"Q01356","html":"<div class=\"sense\"> pr. n. pl., v. <a href=\"#\" data-headword=\"פַּסְקַת\">פַּסְקַת</a></div>","alt":[]},"23181":{"h":"פִּסְקוֹן","r":"Q01357","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיסְקוֹן\">פִּיסְקוֹן</a></div>","alt":["פִּסְקוֹנִית"]},"23182":{"h":"פְּסַקְטֵר","r":"Q01358","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסַכְתֵּר\">פְּסַכְתֵּר</a></div>","alt":[]},"23183":{"h":"פְּסִקְיָא","r":"Q01359","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסִיקְיָא\">פְּסִיקְיָא</a></div>","alt":[]},"23184":{"h":"פִּסְקָיוֹת","r":"Q01360","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>) <i>divisions, parties</i>. <span class=\"citation\">Lev. R. s. 33</span> <span dir=\"rtl\">כשהייתם … נעשים פ׳ פ׳ לע&quot;ז</span> (Ar. <a href=\"#\" data-headword=\"פִּסְקָאוֹת\">פִּסְקָאוֹת</a>) when you lived in your own land, you formed parties for the various idols (with play on <span dir=\"rtl\">ותפשקי</span>, <span class=\"citation\">Ez. XVI, 25</span>); Yalk. Dan. 1061.</div>","alt":[]},"23185":{"h":"פסקינון","r":"Q01361","html":"<div class=\"sense\">, <span class=\"citation\">Y. Yoma III, 41ᵃ</span> top, v. <a href=\"#\" data-headword=\"פִּיקְסִינָה\">פִּיקְסִינָה</a></div>","alt":["פסקינין"]},"23186":{"h":"פַּסְקִית","r":"Q01362","html":"<div class=\"sense\"> adv. (<a href=\"#\" data-headword=\"פְּסַק\">פְּסַק</a>) <i>in the wag of chopping, across</i>. <span class=\"citation\">Ḥull. 51ᵃ</span> אי מחייה פ׳ Ar. (Ms. M. <span dir=\"rtl\">אַפַּסְקִית</span>; ed. <span dir=\"rtl\">מחיי אפסקיה</span>, corr. acc.) if he struck her with the stick across her back.</div>","alt":[]},"23187":{"h":"פסקן","r":"Q01363","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיסָּק\">פִּיסָּק</a></div>","alt":["פסקנין"]},"23188":{"h":"פִּסְקָנִית","r":"Q01364","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיסְקוֹן\">פִּיסְקוֹן</a></div>","alt":[]},"23189":{"h":"פַּסְקַת","r":"Q01365","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Pasḳath</i> (<i>Failing</i>; transl. of b. h. <span dir=\"rtl\">כְּוִיב</span>, v. <a href=\"#\" data-headword=\"כָּזַב\">כָּזַב</a>). <span class=\"citation\">Targ. Y. I Gen. XXXVIII, 5</span> <span dir=\"rtl\">והוה בפ׳</span> (Y. II <span dir=\"rtl\">והוה דפסקא</span>, corr. acc.); <span class=\"citation\">Gen. R. s. 85</span> <span dir=\"rtl\">כזיב פ׳</span> (<span dir=\"rtl\">שם מקום</span>) (some ed. <a href=\"#\" data-headword=\"פסקה\">פסקה</a>) Kezib is P. (name of a place); <span class=\"citation\">Yalk. ib. 144</span>.—Cmp. <a href=\"#\" data-headword=\"פְּסָאקָא\">פְּסָאקָא</a>.</div>","alt":[]},"23190":{"h":"פְּסַקְתֵּר","r":"Q01366","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּסַכְתֵּר\">פְּסַכְתֵּר</a></div>","alt":[]},"23191":{"h":"פִּסְּתָא","r":"Q01367","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיסְּתָא\">פִּיסְּתָא</a></div>","alt":[]},"23192":{"h":"צְדָדָא","r":"R00086","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Num. XIX, 14</span> <span dir=\"rtl\">צִדְדֵיה</span> (v. <span class=\"citation\">Sifré Num. 126</span>, quot. in <a href=\"#\" data-headword=\"צְדָד\">preced.</a>).—Pl. <span dir=\"rtl\">צְדָדִין</span>, v. preced.—[Y. Sabb. VII, 10ᵃ bot. <span dir=\"rtl\">מתברא בצדדיא</span>, read: <span dir=\"rtl\">מבחרא בצרריא</span>, v. <a href=\"#\" data-headword=\"צְרָרָא II\"><span dir=\"rtl\">צְרָרָא</span> II</a>.]</div>","alt":[]},"23193":{"h":"צָדָה","r":"R00087","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צדי\">צדי</a>.—[<span class=\"citation\">Yalk. Lev. 587</span> <span dir=\"rtl\">ואומר לו צדה</span>, read: <a href=\"#\" data-headword=\"צְרַח I\">צְרַח</a>, v. <a href=\"#\" data-headword=\"צָרַח\">צָרח</a>.]</div>","alt":[]},"23194":{"h":"צֵדָה","r":"R00088","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צֵידָה\">צֵידָה</a>, a. <a href=\"#\" data-headword=\"צֵידָא\">צֵידָא</a>.</div>","alt":[]},"23195":{"h":"צֵדוּ","r":"R00089","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"צֵידָה\">צֵידָה</a>, <i>provision, food</i>. <span class=\"citation\">Lev. R. s. 33</span>; <span class=\"citation\">Yalk. ib. 661</span> <span dir=\"rtl\">צ׳ טבא וכ׳</span> the best food in the market.</div>","alt":[]},"23196":{"h":"צָדוּ","r":"R00090","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (צְדֵי II) <i>desolation, confusion, despair</i> (corresp. to h. <a href=\"#\" data-headword=\"שַׁמָּה\">שַׁמָּה</a>). <span class=\"citation\">Targ. Is. XIII, 9</span>. <span class=\"citation\">Targ. Y. II, Deut. XXXII, 10</span> (ed. Vien. <a href=\"#\" data-headword=\"צִירְיָא\">צר׳</a>, corr. acc.). <span class=\"citation\">Targ. Ps. CIX, 10</span> מה הוות צָדוּתְהוֹן Ms. (ed. Lag. <span dir=\"rtl\">צדיתהון</span>; oth. ed. <span dir=\"rtl\">מדהוות צרתהון</span>, corr. acc.). <span class=\"citation\">Targ. O. Deut. XXVIII, 37</span>; a. fr.—Pesik. Naḥ., p. 126ᵇ (Hebr. dict.) <span dir=\"rtl\">מושיבה צ׳</span>, (not <span dir=\"rtl\">צרו</span>), v. <a href=\"#\" data-headword=\"פִּיד\">פִּיד</a>; <span class=\"citation\">Yalk. Job 918</span>. <span class=\"citation\">Lam. R. to I, 13</span> (expl. <span dir=\"rtl\">שוממה</span> a. <span dir=\"rtl\">דוה</span> ib.) <span dir=\"rtl\">שוממה לצ׳ דוה לגרדום</span> <i>shomemah</i> means doomed to desolation, <i>davah</i>, to execution.</div>","alt":["צָדוּתָא"]},"23197":{"h":"צֵדוֹן","r":"R00091","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צִידוֹן\">צִידוֹן</a></div>","alt":["צֵדוֹנִי"]},"23198":{"h":"צִדּוּק","r":"R00092","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צִידּוּק\">צִידּוּק</a></div>","alt":[]},"23199":{"h":"צָדוֹק","r":"R00093","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Zadok</i>, 1) the high priest under David and Solomon.</div><div class=\"sense\"><b>1)</b>  the high priest under David and Solomon. <span class=\"citation\">Yoma 73ᵇ</span>; <span class=\"citation\">Sot. 48ᵇ</span>. <span class=\"citation\">Snh. 21ᵃ</span> <span dir=\"rtl\">מה צ׳ מחצה וכ׳</span> as Z. (the high priest) takes one half of the show-bread &amp;c. <span class=\"citation\">Koh. R. to I, 4</span> (ref. to <span class=\"citation\">I Chr. VI, 34</span>) <span dir=\"rtl\">ללמדך אילו היה אהרן … צ׳ היה וכ׳</span> to teach thee that if Aaron and his sons had been alive (in David’s days), Z. would have been their superior in his time; a. e.</div><div class=\"sense\"><b>—2)</b>  Z., an alleged disciple of Antigonos of Sokho, and founder of the sect of the Sadducees. <span class=\"citation\">Ab. d’R. N. ch. V</span>.—3) R. Z., a Tannai, contemporary with the destruction of the Temple. <span class=\"citation\">Gitt. 56ᵃ</span>, sq. <span class=\"citation\">Yoma 23ᵃ</span>. <span class=\"citation\">Ab. IV, 5</span>; a. fr.—V. Fr. Darkhé, p. 70 sq.</div>","alt":[]}};
